MultiLanguageItemData['it'][137014] = {name = "[q5]Achor, la Fame Eterna", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Torso} {Cuoio}\n8 Armatura\n+5 [Agilità o Intelletto]\n+7 Tempra\n[q2]+ 4 Critico\n[q2]+ 6 Celerità\n[q2]+ 3 Maestria\nIntegrità 200 / 200Classi: Cacciatore di Demoni\n[q2]Equipaggia: Ritiro Vendicativo ti cura del 25% della salute massima e aumenta il ritorno vitale del 20% per 8 s.\n[q]\"I Cacciatori di Demoni hanno una sete di battaglia infinita, così come sono infinite le legioni al comando del loro nemico più odiato.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137015] = {name = "[q5]Ekoporter, Creatore di Mondi", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Torso} {Cuoio}\n8 Armatura\n+5 [Agilità o Intelletto]\n+7 Tempra\n[q2]+ 4 Critico\n[q2]+ 3 Celerità\n[q2]+ 6 Maestria\nIntegrità 200 / 200Classi: Druido\n[q2]Equipaggia: Aumenta gli effetti di Pelle Spessa, Influenza Astrale, Rapidità Felina e Dono di Ysera del 75%.\n[q]\"Non solo potremo evocare creature, ma anche creare un luogo tutto nostro. E qualunque luogo sia mai esistito... è al servizio del nostro sogno. Ti prego... ascolta con me.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137016] = {name = "[q5]Giubba Perduta di Sal'salabim", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Torso} {Cuoio}\n8 Armatura\n+5 [Agilità o Intelletto]\n+7 Tempra\n[q2]+ 6 Celerità\n[q2]+ 4 Maestria\nIntegrità 200 / 200Classi: Monaco\n[q2]Equipaggia: Lancio del Barile azzera il tempo di recupero restante di Soffio di Fuoco.\n[q]\"Sal'salabim potrebbe averla persa quando è svenuto per sei ore...\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137017] = {name = "[q5]Pettorale Corazzato della Val'kyr Dorata", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Torso} {Piastre}\n18 Armatura\n+5 [Forza o Intelletto]\n+7 Tempra\n[q2]+ 6 Celerità\n[q2]+ 4 Versatilità\nIntegrità 200 / 200Classi: Paladino\n[q2]Equipaggia: Ogni nemico colpito da Scudo del Vendicatore riduce il tempo di recupero restante di Guardiano dei Re Antichi di 3 s.\n[q]\"Ciò che resta di un grande comandante, sceso sui suoi nemici dai cieli, splendente della luminosità del sole.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137018] = {name = "[q5]Manipolatore del Destino", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Torso} {Piastre}\n18 Armatura\n+5 [Forza o Intelletto]\n+7 Tempra\n[q2]+ 6 Celerità\n[q2]+ 4 Maestria\nIntegrità 200 / 200Classi: Guerriero\n[q2]Equipaggia: Gli attacchi intercettati forniscono a te e al bersaglio intercettato uno scudo che assorbe danni subiti pari al 50% dei danni inflitti dall'attacco per 10 s.\n[q]\"Piega il tempo stesso per proteggere il mondo dalla devastazione.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137019] = {name = "[q5]Cenedril, Specchio dell'Odio", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\nSchiena\n3 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 4 Celerità\n[q2]+ 2 Maestria\nClassi: Monaco\n[q2]Equipaggia: Aumenta i danni inflitti da Tocco del Karma del 150%.\n[q]\"Se conosci il tuo nemico e te stesso, non devi temere il risultato di cento battaglie.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137020] = {name = "[q5]Sussurro del Nathrezim", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\nSchiena\n3 Armatura\n+3 [Forza o Intelletto]\n+4 Tempra\n[q2]+ 4 Critico\n[q2]+ 2 Celerità\nClassi: Paladino\n[q2]Equipaggia: Verdetto dei Templari e Tempesta Divina aumentano i danni inflitti dal successivo Verdetto dei Templari o Tempesta Divina lanciato entro 4 s del 15%.\n[q]\"Patetico. Tutto qui quello che sai fare?\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137021] = {name = "[q5]Inganno del Signore del Terrore", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\nSchiena\n3 Armatura\n+3 Agilità\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Maestria\nClassi: Ladro\n[q2]Equipaggia: Scaltrezza\n Ogni 2 s, aumenta i danni inflitti dal successivo Tempesta di Shuriken del 25%. Si accumula fino a 30 volte.\n\nAssassinio, Fuorilegge\n Ogni 2 s, aumenta i danni inflitti dal successivo Ventaglio di Lame del 35%. Si accumula fino a 30 volte.\n[q]\"Ti aspettavo, giovane principe. Io sono Mal'Ganis. Come vedi, la tua gente ora è MIA...\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137022] = {name = "[q5]Sacrificio di Loramus Thalipedes", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Piedi} {Cuoio}\n5 Armatura\n+4 [Agilità o Intelletto]\n+6 Tempra\n[q2]+ 3 Critico\n[q2]+ 5 Celerità\nIntegrità 95 / 95Classi: Cacciatore di Demoni\n[q2]Equipaggia: Vilscatto infligge il 10% di danni aggiuntivi per ogni bersaglio colpito.\n[q]\"Questi stivali sono l'unica cosa rimasta dopo che il Pugnale di Pietra del Sigillo intrappolò Rakh'likh nel corpo di Loramus il Profanato.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137023] = {name = "[q5]Promessa di Elune, Dea della Luna", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Piedi} {Cuoio}\n5 Armatura\n+4 [Agilità o Intelletto]\n+6 Tempra\n[q2]+ 4 Celerità\n[q2]+ 3 Maestria\nIntegrità 95 / 95Classi: Druido\n[q2]Equipaggia: Aumenta i danni inflitti da Ira Solare e Ira Lunare del 8% e fornisce l'effetto Potere di Elune, aumentando le cure fornite dalla successiva Ricrescita del 30% e riducendone il tempo di lancio del 5%. Si accumula fino a 20 volte.\n[q]\"Quando gli altri ricevono la vita e l'energia da te, anche tu ricevi vita ed energia da me.\"\nPrezzo di vendita:"}
