MultiLanguageItemData['it'][137046] = {name = "[q5]Ilterendi, Corona Ingioiellata di Lunargenta", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 8 Critico\n[q2]+ 6 Maestria\n\n[q0]Incavo Prismatico\n\nClassi: Paladino\n[q2]Equipaggia: Giudizio aumenta tutte le cure da te fornite del 15% per 5 s.\n[q]\"Lunargenta fu costruita con pietra bianca e adornata con arazzi rossi. Tuttavia, la fama della città non deriva solo dalla sua bellezza, ma dal fatto che è sede degli studi di magia e dei maestri manipolatori del mana.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137047] = {name = "[q5]Immortalità di Heathcliff", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 8 Celerità\n[q2]+ 6 Maestria\n\n[q0]Incavo Prismatico\n\nClassi: Paladino\n[q2]Equipaggia: Riduce del 4% i danni subiti quando ci si trova nell'area d'effetto di Consacrazione.\n[q]\"Heathcliff, l'Oggetto Immortale che si diceva fosse immune ai danni gravi. Alcuni raccontavano che la forza del Cavaliere del Sangue trascendeva le leggi naturali del mondo.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137048] = {name = "[q5]Furia Scatenata di Liadrin", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 8 Critico\n[q2]+ 6 Celerità\n\n[q0]Incavo Prismatico\n\nClassi: Paladino\n[q2]Equipaggia: Ira Vendicatrice fornisce 1 carica di potere sacro ogni 6 s.\n[q]\"Siamo stati traditi dall'uomo che chiamavamo Principe. Giuro che le spade dei miei Cavalieri del Sangue saranno votate alla sconfitta di Kil'jaeden e alla restaurazione di Lunargenta. Combatteremo al tuo fianco, A'dal.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137049] = {name = "[q5]Insegna di Corvolesto", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 9 Critico\n[q2]+ 5 Celerità\n\n[q0]Incavo Prismatico\n\nClassi: Ladro\n[q2]Equipaggia: Gli attacchi a bersaglio singolo che forniscono punti combo infliggono il 15% di danni aggiuntivi come danni da ombra a tutti i bersagli frontali entro 15 m.\n[q]\"Un'insegna consegnata solamente a coloro che hanno dimostrato maestria con le ombre e che hanno ucciso al servizio di Corvolesto.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137050] = {name = "[q5]Occhio della Distorsione Fatua", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 9 Celerità\n[q2]+ 5 Maestria\n\n[q0]Incavo Prismatico\n\nClassi: Sciamano\n[q2]Equipaggia: Infliggere danni da fuoco, da gelo o da natura aumenta tutti i danni da te inflitti del 1.5% per 8 s. Ogni elemento si accumula separatamente.\n[q]\"Nel Fatuo, anche se gli elementi naturali sono corrotti e appena riconoscibili, il loro potere è senza eguali.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137051] = {name = "[q5]Focalizzatore di Jonat, l'Anziano", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 9 Critico\n[q2]+ 5 Celerità\n\n[q0]Incavo Prismatico\n\nClassi: Sciamano\n[q2]Equipaggia: Ondata di Cura ed Eruzione Benefica aumentano le cure fornite dalla successiva Catena di Guarigione del 10%. Si accumula fino a 5 volte.\n[q]\"Con l'addestramento di Jonat Han, i nuovi Sciamani degli Scorticadraghi apprendevano la maestria delle acque, per curare uno e tanti.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137052] = {name = "[q5]Cuore di Pietra di Ayala", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 8 Critico\n[q2]+ 6 Maestria\n\n[q0]Incavo Prismatico\n\nClassi: Guerriero\n[q2]Equipaggia: Gli attacchi hanno una probabilità di rendere la successiva Esecuzione priva di costo in rabbia e utilizzabile su qualsiasi bersaglio, a prescindere dalla sua percentuale di salute.\n[q]\"Nelle fosse delle Sale del Valore, Ayala l'Implacabile uccise innumerevoli nemici, entrando nella leggenda. Era davvero terrificante da guardare, e più i suoi nemici si indebolivano, più diventava crudele.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137053] = {name = "[q5]Kazzalax, Furia di Fujieda", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\nSchiena\n3 Armatura\n+3 Forza\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Maestria\nClassi: Guerriero\n[q2]Equipaggia: Sete di Sangue aumenta tutti i danni inflitti e le cure ricevute del 1% per 10 s. Si accumula fino a 4 volte.\n[q]\"I Jinyu raccontano di un grande guerriero, Fujieda, che uccise un demone vile dopo averlo atteso per ore in una pozza poco profonda.\"\nPrezzo di vendita:"}
