MultiLanguageItemData['it'][137089] = {name = "[q5]Vigore della Divinità del Tuono", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Fianchi} {Piastre}\n10 Armatura\n+4 [Forza o Intelletto]\n+6 Tempra\n[q2]+ 5 Celerità\n[q2]+ 3 Versatilità\nIntegrità 70 / 70Classi: Guerriero\n[q2]Equipaggia: Ogni nemico colpito da Schianto del Tuono riduce il tempo di recupero restante di Urlo Demoralizzante di 3 s.\n[q]\"E il dio del tuono folgorò i trasgressori con tutta la sua furiosa vendetta...\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137090] = {name = "[q5]Stabilizzatori Bionici dei Mo'arg", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 4 Critico\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Cacciatore di Demoni\n[q2]Equipaggia: I danni inflitti da Lancio Lama aumentano del 25% per ogni nemico colpito.\n[q]\"Se si può stabilizzare una sega, si può stabilizzare una lama.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137091] = {name = "[q5]Avambracci Perduti del Profanatore", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 2 Celerità\n[q2]+ 3 Maestria\n[q2]+ 3 Elusione\nIntegrità 70 / 70Classi: Cacciatore di Demoni\n[q2]Equipaggia: Fendente d'Anima riduce il tempo di recupero restante di un Sigillo casuale di 8 s. (500ms di recupero)\n[q]\"Mentre Razelikh era in battaglia con Loramus Thalipedes in cima alle Alture del Profanatore, questi bracciali fecero volare i suoi polsi verso il Portale Oscuro.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137092] = {name = "[q5]Intuizione di Oneth", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Celerità\nIntegrità 70 / 70Classi: Druido\n[q2]Equipaggia: Cometa Arcana e Pioggia di Stelle hanno ciascuna una probabilità del 20% di azzerare il costo dell'altra. (Possibilità di Apparire:20%)\n[q]\"Aglaya avrebbe chiamato questi bracciali Tracotanza di Oneth.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137094] = {name = "[q5]Bracciali del Selvatico", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Mani} {Cuoio}\n5 Armatura\n+4 [Agilità o Intelletto]\n+6 Tempra\n[q2]+ 4 Critico\n[q2]+ 3 Celerità\nIntegrità 70 / 70Classi: Druido\n[q2]Equipaggia: I danni critici degli effetti di sanguinamento hanno una probabilità del 30% di attivare Furia Primordiale. (Possibilità di Apparire:30%)\n[q]\"I Druidi corrotti dei Proleselva speravano un giorno di avere il potere che Alzzin aveva infuso in questi bracciali.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137095] = {name = "[q5]Edraith, Vincoli di Aglaya", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Celerità\nIntegrità 70 / 70Classi: Druido\n[q2]Equipaggia: Guarigione Immediata estende la durata dei tuoi effetti di cura periodici sul bersaglio di 10 s.\n[q]\"Realizzati con la pelle di un antico toro, benedetto da un costante umore di felicità eterna.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137096] = {name = "[q5]Profumo di Pioggia Omaggio", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 4 Celerità\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Monaco\n[q2]Equipaggia: Il tempo di recupero restante di Palingenesi si riduce di 2.0 s ogni volta che viene lanciata Nebbia Curativa.\n[q]\"Ah... C'è odore di pioggia oggi.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137097] = {name = "[q5]Copertura del Corno per Libagioni", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 2 Critico\n[q2]+ 4 Celerità\nIntegrità 70 / 70Classi: Monaco\n[q2]Equipaggia: La durata di Tempesta, Terra e Fuoco aumenta di 0.4 s per ogni chi consumato. (100ms di recupero)\n[q]\"I vigorosi Vrykul di Nordania erano in grado di resistere a tutti gli elementi... avendo abbastanza da bere.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137098] = {name = "[q5]Catene da Allenamento della Famiglia Zoldyck", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 2 Celerità\n[q2]+ 4 Maestria\nIntegrità 70 / 70Classi: Ladro\n[q2]Equipaggia: Aumenta del 30% i danni da sanguinamento e da veleno inflitti ai bersagli con meno del 30% di salute restante.\n[q]\"I membri della famiglia Zoldyck vengono addestrati sin dalla nascita nell'arte dell'assassinio. Nei sotterranei delle loro proprietà, imparano a resistere agli effetti dei veleni mortali e a padroneggiarne l'uso.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137099] = {name = "[q5]Polsiere Fradice di Pelleverde", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Celerità\nIntegrità 70 / 70Classi: Ladro\n[q2]Equipaggia: In Mezzo agli Occhi ha una probabilità del 20% per punto combo di aumentare i danni inflitti dal successivo Colpo di Pistola del 200%.\n[q]\"In un mondo senza legge pieno di risse da taverna e duelli improvvisati, la precisione è di importanza vitale.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137100] = {name = "[q5]Ripudio dei Mezzo-Giganti", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 2 Critico\n[q2]+ 4 Maestria\nIntegrità 70 / 70Classi: Ladro\n[q2]Equipaggia: Le mosse risolutive estendono la durata di Lame d'Ombra di 0.2 s per ogni punto combo consumato.\n[q]\"Se pensate che un Tauren che cerca di nascondersi sia ridicolo, dovreste vedere uno di quei giganti Vrykul che cerca di muoversi furtivamente in pieno giorno!\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137101] = {name = "[q5]Richiamo Selvaggio", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Maglia}\n6 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Celerità\nIntegrità 70 / 70Classi: Cacciatore\n[q2]Equipaggia: Riduce il tempo di recupero di tutti gli Aspetti del 35%.\n[q]\"I Cacciatori hanno una connessione profonda con tutto ciò che è selvatico: possono invocare gli aspetti animali per potenziarsi e fare amicizia anche con la più selvaggia delle bestie.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137102] = {name = "[q5]Acrimonia di Al'Akir", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Maglia}\n6 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 3 Celerità\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Sciamano\n[q2]Equipaggia: I danni inflitti da Catena di Fulmini aumentano del 5% a ogni bersaglio successivo.\n[q]\"Il potere del fulmine ancora attraversa queste manette. Ti senti onnipotente e questa sensazione non fa che crescere...\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137103] = {name = "[q5]Cintura delle Tempeste", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Fianchi} {Maglia}\n7 Armatura\n+4 [Agilità o Intelletto]\n+6 Tempra\n[q2]+ 4 Critico\n[q2]+ 3 Celerità\nIntegrità 70 / 70Classi: Sciamano\n[q2]Equipaggia: I nemici colpiti da Assalto della Tempesta diventano caricati elettricamente per 15 s e folgorano ogni 1 s un nemico vicino, infliggendo 5% danni da natura.\n[q]\"Realizzata con le scaglie di un antico Drago della Tempesta, rilascia una magia incontrollabile tutt'intorno.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137104] = {name = "[q5]Redenzione di Nobundo", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Maglia}\n6 Armatura\n+3 [Agilità o Intelletto]\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Sciamano\n[q2]Equipaggia: Catena di Guarigione riduce il costo in mana della successiva Eruzione Benefica del 50%.\n[q]\"Il Veggente Nobundo ha lasciato la città ferito, ma è tornato potenziato dagli elementi.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137105] = {name = "[q5]Guardia di Uther", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Piastre}\n9 Armatura\n+3 [Forza o Intelletto]\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 3 Celerità\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Paladino\n[q2]Equipaggia: Benedizione della Libertà [ Benedizione del Sacrificio : Benedizione del Sacrificio ] e [ Benedizione della Protezione Magica / Benedizione della Protezione] curano il bersaglio del 15% della sua salute massima e durano il 50% in più.\n[q]\"Uther l'Araldo della Luce, capo della Mano d'Argento, comandava con tale presenza sul campo di battaglia che i suoi cavalieri sembravano invincibili e inarrestabili.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137107] = {name = "[q5]Manette dell'Emosuzione di Mannoroth", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Piastre}\n9 Armatura\n+3 [Forza o Intelletto]\n+4 Tempra\n[q2]+ 2 Celerità\n[q2]+ 4 Versatilità\n[q2]+ 3 Maestria\nIntegrità 70 / 70Classi: Guerriero\n[q2]Equipaggia: Rigenera il 1% della tua salute massima ogni 10 rabbia consumata.\n[q]\"Vieni, banchetta con il mio sangue, e presto banchetterai col sangue dei tuoi nemici.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137108] = {name = "[q5]Guanti Lunghi di Elettroscaglie di Kakushan", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Mani} {Piastre}\n10 Armatura\n+4 [Forza o Intelletto]\n+6 Tempra\n[q2]+ 3 Versatilità\n[q2]+ 4 Maestria\nIntegrità 70 / 70Classi: Guerriero\n[q2]Equipaggia: [ Devastatore : Gli attacchi automatici aumentano / Sfondamento aumenta] i danni inflitti e la rabbia generata dal successivo Colpo di Scudo o Schianto del Tuono del 20%.\n[q]\"Il grande guerriero Kakushan li ha creati usando le elettroscaglie dopo che lui e Ivagont avevano devastato i villaggi di Rivafosca. Mentre i Naga fuggivano terrorizzati, i Vrykul bevevano il sangue dei membri della loro tribù.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][137109] = {name = "[q5]X'anshi, Manto dell'Arcivescovo Benedictus", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\nSchiena\n3 Armatura\n+3 Intelletto\n+4 Tempra\n[q2]+ 4 Critico\n[q2]+ 2 Maestria\nClassi: Sacerdote\n[q2]Equipaggia: Al termine di Spirito di Redenzione, si rinasce con una percentuale di salute che varia in base a quanto si è stati efficaci durante Spirito della Redenzione, fino a un massimo del 100%. Dopo essere rinati, non si può beneficiare dell'effetto per 10 min.\n[q]\"È possibile farcela senza mai tradire?\"\nPrezzo di vendita:"}
