MultiLanguageItemData['it'][139533] = {name = "Supplica Bruciacchiata", additional_info = "Si vincola alla raccolta\nUnico\nQuesto oggetto avvia una missione\n[q]\"I bordi sembrano bruciati dalla vilmagia. Al centro c'è un messaggio scarabocchiato.\""}
MultiLanguageItemData['it'][139534] = {name = "Lettera Insanguinata", additional_info = "Si vincola alla raccolta\nUnico\nQuesto oggetto avvia una missione\n[q]\"Un messaggio scritto frettolosamente col sangue su un pezzo di stoffa.\""}
MultiLanguageItemData['it'][139535] = {name = "Preghiera Insanguinata", additional_info = "Si vincola alla raccolta\nUnico\nQuesto oggetto avvia una missione\n[q]\"Un messaggio scritto frettolosamente col sangue su un pezzo di stoffa.\""}
MultiLanguageItemData['it'][139536] = {name = "[q6]Emanazioni dei Venti", additional_info = "Si vincola alla raccolta\nUnicoClassi: Ladro\n[q2]Usa: Sblocca l'aspetto Furiatonante, Lama Santificata del Signore del Vento per l'Artefatto Lame dell'Oscurità .\n[q]\"I segreti del potere elementale sono custoditi all'interno della famosa lama di Tuonelaar il Vento Eterno.\""}
MultiLanguageItemData['it'][139537] = {name = "Treccia del Re delle Profondità", additional_info = "Oggetto di missione\n[q]\"Questa magica treccia sciamanica è stata indossata da ognuno dei Re delle Profondità fin dai tempi antichi.\""}
MultiLanguageItemData['it'][139538] = {name = "Frusta dell'Incubo", additional_info = "Oggetto di missione\n[q]\"Questa frusta è stata creata con l'energia oscura di Xavius stesso.\""}
MultiLanguageItemData['it'][139539] = {name = "Antica Lama degli Abiskorn", additional_info = "Oggetto di missione\n[q]\"L'arma venerata dai guerrieri Abiskorn ormai caduti da tempo.\""}
MultiLanguageItemData['it'][139540] = {name = "Pagina di Diario di Aponi", additional_info = "Oggetto di missione\n[q]\"Scritta in fretta.\""}
MultiLanguageItemData['it'][139541] = {name = "Sigillo del Comando", additional_info = "Oggetto di missione\n[q2]Usa: Ti teletrasporta nel mondo demoniaco di Niskara. (3 S Recupero)\n[q]\"Si illumina in presenza del portale della Legione.\""}
MultiLanguageItemData['it'][139542] = {name = "[q0]Striscia di Tessuto Marino", additional_info = "Si vincola alla raccolta\n[q]\"Forse nemmeno un sarto potrebbe usarla.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][139543] = {name = "[q0]Timone Rotto", additional_info = "Si vincola alla raccolta\n[q]\"Potrebbe essere recuperato da un carpentiere navale di talento.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][139544] = {name = "[q0]Stendardo di Guerra Consumato degli Abiskorn", additional_info = "Si vincola alla raccolta\n[q]\"Una volta sventolava con orgoglio sugli alberi delle navi dei Vrykul.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][139545] = {name = "[q0]Campana Arrugginita del Marinaio", additional_info = "Si vincola alla raccolta\n[q]\"Utilizzata per segnalare altre navi in caso di nebbia fitta.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][139546] = {name = "[q6]Crogiuolo Vorticoso di Anime", additional_info = "Si vincola alla raccolta\nUnicoClassi: Cavaliere della Morte\n[q2]Usa: Sblocca l'aspetto Tocco della Non Morte per l'Artefatto Morso del Dannato .\n[q]\"Un esperimento fallito, il tentativo di rubare magicamente un potere estinto da tempo. La massa risultante si contorce e ondeggia fastidiosamente.\""}
MultiLanguageItemData['it'][139547] = {name = "[q6]Rune dell'Oscuramento", additional_info = "Si vincola alla raccolta\nUnicoClassi: Cavaliere della Morte\n[q2]Usa: Sblocca l'aspetto Lama Runica Oscura per l'Artefatto Lame del Principe Caduto .\n[q]\"Sono scritte in una lingua antica che non ricorda anima viva, eppure in qualche modo senti le parole formarsi nella tua mente, desiderose di essere lette.\""}
MultiLanguageItemData['it'][139548] = {name = "[q6]Gancio dello Spezzaossa", additional_info = "Si vincola alla raccolta\nUnicoClassi: Cavaliere della Morte\n[q2]Usa: Sblocca l'aspetto Spezzaossa per l'Artefatto Apocalisse .\n[q]\"Alimentata dalla robusta energia della Rocca della Corona di Ghiaccio, quest'arma crudele e brutale potrebbe facilmente diventare uno strumento di morte.\""}
MultiLanguageItemData['it'][139549] = {name = "[q6]Maschera del Calcamorte", additional_info = "Si vincola alla raccolta\nUnicoClassi: Cacciatore di Demoni\n[q2]Usa: Sblocca l'aspetto Calcamorte per l'Artefatto Lame Gemelle dell'Incantatore .\n[q]\"Un'arma scura da un maestro da tempo morto, ansiosa di bere nuovamente del sangue.\""}
MultiLanguageItemData['it'][139550] = {name = "[q6]Baluardo della Custode di Ferro", additional_info = "Si vincola alla raccolta\nUnicoClassi: Cacciatore di Demoni\n[q2]Usa: Sblocca l'aspetto Custode di Ferro per l'Artefatto Lame da Guerra degli Aldrachi .\n[q]\"Un tempo un Costrutto indomabile dei Draenei, trasformato dalla Legione in uno strumento di distruzione, il Custode di Ferro cadde tempo fa durante la conquista della terra natale degli Aldrachi.\""}
MultiLanguageItemData['it'][139551] = {name = "[q6]Fiorsole", additional_info = "Si vincola alla raccolta\nUnicoClassi: Druido\n[q2]Usa: Sblocca l'aspetto Presa del Custode del Sole per l'Artefatto Falce di Elune .\n[q]\"Un fiore raro proveniente dal Sogno di Smeraldo, scomparso da Azeroth dall'inizio della Guerra degli Antichi.\""}
MultiLanguageItemData['it'][139552] = {name = "[q6]Piuma dello Spirito Lunare", additional_info = "Si vincola alla raccolta\nUnicoClassi: Druido\n[q2]Usa: Sblocca l'aspetto Spirito Lunare per l'Artefatto the Zanne di Grigiomanto .\n[q]\"Una piuma di un dio selvatico solitario. Con essa, un Druido dell'Unghia potrebbe imparare a padroneggiare una forma mai vista prima.\""}
MultiLanguageItemData['it'][139553] = {name = "[q6]Marchio del Guardiano della Radura", additional_info = "Si vincola alla raccolta\nUnicoClassi: Druido\n[q2]Usa: Sblocca l'aspetto Guardiano della Radura per l'Artefatto the Artigli di Ursoc .\n[q]\"Un marchio potente messo sugli orsi selvatici da Ursol per potenziarli come difensori della natura selvaggia nel momento del bisogno.\""}
MultiLanguageItemData['it'][139554] = {name = "[q6]Ghianda dell'Eternità", additional_info = "Si vincola alla raccolta\nUnicoClassi: Druido\n[q2]Usa: Sblocca l'aspetto Corona del Custode per l'Artefatto G'hanir, l'Albero Madre .\n[q]\"Molte di queste ghiande magiche sono state salvate da uno degli alberi più antichi nel Sogno prima che diventasse l'Incubo.\""}
MultiLanguageItemData['it'][139555] = {name = "[q6]Progetti del Grande Architetto", additional_info = "Si vincola alla raccolta\nUnicoClassi: Cacciatore\n[q2]Usa: Sblocca l'aspetto Presa del Titano per l'Artefatto Titanassalto .\n[q]\"Progetti dettagliati riguardo alla creazione di un arco, un capolavoro tecno-magico che usa una sorgente di potere creata dai titani. Difficile dire come siano arrivati fino agli archivi di Mimiron.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][139556] = {name = "[q6]Note di Syriel Lunacrescente: Guardiacorvo", additional_info = "Si vincola alla raccolta\nUnicoClassi: Cacciatore\n[q2]Usa: Sblocca l'aspetto Guardia del Corvo per l'Artefatto Thas'dorah, Eredità dei Ventolesto .\nRichiedeCorte di Farondis\n- Riverito\n[q]\"Progetti dettagliati per la costruzione di una balestra elegante e potente, persi nel tempo perché i materiali per costruirla non esistevano ancora.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][139557] = {name = "[q6]Ultimo Soffio della Foresta", additional_info = "Si vincola alla raccolta\nUnicoClassi: Cacciatore\n[q2]Usa: Sblocca l'aspetto Fermezza dell'Orso per l'Artefatto Grinfiartiglio, Lancia degli Dei Selvatici .\n[q]\"Ursoc sacrificò la propria vita per le terre selvagge due volte, ma lasciò dietro di sé un'eredità importante per tanti altri nobili difensori in sua assenza.\""}
MultiLanguageItemData['it'][139558] = {name = "[q6]Carica del Tosapecore", additional_info = "Si vincola alla raccolta\nUnicoClassi: Mago\n[q2]Usa: Sblocca l'aspetto Carica del Tosapecore per l'Artefatto Aluneth .\n[q]\"Cote \"il Pastore\" Metcalf non fu capace di svelare i segreti di questo misterioso bastone pastorizio.\""}
MultiLanguageItemData['it'][139559] = {name = "[q6]Progetto delle Stelle", additional_info = "Si vincola alla raccolta\nUnicoClassi: Mago\n[q2]Usa: Sblocca l'aspetto Progetto delle Stelle per l'Artefatto Felo'melorn .\n[q]\"I progetti dei Nobili Oscuri per una lama incantata ispirata a una preziosa costellazione del loro popolo.\""}
MultiLanguageItemData['it'][139560] = {name = "[q6]Cristallo Inestinguibile", additional_info = "Si vincola alla raccolta\nUnicoClassi: Mago\n[q2]Usa: Sblocca l'aspetto Ricordo di Fuocogelo per l'Artefatto Gelonero .\n[q]\"Un cristallo congelato, illuminato da un fuoco eterno senza calore. Non scotta e non mostra segni di scioglimento.\""}
MultiLanguageItemData['it'][139561] = {name = "[q6]Leggenda del Signore delle Scimmie", additional_info = "Si vincola alla raccolta\nUnicoClassi: Monaco\n[q2]Usa: Sblocca l'aspetto Custode della Birra per l'Artefatto Fu Zan, Compagno del Viandante .\n[q]\"Una birra speciale, molto potente, che si dice sia stata inventata dal Signore delle Scimmie stesso. È squisita e potrebbe essere utilizzata anche per altri scopi...\""}
MultiLanguageItemData['it'][139562] = {name = "[q6]Soffio della Serpe Immortale", additional_info = "Si vincola alla raccolta\nUnicoClassi: Monaco\n[q2]Usa: Sblocca l'aspetto Soffio della Serpe Immortale per l'Artefatto Sheilun, Bastone delle Nebbie .\n[q]\"Una fonte vorticosa di energia magica, che si dice provenga dalla pancia di un drago più antico del tempo.\""}
MultiLanguageItemData['it'][139563] = {name = "[q6]Mano della Tempesta", additional_info = "Si vincola alla raccolta\nUnicoClassi: Monaco\n[q2]Usa: Sblocca l'aspetto Mano della Tempesta per l'Artefatto the Pugni del Cielo .\n[q]\"Poco si sa riguardo la creazione della Mano della Tempesta, ma il potere al suo interno sembra provenire sia da Therazane che da Al'Akir, un'unione decisamente inaspettata.\""}
MultiLanguageItemData['it'][139564] = {name = "[q6]Editti Perduti del Guardiano", additional_info = "Si vincola alla raccolta\nUnicoClassi: Paladino\n[q2]Usa: Sblocca l'aspetto Armamento del Guardiano per l'Artefatto Mano d'Argento .\n[q]\"Abbiamo giurato di ridare speranza a questo mondo travagliato, di stanare la tirannia e il male ovunque mettessero radici... e di far calare il martello della giustizia su tutti i malvagi.\""}
MultiLanguageItemData['it'][139565] = {name = "[q6]Scintilla dell'Esarca Caduto", additional_info = "Si vincola alla raccolta\nUnicoClassi: Paladino\n[q2]Usa: Sblocca l'aspetto Baluardo del Vendicatore per l'Artefatto Scudo della Verità .\n[q]\"Quando l'Esarca Kelios cadde, anche l'ultima speranza di difendere il tempio se ne andò. La Legione aveva vinto. L'unica pace era pensare a quei pochi che erano fuggiti, ma presto la Legione avrebbe preso anche loro.\""}
MultiLanguageItemData['it'][139566] = {name = "[q6]Cuore della Corruzione", additional_info = "Si vincola alla raccolta\nUnicoClassi: Paladino\n[q2]Usa: Sblocca l'aspetto Ricordo Corrotto per l'Artefatto Brandicenere .\n[q]\"Uno sguardo triste al passato che Brandicenere si era lasciata alle spalle, un passato che molti speravano non sarebbe mai tornato.\""}
MultiLanguageItemData['it'][139567] = {name = "[q6]Scritti sulla Fine", additional_info = "Si vincola alla raccolta\nUnicoClassi: Sacerdote\n[q2]Usa: Sblocca l'aspetto Spira del Custode dei Tomi per l'Artefatto Ira della Luce .\n[q]\"Scritti raccolti dai tomi dell'Archivista sparsi, parole che prevedevano tempi terribili.\""}
MultiLanguageItemData['it'][139568] = {name = "[q6]Bastone della Genia della Luce", additional_info = "Si vincola alla raccolta\nUnicoClassi: Sacerdote\n[q2]Usa: Sblocca l'aspetto Scudo della Genia della Luce per l'Artefatto T'uure, Faro dei Naaru .\n[q]\"Il bastone risuona pacificamente con il potere delle Valkyra. Il suono si ferma quando viene toccato.\""}
MultiLanguageItemData['it'][139569] = {name = "[q6]Artiglio di N'zoth", additional_info = "Si vincola alla raccolta\nUnicoClassi: Sacerdote\n[q2]Usa: Sblocca l'aspetto Artiglio di N'zoth per l'Artefatto Xal'atath, Lama dell'Impero Nero .\n[q]\"Gli occhi si muovono. La carne pulsa. È decisamente ancora vivo.\""}
MultiLanguageItemData['it'][139570] = {name = "[q6]Codice Cifrato dell'Osso Rotto", additional_info = "Si vincola alla raccolta\nUnicoClassi: Ladro\n[q2]Usa: Sblocca l'aspetto Spaccaossa per l'Artefatto Lame Sterminatrici di Re .\n[q]\"I segreti di un assassino morto da tempo, conosciuto come \"lo Spaccaossa\". Si dice che avesse preso l'abitudine di rompere le ossa delle gambe delle sue vittime dopo che una di loro era tornata dalla morte per vendicarsi.\""}
MultiLanguageItemData['it'][139571] = {name = "[q6]Tomo dei Veleni Ultraterreni", additional_info = "Si vincola alla raccolta\nUnicoClassi: Ladro\n[q2]Usa: Sblocca l'aspetto Morso Velenoso per l'Artefatto the Zanne del Divoratore .\n[q]\"Un testo tramandato di generazione in generazione dai Cacciatori dell'Ombra Zandalari, in cui vengono spiegate le armi e i veleni più esotici utilizzati per uccidere i nemici.\""}
MultiLanguageItemData['it'][139572] = {name = "[q6]Codice Perduto degli Amani", additional_info = "Si vincola alla raccolta\nUnicoClassi: Sciamano\n[q2]Usa: Sblocca l'aspetto Prestigio degli Amani per l'Artefatto Pugno di Ra-Den .\n[q]\"Un testo dei Troll da tempo perduto, che racconta dei capi che sono ascesi e poi caduti nel corso delle generazioni. Un capitolo particolarmente lungo riguarda un Troll di nome Atai'natha e il potente artiglio magico che usava per imporre il suo dominio.\""}
MultiLanguageItemData['it'][139573] = {name = "[q6]Mazza da Guerra di Shirvallah", additional_info = "Si vincola alla raccolta\nUnicoClassi: Sciamano\n[q2]Usa: Sblocca l'aspetto Campione Zandalari per l'Artefatto Martelfato .\n[q]\"Nonostante il suo aspetto adornato, questa brutale mazza ha rivendicato molte vite nel tentativo di onorare il Dio Primordiale Shirvallah. Era scomparsa nel mare molto tempo fa assieme al Sacerdote che la brandiva.\""}
MultiLanguageItemData['it'][139574] = {name = "[q6]Spira della Regina Annegata", additional_info = "Si vincola alla raccolta\nUnicoClassi: Sciamano\n[q2]Usa: Sblocca l'aspetto Spira del Serpente per l'Artefatto Sharas'dal, Scettro delle Maree .\n[q]\"Strisciando sotto le onde, gli Alti Nobili non sembravano più loro stessi. Erano diventati tutt'uno con le profondità, servitori di qualcosa di più oscuro...\""}
MultiLanguageItemData['it'][139575] = {name = "[q6]Essenza dell'Esecutore", additional_info = "Si vincola alla raccolta\nUnicoClassi: Stregone\n[q2]Usa: Sblocca l'aspetto Fine del Destino per l'Artefatto Ulthalesh, Mietitrice di Ventomorto .\n[q]\"Distillata con i teschi di grandi campioni, quest'essenza fornisce un grande potere a coloro che osano pagarne l'oscuro costo.\""}
MultiLanguageItemData['it'][139576] = {name = "[q6]Volto del Primo Risvegliatore", additional_info = "Si vincola alla raccolta\nUnicoClassi: Stregone\n[q2]Usa: Sblocca l'aspetto Visione di Thal'kiel per l'Artefatto Teschio dei Man'ari .\n[q]\"I soggetti più in vista tra i frenologi in questo periodo sono Thal'kiel e Archimonde. Thal'kiel in particolare è risultato avere il cranio archetipico dell'incantatore, cosa ammirevole.\""}
MultiLanguageItemData['it'][139577] = {name = "[q6]Gioielli Ardenti di Sargeras", additional_info = "Si vincola alla raccolta\nUnicoClassi: Stregone\n[q2]Usa: Sblocca l'aspetto Terrore della Legione per l'Artefatto Scettro di Sargeras .\n[q]\"Una fiamma scura brucia all'interno del gioiello cremisi, lambendo i bordi quando ti avvicini.\""}
MultiLanguageItemData['it'][139578] = {name = "[q6]Spezzalame d'Arcanite", additional_info = "Si vincola alla raccolta\nUnicoClassi: Guerriero\n[q2]Usa: Sblocca l'aspetto Spezzalame d'Arcanite per l'Artefatto Strom'kar, la Spezzaguerra .\n[q]\"Realizzata a mano dal maestro fabbro della Rocca Celeste, Helgar, quest'ascia dovrebbe essere migliore di qualsiasi arma d'acciaio su Azeroth.\""}
MultiLanguageItemData['it'][139579] = {name = "[q6]Ammazzadraghi", additional_info = "Si vincola alla raccolta\nUnicoClassi: Guerriero\n[q2]Usa: Sblocca l'aspetto Lama dell'Ammazzadraghi per l'Artefatto Spadoni dei Valarjar .\n[q]\"Due asce temibili, recanti i teschi dei draghi uccisi, costruite con il legno runico dei Vrykul. Armi impressionanti per qualsiasi guerriero.\""}
MultiLanguageItemData['it'][139580] = {name = "[q6]Piastra Ardente del Devastamondi", additional_info = "Si vincola alla raccolta\nUnicoClassi: Guerriero\n[q2]Usa: Sblocca l'aspetto Ultimo Respiro del Devastamondi per l'Artefatto Scaglia del Custode della Terra .\n[q]\"Ricoperta dal sangue fuso di Neltharion stesso, lasciato fumare nella sua tana per innumerevoli anni, in attesa di ricongiungersi con la scaglia perduta dallo stesso padre.\""}
MultiLanguageItemData['it'][139583] = {name = "Runa Demoniaca", additional_info = "Oggetto di missione\n[q]\"Sulla pietra sono incisi caratteri indecifrabili.\""}
MultiLanguageItemData['it'][139584] = {name = "[q2]Bombe Appiccicose", additional_info = "Si vincola alla raccolta\n[q2]Usa: Lancia sul bersaglio una Bomba Appiccicosa che esplode dopo 5 s, infliggendo ([375% of Attack Power]) danni a tutti i nemici entro 5 m.\n\n Utilizzabile solo sulle Isole Disperse e su Argus. (30 S Recupero)\n15 Carici"}
MultiLanguageItemData['it'][139585] = {name = "[q2]Polvere di Fumo", additional_info = "Si vincola alla raccolta\n[q2]Usa: Lancia della Polvere di Fumo per terra, così da permetterti di sparire in una nuvola di fumo.\n\n Utilizzabile solo sulle Isole Disperse e su Argus.\n10 Carici"}
MultiLanguageItemData['it'][139586] = {name = "[q2]Tè di Sboccialesto", additional_info = "Si vincola alla raccolta\n[q2]Usa: Rigenera 100 energia.\n\n Utilizzabile solo sulle Isole Disperse. (5 S Recupero)\n10 Carici"}
MultiLanguageItemData['it'][139587] = {name = "[q3]Cassa Sospetta", additional_info = "Si vincola alla raccolta\nGiocattolo\nClassi: Ladro\n[q2]Usa: Ti travesti da cassa di legno. (30 Min Recupero)"}
MultiLanguageItemData['it'][139588] = {name = "[q2]Pacco di Pozioni da Battaglia", additional_info = "Si vincola alla raccolta\n[q2]Usa: Bevi un'utile pozione da battaglia dalla riserva personale di uno dei Senza Corona.\n\n Utilizzabile solo sulle Isole Disperse e su Argus. (30 S Recupero)\n6 Carici"}
MultiLanguageItemData['it'][139589] = {name = "[q2]Coltelli da Lancio Avvelenati", additional_info = "Si vincola alla raccolta\n[q2]Usa: Lancia un coltello avvelenato contro il bersaglio, inabilitandolo per 1 min.\n\n Utilizzabile solo sulle Isole Disperse e su Argus.\n8 Carici"}
MultiLanguageItemData['it'][139590] = {name = "[q3]Pergamena del Teletrasporto: Corvolesto", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti teletrasporta al Maniero dei Corvolesto. (1 Ora Recupero)"}
MultiLanguageItemData['it'][139591] = {name = "[q0]Tomo Rubato della Storia dell'Artefatto", additional_info = "Si vincola alla raccolta\nPrezzo di vendita:"}
MultiLanguageItemData['it'][139592] = {name = "[q2]Stivali Fumanti", additional_info = "Si vincola alla raccolta\n[q2]Usa: Aumenta la velocità di movimento in modalità furtiva del 15% per 1 ora.\n\n Utilizzabile solo sulle Isole Disperse e su Argus.\n3 Carici"}
MultiLanguageItemData['it'][139593] = {name = "Piccola Borsa di Elementi Riciclabili", additional_info = "Si vincola alla raccolta\n[q2]Usa: Frughi tra gli scarti alla ricerca di un tesoro nascosto. Utilizzabile solo al Centro di Riciclaggio."}
MultiLanguageItemData['it'][139594] = {name = "[q2]Cassa Recuperata", additional_info = "Si vincola alla raccolta\n[q2]Usa: Frughi tra gli scarti alla ricerca di un tesoro nascosto. Utilizzabile solo al Centro di Riciclaggio."}
MultiLanguageItemData['it'][139595] = {name = "[q4]Pantaloni di Nar'thalas Vintage", additional_info = "Si vincola alla raccolta\n{Gambe} {Stoffa}\n4 Armatura\n+5 Intelletto\n+7 Tempra\n[q2]+ 5 Critico\n[q2]+ 5 Maestria\nIntegrità 120 / 120\nRichiedeCorte di Farondis\n- Osannato\n[q]\"La moda è cambiata in diecimila anni.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][139596] = {name = "[q4]Paraspalle delle Radici Annodate", additional_info = "Si vincola alla raccolta\n{Spalle} {Cuoio}\n6 Armatura\n+4 [Agilità o Intelletto]\n+6 Tempra\n[q2]+ 4 Celerità\n[q2]+ 4 Maestria\nIntegrità 100 / 100\nRichiedePlasmasogni\n- Osannato\nPrezzo di vendita:"}
