MultiLanguageItemData['it'][140656] = {name = "[q6]Verga dell'Ascensione", additional_info = "Si vincola alla raccolta\nUnicoClassi: Sacerdote\n[q2]Usa: Combina il Cimiero della Genia della Luce con la Verga dell'Ascensione per creare il Bastone della Genia della Luce.\nRichiedeValarjar\n- Osannato\n[q]\"Uno splendido bastone, realizzato per canalizzare la grande potenza di un Mistico Vrykul da lungo tempo dimenticato. Senza la testa giusta, il bastone però resta dormiente.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][140657] = {name = "[q6]Cimiero della Genia della Luce", additional_info = "Si vincola alla raccolta\nUnicoClassi: Sacerdote\n[q2]Usa: Combina il Cimiero della Genia della Luce con la Verga dell'Ascensione per creare il Bastone della Genia della Luce.\n[q]\"Un intricato copricapo che pulsa di energia sacra. Riuscendo a canalizzarne l'energia, potrebbe diventare una potente arma della Luce.\""}
