MultiLanguageItemData['it'][141053] = {name = "Tecnica: Glifo - Proporzioni Metamorfiche", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare il Glifo - Proporzioni Metamorfiche.\n[q2]Crea un Glifo - Proporzioni Metamorfiche.\nRichiede Runografia di Legion (1)\nPrezzo di vendita: \nGlifo - Proporzioni Metamorfiche\nClassi: Mago\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nI bersagli metamorfati sono leggermente più grandi.\nPrezzo di vendita:\nRichiede Cartapecora Leggera , Pigmento Giallastro (6), Pigmento Rosato (50)"}
MultiLanguageItemData['it'][141054] = {name = "Tecnica: Glifo - Infuocato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare il Glifo - Infuocato.\n[q2]Crea un Glifo - Infuocato.\nRichiede Runografia di Legion (1)\nPrezzo di vendita: \nGlifo - Infuocato\nClassi: Mago\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nDopo Combustione si resta infuocati per qualche secondo.\nPrezzo di vendita:\nRichiede Cartapecora Leggera , Pigmento Giallastro (6), Pigmento Rosato (50)"}
MultiLanguageItemData['it'][141055] = {name = "Tecnica: Glifo - Grazia di Yu'lon", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare il Glifo - Grazia di Yu'lon.\n[q2]Crea un Glifo - Grazia di Yu'lon.\nRichiede Runografia di Legion (1)\nPrezzo di vendita: \nGlifo - Grazia di Yu'lon\nClassi: Monaco\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nDona il verde di Yu'lon ai globi del tuo Dono dello Yak.\nPrezzo di vendita:\nRichiede Cartapecora Leggera , Pigmento Giallastro (4), Pigmento Rosato (60)"}
MultiLanguageItemData['it'][141056] = {name = "Tecnica: Glifo - Surriscaldamento", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare il Glifo - Surriscaldamento.\n[q2]Crea un Glifo - Surriscaldamento.\nRichiede Runografia di Legion (1)\nPrezzo di vendita: \nGlifo - Surriscaldamento\nClassi: Ladro\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nScatto lascia una scia fumante al tuo passaggio.\nPrezzo di vendita:\nRichiede Cartapecora Leggera , Pigmento Giallastro (10), Pigmento Rosato (30)"}
MultiLanguageItemData['it'][141057] = {name = "Tecnica: Glifo - Scoppio Lampo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare il Glifo - Scoppio Lampo.\n[q2]Crea un Glifo - Scoppio Lampo.\nRichiede Runografia di Legion (1)\nPrezzo di vendita:\nGlifo - Scoppio Lampo\nClassi: Ladro\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nCambia il fumo con uno scoppio accecante!\nPrezzo di vendita:\nRichiede Cartapecora Leggera , Pigmento Giallastro (10), Pigmento Rosato (30)"}
MultiLanguageItemData['it'][141058] = {name = "Tecnica: Glifo - Maleficio Animale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare il Glifo - Maleficio Animale.\n[q2]Crea un Glifo - Maleficio Animale.\nRichiede Runografia di Legion (1)\nPrezzo di vendita:\nGlifo - Maleficio Animale\nClassi: Sciamano\n[q2]Usa: Apprendi in modo permanente questo glifo.\n\nMaleficio lanciato su un animale dura 1 giorno e può essere lanciato su più bersagli.\nPrezzo di vendita:\nRichiede Cartapecora Leggera , Pigmento Giallastro (6), Pigmento Rosato (50)"}
