MultiLanguageItemData['it'][141216] = {name = "[q4]Redini Profanate", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Profanatore del Bosco cavalcabile.\n[q2]Evoca e congeda un Profanatore del Bosco cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Custodi del Bosco del Sogno di Smeraldo sono stati tra i primi a cadere sotto l'influenza corruttrice dell'Incubo.\"\nImpresa:\nGloria dell'incursore di Legion\nCategoria:\nSpedizioni e incursioni"}
MultiLanguageItemData['it'][141217] = {name = "[q4]Redini dell'Ippogrifo Fagliapiuma", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda un Ippogrifo Fagliapiuma cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un tempo cavalcature degli Alti Nobili, queste creature ora vagano libere sulle Isole Disperse. Sono molto rare da trovare a causa dei loro poteri magici latenti.\"\nImpresa:\nGloria dell'eroe di Legion\nCategoria:\nSpedizioni e incursioni"}
