MultiLanguageItemData['it'][142049] = {name = "Eredità del Re della Montagna", additional_info = "Karazhan\nOggetto Evocato\nUnico\n[q2]Usa: Rompe il sigillo del libro, aumentando i danni da te inflitti e le cure da te ricevute quando scendi al di sotto del 25% di salute restante per 1 ora.\n[q]\"L'essenza di questo libro è vincolata a Karazhan.\""}
MultiLanguageItemData['it'][142051] = {name = "Tormento del Worgen", additional_info = "Karazhan\nOggetto Evocato\nUnico\n[q2]Usa: Rompe il sigillo del libro, fornendoti Tormento del Worgen. Quando si colpisce un nemico con meno del 30% di salute restante, si ottiene l'effetto Frenesia del Worgen, che aumenta i danni inflitti del 15% per 30 s. L'effetto non può verificarsi più di una volta ogni 5 min.\n[q]\"L'essenza di questo libro è vincolata a Karazhan.\""}
