MultiLanguageItemData['it'][142357] = {name = "Progetto: Incisore dell'Alba", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Incisore dell'Alba.\nRichiede Forgiatura Classica (1)\nPrezzo di vendita:\n[q3]Incisore dell'Alba\nSi vincola all'equipaggiamento\n{Una mano} {Ascia}\n{3 - 7 Danni} {Velocità 2.60}\n(1.9 danni per secondo)\n+2 Forza\n+3 Tempra\n[q2]+ 5 Critico\nIntegrità 90 / 90\nPrezzo di vendita: \nRichiede Lingotto di Torio (30), Lingotto di Torio Incantato (4), Rubino Stellato (4), Zaffiro Blu (4), Pietra da Molatura Densa (2), Cuoio Duro (4)"}
MultiLanguageItemData['it'][142358] = {name = "Progetto: Stocco Fiammeggiante", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare uno Stocco Fiammeggiante.\nRichiede Forgiatura Classica (1)\nPrezzo di vendita:\n[q3]Stocco Fiammeggiante\nSi vincola all'equipaggiamento\n{Una mano} {Spada}\n{3 - 6 Danni} {Velocità 2.60}\n(1.7 danni per secondo)\nIntegrità 90 / 90\n[q2]Probabilità all'impatto: Brucia il nemico, infliggendo 2 danni in 30 s.\nPrezzo di vendita: \nRichiede Lingotto di Torio Incantato (10), Essenza di Fuoco (4), Cuore di Fuoco (4), Diamante Azerotiano (2), Pietra da Molatura Densa (2)"}
