MultiLanguageItemData['it'][142361] = {name = "[q3]Artiglio d'Avorio", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Rigeneri il 100% della salute massima e diventi un vendicatore di Aviana. In questo stato, tutti i personaggi diventano ostili e uccidere personaggi fornisce Marchi della Preda. Funziona solo nelle aree dei falcosauri e delle missioni mondiali PvP, e attiva la modalità PvP. (15 Min Recupero)\n[q]\"Impugnare questo artiglio ti fa venir voglia di afferrare la preda con le mani e farla a pezzi.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][142363] = {name = "[q2]Marchio della Preda", additional_info = "Si vincola alla raccolta\n[q2]Usa: Aumenta la reputazione con la Vendetta dell'Artiglio di 100.\n[q]\"Simbolo di una caccia riuscita.\""}
MultiLanguageItemData['it'][142364] = {name = "[q2]Borsa di Rami", additional_info = "Si vincola alla raccolta\nUnico (5)\n[q2]Usa: Costruisce un nido che permette di riposare. Dura 5 min. Se riposi per almeno 5 s diventi Ben Riposato e tutti gli attributi aumentano del 3% per 1 ora. Utilizzabile solo sulle Isole Disperse. (5 Min Recupero)\nRichiedeVendetta dell'Artiglio\n- Amichevole\nPrezzo di vendita:"}
