MultiLanguageItemData['it'][147007] = {name = "[q4]Grande Piano dell'Ingannatore", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 7 Maestria\n[q2]Usa: Marchia un personaggio alleato con Mano Guida, curandolo di 22 ogni 3.0 s per 2 min. Se il bersaglio scende al di sotto del 35% di salute restante, Mano Guida si consuma e gli fornisce uno scudo che previene [(1 + Versatilità) * 379 ] danni subiti per 15 s. (2 min di ricarica, 2 cariche)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][147009] = {name = "[q4]Braci Infernali", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 7 Critico\n[q2]Equipaggia: Gli attacchi in mischia hanno una probabilità di infliggere 20 danni da fuoco. La probabilità di critico di questi danni aumenta del 10% per ogni alleato entro 10 m che possiede questo oggetto.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][147010] = {name = "[q4]Culla dell'Angoscia", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 7 Celerità\n[q2]Equipaggia: Quando si ha almeno il 80% di salute restante, fornisce 1 Forza o Agilità ogni secondo, in base alla specializzazione. Si accumula fino a 10 volte. Se si scende al di sotto del 50% di salute restante, l'effetto si dissolve.\nPrezzo di vendita:"}
