MultiLanguageItemData['it'][151639] = {name = "[q5]Anima del Flagello dei Demoni", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Celerità\n[q2]+ 4 Maestria\n\n[q0]Incavo Prismatico\n\nClassi: Cacciatore di Demoni\n[q2]Equipaggia: Fornisce uno dei seguenti talenti (in base alla specializzazione):\n\nRovina: Primo Sangue\nVendetta: Ricaduta\n[q]\"Gli Illidari risiedono sulla Vilmartello. Essi esercitano i poteri proibiti dei demoni che uccidono al fine di combattere le forze del caos... a qualsiasi costo.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][151640] = {name = "[q5]Anima del Signore della Morte", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Celerità\n[q2]+ 4 Maestria\n\n[q0]Incavo Prismatico\n\nClassi: Cavaliere della Morte\n[q2]Equipaggia: Fornisce uno dei seguenti talenti (in base alla specializzazione):\n\nSangue: Baluardo Infetto\nGelo: Tempesta Incombente\nEmpietà: Piaghe Purulente\n[q]\"I Cavalieri della Spada d'Ebano risiedono su Acherus, la Roccaforte d'Ebano. Un tempo erano i campioni del Flagello, ora sono i dannati.\"\nPrezzo di vendita:"}
