MultiLanguageItemData['it'][151709] = {name = "Progetto: Ancora di Vilardesia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare un'Ancora di Vilardesia.\n[q2]Crea un'Ancora di Vilardesia.\nRichiede Forgiatura di Legion (1)\n\n\nAncora di Vilardesia\n[q2]Usa: Agganci un'ancora alle tue caviglie, facendoti trascinare direttamente sul fondo dell'oceano. Utilizzabile solo in acqua. (30 S Recupero)\n[q]\"Appesantita tanto da mandare un kraken sul fondo dell'oceano!\"\nRichiede Vilardesia (50)"}
MultiLanguageItemData['it'][151710] = {name = "Ricetta: Trasmutazione - Sargerite Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a trasmutare il Sangue di Sargeras in Sargerite Primordiale.\n[q2]Trasmuta il Sangue di Sargeras in Sargerite Primordiale.\nRichiede Alchimia di Legion (1)\nPrezzo di vendita: \n[q3]Sargerite Primordiale\nSi vincola alla raccolta\nReagente d'artigianato\n[q]\"Utilizzata come reagente d'artigianato o cedibile al Commerciante Caelen alla Forgia di Obliterum di Dalaran.\"\nPrezzo di vendita: \nRichiede Sangue di Sargeras (25)"}
