MultiLanguageItemData['it'][154172] = {name = "[q5]Visione di Aman'thul", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Sentiero dei Titani (1)\nMonile\n[q2]+ 6 Critico\n[q2]+ 6 Celerità\n[q2]+ 6 Versatilità\n[q2]+ 6 Maestria\n[q2]Equipaggia: Gli incantesimi e le abilità hanno una probabilità di aumentare la velocità, l'indice d'elusione e l'indice di ritorno vitale di 9 per 12 s.\n\nGrandezza di Aman'thul\n Il potenziamento del Pantheon aumenta l'Intelletto di 6 per 15 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][154173] = {name = "[q4]Convinzione di Aggramar", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Sentiero dei Titani (1)\nMonile\n+6 [Agilità o Forza]\n[q2]Equipaggia: Subire danni fornisce una probabilità di aumentare l'indice di versatilità di 27 per 14 s.\n\nFermezza di Aggramar\n Il potenziamento del Pantheon aumenta la salute massima di 94 per 15 s e rigenera 988 salute.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][154174] = {name = "[q4]Vitalità di Golganneth", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Sentiero dei Titani (1)\nMonile\n+6 Agilità\n[q2]Equipaggia: Le abilità d'attacco hanno una probabilità di creare una Tempesta Devastante sulla posizione del bersaglio, infliggendo ( 10 * 6) danni da natura suddivisi tra tutti i nemici entro 6 m in 6 s.\n\nIra Tonante di Golganneth\n Il potenziamento del Pantheon fa sì che gli attacchi automatici provochino un'esplosione di fulmini, infliggendo [ 1 * ([Mainhand weapon min base speed]) * 5 ] danni da natura a tutti i nemici entro 8 m dal bersaglio. Dura 15 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][154175] = {name = "[q4]Compassione di Eonar", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Sentiero dei Titani (1)\nMonile\n+6 Intelletto\n[q2]Equipaggia: Gli effetti di cura hanno una probabilità di far crescere nelle vicinanze un Bocciolo di Smeraldo, che cura un alleato ferito casuale di 16 ogni 2 s. Dura 12 s.\n\nAbbraccio Lussureggiante di Eonar\n Il potenziamento del Pantheon fa sì che i successivi 4 lanci di un incantesimo di cura diretto forniscano al bersaglio uno scudo che assorbe 24 danni subiti per 30 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][154176] = {name = "[q4]Coraggio di Khaz'goroth", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Sentiero dei Titani (1)\nMonile\n+6 Forza\n[q2]Equipaggia: Gli attacchi hanno una probabilità di accendere la tua arma con il fuoco della forgia di Khaz'goroth, così che gli attacchi automatici infliggano ( 1 * [Mainhand weapon min base speed] * 8 ) danni da fuoco aggiuntivi per 12 s.\n\nForma di Khaz'goroth\n Il potenziamento del Pantheon aumenta l'indice di critico, di celerità, di maestria o di versatilità (scegliendo sempre quello più alto) di 26 per 15 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][154177] = {name = "[q4]Abilità di Norgannon", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Sentiero dei Titani (1)\nMonile\n[q2]+ 8 Maestria\n[q2]Equipaggia: Gli incantesimi d'attacco hanno una probabilità di aumentare l'Intelletto di 22 per 12 s.\n\nComando di Norgannon\n Il potenziamento del Pantheon fornisce 6 cariche di Comando di Norgannon per 15 s. Gli incantesimi d'attacco consumano una carica per infliggere 13 danni aggiuntivi di una scuola di magia casuale.\nPrezzo di vendita:"}
