MultiLanguageItemData['it'][155819] = {name = "[q2]Frittata di Plesiosauro con Tripli Sottaceti", additional_info = "Si vincola alla raccolta\n[q2]Usa: Evoca Humphrey come tua guardia per 10 min.\n\n Utilizzabile solo nella Valle dei Sacraonda.\n[q]\"Il piatto preferito di Humphrey. Un pieno di proteine per un pieno di energie!\""}
MultiLanguageItemData['it'][155820] = {name = "[q2]Bomba di Spine", additional_info = "Si vincola alla raccolta\nUnico (20)\n[q2]Usa: Lancia un esplosivo pieno di spine di Verrospino su una posizione bersaglio, infliggendo 3775 danni fisici a tutti i nemici entro 10 m e stordendoli per 3 s s. (2 Min Recupero)\n[q]\"Imbottita fino all'orlo di spine di Verrospino.\""}
