MultiLanguageItemData['it'][156564] = {name = "[q4]Shu-Zen, la Sentinella Divina", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda Shu-Zen.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Mentre i membri del Loto Dorato lavoravano per curare la Vallata dell'Eterna Primavera, una statua ha preso vita, difendendoli dagli assalti dello Sha. Ritenuto un segno di buona fortuna o un dono della Luce, Shu-Zen è un fedele compagno di chiunque voglia difendere Azeroth dai folli sussurri degli Dei Antichi.\"\nNegozio"}
MultiLanguageItemData['it'][156565] = {name = "Nucleo del Guardiano Milov", additional_info = "Oggetto di missione\n[q]\"Questo nucleo di dati è molto più leggero di quanto sembri. Cosa ci sarà esattamente conservato all'interno?\""}
MultiLanguageItemData['it'][156566] = {name = "[q3]Guizzo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare questa mascotte.\nRichiede dal livello 1 al 80 ( 80)"}
