MultiLanguageItemData['it'][156631] = {name = "[q4]Sfera della Trasmutazione di Silas", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Permette al personaggio di interagire con vari calderoni a Kul Tiras e Zandalar, e li evidenzia.\n[q2]Usa: Concentrarsi sulla sfera permette di trasmutarla in un altro oggetto per 1 ora.\nRichiede Alchimia di Kul Tiras (150)\n[q]\"La superficie della sfera turbina e vortica, mostrando immagini diverse per brevi istanti, troppo brevi per capire cosa siano in realtà.\""}
MultiLanguageItemData['it'][156632] = {name = "[q4]Pietra del Trasporto di Silas", additional_info = "Si vincola alla raccolta\nUnico\nDurata: 1 ora (tempo reale)\n[q2]Permette al personaggio di interagire con vari calderoni a Kul Tiras e Zandalar, e li evidenzia.\n[q2]Usa: Evoca un occhio onnisciente per 2 min, che ti teletrasporta istantaneamente in un luogo sicuro vicino quando ti trovi all'esterno a Kul Tiras o Zandalar. (9 Min Recupero)\nRichiede Alchimia di Kul Tiras (1)"}
MultiLanguageItemData['it'][156633] = {name = "[q4]Pozione della Prosperità di Silas", additional_info = "Si vincola alla raccolta\nUnico\nDurata: 1 ora (tempo reale)\n[q2]Permette al personaggio di interagire con vari calderoni a Kul Tiras e Zandalar, e li evidenzia.\nUsa: Aumenta la probabilità di creare oggetti aggiuntivi dalla tua lista di ricette di Alchimia di Kul Tiras. (20 Min Recupero)\nRichiede Alchimia di Kul Tiras (1)"}
MultiLanguageItemData['it'][156634] = {name = "[q4]Fiala delle Cure Continue di Silas", additional_info = "Si vincola alla raccolta\nUnico\nDurata: 1 ora (tempo reale)\n[q2]Permette al personaggio di interagire con vari calderoni a Kul Tiras e Zandalar, e li evidenzia.\n[q2]Usa: Rigenera 8000 salute grazie alla tua interminabile e traboccante fiala delle cure continue! (5 Min Recupero)\nRichiede Alchimia di Kul Tiras (1)"}
