MultiLanguageItemData['it'][160649] = {name = "[q4]Estratto Inoculante", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 Intelletto\n[q2]Usa: Inietta 5 accumuli di Anticorpi Mutageni in un bersaglio alleato per 30 s. Le tue cure dirette su quel bersaglio consumano 1 accumulo dell'effetto per rigenerare 56 salute aggiuntiva. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][160650] = {name = "[q4]Disco della Regressione Sistematica", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 Forza\n[q2]Equipaggia: Gli attacchi hanno una probabilità di provocare dei Settori Invalidati, infliggendo istantaneamente 72 danni da ombra suddivisi tra i bersagli in un cono frontale. Infligge danni aggiuntivi quando colpisce bersagli multipli.\nPrezzo di vendita:"}
