MultiLanguageItemData['it'][163573] = {name = "[q4]Redini di Mantodorato", additional_info = "Unico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare Mantodorato.\n[q2]Evoca e congeda Mantodorato.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Ser Sacraonda ha ordinato ai suoi sgherri di rubare questo cavallo dalla Tenuta dei Norwington a Tiragarde, perché bramava il suo lucente manto dorato.\"\nZona:\nSacraonda"}
MultiLanguageItemData['it'][163574] = {name = "[q4]Redini Morsicate del Mulo da Soma Terrorizzato", additional_info = "Unico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Mulo da Soma Terrorizzato.\n[q2]Evoca e congeda un Mulo da Soma Terrorizzato.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Questo povero mulo si trovava a Drustvar quando le Streghe hanno attaccato. Ne ha viste davvero troppe.\"\nZona:\nDrustvar"}
