MultiLanguageItemData['it'][164761] = {name = "[q6]Xal'atath, Lama dell'Impero Nero", additional_info = "Oggetto di missione\nUnico\n[q]\"Xal'atath è in grado di pensare. Un tempo arma preziosa ambita dai Sacerdoti votati a combattere la Legione Infuocata, questo artefatto ha perso il proprio potere ed è in uno stato dormiente. Per ora.\""}
MultiLanguageItemData['it'][164762] = {name = "[q4]Destriero di Kul Tiras", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Destriero di Kul Tiras.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"L'esercito di Kul Tiras è conosciuto per le sue capacità sia in mare, grazie alla sua vasta flotta, che sulla terra, con un'ingente cavalleria armata.\"\nImpresa:\nRazze Alleate: Umani di Kul Tiras"}
MultiLanguageItemData['it'][164763] = {name = "Tridente dell'Oceano Profondo", additional_info = "Oggetto di missione\n[q]\"Se lo tieni vicino all'orecchie, puoi sentire il rumore dell'oceano.\""}
MultiLanguageItemData['it'][164764] = {name = "[q3]Testa di Tridente", additional_info = "Oggetto di missione\n[q2]La Voce dell'Oceano ti protegge.\n[q]\"I denti feroci sono ottimi come violenta arma da mischia. Da usare in abbinamento all'Impugnatura di Tridente.\""}
MultiLanguageItemData['it'][164766] = {name = "[q4]Verga Runica di Iwen", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Permette di ricevere risorse aggiuntive con il Disincantamento.\n[q2]Usa: Consuma 1 Cristallo Velato per animare un Golem Inerte. (5 S Recupero)\nRichiede Incantamento di Kul Tiras (150)\n[q]\"La magia dei Drust fa vibrare energicamente la verga. Può essere usata come Verga Runica di livello inferiore.\""}
