MultiLanguageItemData['it'][165568] = {name = "[q4]Invocazione: Yu'lon", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 Agilità\n[q2]Usa: Ordina all'invocazione di Yu'lon di assaltare il bersaglio, infliggendo 191 danni da natura suddivisi tra tutti i nemici vicini. Infligge danni aggiuntivi quando colpisce bersagli multipli. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][165569] = {name = "[q4]Protezione dell'Avvolgimento", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 Intelletto\n[q2]Usa: Avvolge fino a 5 alleati nell'area bersaglio con degli scudi condivisi per 10 s, che assorbono fino a [ 458 * (1 + Versatilità)] danni subiti. Assorbe danni aggiuntivi quando protegge alleati multipli. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][165570] = {name = "[q4]Ancora del Brivido Eterno", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 Forza\n[q2]Equipaggia: Le abilità che infliggono danni in mischia applicano Brivido Eterno, infliggendo 1 danni da gelo ogni 3 s e riducendo la velocità di movimento del bersaglio colpito del 2%. Questo effetto si accumula fino a 10 volte. Dura 12 s. (750ms di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][165571] = {name = "[q4]Scheggia Incandescente", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 Intelletto\n[q2]Equipaggia: Se non ci sono alleati entro 5 m, fornisce 1 indice di critico ogni 2 s. Al raggiungimento di 10 accumuli, fornisce anche 4 indice di maestria. L'effetto si riduce col tempo se ci sono degli alleati vicini, a meno che non abbiano anche loro questo effetto attivo.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][165572] = {name = "[q4]Validatore Instabile a Gigavolt Oscillante del Reattore Esterno", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 Agilità\n[q2]Equipaggia: Il tuo indice di critico aumenta di 3 ogni 2 s, fino a un massimo di ( 3 * 6) per 6 s, dopodiché si riduce fino a spegnersi per 6 s. Il ciclo si ripete ogni 32 s.\n[q2]Usa: Mantiene l'oscillazione attuale per 6 s. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][165573] = {name = "[q4]Prisma Rifrangente Ricoperto di Diamanti", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 [Agilità o Forza]\n[q2]Equipaggia: Ogni 10 s, fornisce uno scudo che assorbe [ 82 * (1 + Versatilità)] danni subiti, fino a un massimo di [( 82 * (1 + Versatilità)) * 5].\nPrezzo di vendita:"}
MultiLanguageItemData['it'][165574] = {name = "[q4]Rabbia Primordiale di Grong", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+6 Forza\n[q2]Usa: Scatena una rabbia primordiale, infliggendo ( 93 * 5) danni fisici suddivisi tra i nemici vicini in 4 s. Infligge danni aggiuntivi quando colpisce bersagli multipli. Durante l'effetto, non è possibile muoversi o usare abilità. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
