MultiLanguageItemData['it'][166770] = {name = "[q7]Mantello a Bande di Gilneas", additional_info = "[q]Livello di potenziamento del Cimelio: 0/0\n[q7]Si vincola alla Brigata\nSchiena\n6 Armatura\n+6 [Agilità o Forza o Intelletto]\n+9 Tempra\n[q2]+ 6 Celerità\n[q2]+ 6 Versatilità\n[Requires any Alliance race]\nRichiede dal livello 1 al 29 ( 29)\n[q]\"Un mantello piuttosto comune dato in dotazione alle nuove reclute in guerra.\"\n\n[q]Vessillo degli Avventurieri Leggendari (0/7)\n[q0]Corazza Cimelio\nElmo Cimelio\nSpallacci Cimelio\nMantello Cimelio\nPantaloni Cimelio\nCollana Cimelio\nAnello Cimelio\n[q0](2) Set : Riduce il consumo del bonus all'esperienza fornito dal riposo del 30%.\n(3) Set : Aumenta la rigenerazione quando non si è in combattimento all'esterno, nelle spedizioni e nei campi di battaglia.\n(5) Set : Aumentare di livello attiva Scarica di Conoscenza, infliggendo 1126 danni da sacro ai nemici vicini e aumentando [[Primary Stat]] del 40% per 2 min. Sconfiggere i nemici estende la durata dell'effetto, fino a un massimo di 2 min.\n(6) Set : Riduce il consumo del bonus all'esperienza fornito dal riposo del 30% aggiuntivo.\n\n\nMercante:\nApprovvigionatrice Forgiadura\nZona:\nBoralus"}
MultiLanguageItemData['it'][166771] = {name = "Sparafuoco Improvvisato", additional_info = "Oggetto di missione\n[q2]Usa: Lancia un razzo a uno zeppelin ghiacciato dell'Orda per farlo esplodere. Infligge danni da fuoco ai nemici sulla posizione del bersaglio. (10 S Recupero)"}
MultiLanguageItemData['it'][166773] = {name = "Esplosivi dei Goblin", additional_info = "Rivafosca\nOggetto di missione\nUnico\n[q]\"Chi, sano di mente, ha pensato che fosse una buona idea lasciare in giro degli esplosivi?\""}
MultiLanguageItemData['it'][166774] = {name = "[q4]Porcus, Suino della Buona Sorte", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\nEvoca e congeda questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Porcus fu visto per la prima volta dall'Imperatore Shaohao durante il terzo giorno della sua meditazione ed è considerato dai Pandaren uno dei più grandi simboli di buona fortuna.\"\nNegozio"}
MultiLanguageItemData['it'][166775] = {name = "[q3]Famiglio Volpino", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\nEvoca e congeda questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Incredibilmente curiose e intelligenti, queste creature simili a volpi hanno attraversato la Grande Oscurità per giungere fino ad Azeroth. Avvicinate dai più grandi campioni del mondo, amano la compagnia e l'avventura.\"\nNegozio"}
MultiLanguageItemData['it'][166776] = {name = "[q4]Sognatore Silveriano", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\nEvoca e congeda questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un'artista della città magica di Dalaran un giorno si addormentò sul suo pennello, sognando di dipingere un bellissimo drago piumato. Il suo disegno prese vita e, quando si svegliò, lo trovò dolcemente addormentato al suo fianco.\"\nNegozio"}
