MultiLanguageItemData['it'][168022] = {name = "[q3]Progetto: Martello da Forgiatore Khaz'goriano", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Martello da Forgiatore Khaz'goriano.\n[q2]Crea un Martello Khaz'goriano.\nRichiede Forgiatura di Kul Tiras (150)\nPrezzo di vendita: \n[q4]Martello da Forgiatore Khaz'goriano\nSi vincola alla raccolta\nUnico Attrezzo di Forgiatura Quando si creano armi o armature con Forgiatura, c'è una probabilità che ottengano la proprietà \"Indistruttibile\".\n[q2]Usa: Permette di riparare un pezzo dell'equipaggiamento all'istante. (1 Ora Recupero)\nEquipaggia: Aumenta la competenza in Forgiatura di 4.\nRichiede Forgiatura di Kul Tiras (150)\n[q]\"Questo martello può essere usato al posto di un normale martello da fabbro.\"\nRichiede Sangue del Titano (30), Strumenti di Precisione Benedetti , Pugno di Azerokk , Minerale di Argento della Tempesta (30), Minerale di Platino (20), Espulsom (10)"}
MultiLanguageItemData['it'][168023] = {name = "Ripetitore di Trasporto Schiacciato", additional_info = "Si vincola alla raccolta"}
MultiLanguageItemData['it'][168024] = {name = "[q3]Formula: Verga Runica di Iwen", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare una Verga Runica di Iwen.\n[q2]Crea una Verga Runica di Iwen.\nRichiede Incantamento di Kul Tiras (150)\nPrezzo di vendita: \n[q4]Verga Runica di Iwen\nSi vincola alla raccolta\nUnico\n[q2]Permette di ricevere risorse aggiuntive con il Disincantamento.\n[q2]Usa: Consuma 1 Cristallo Velato per animare un Golem Inerte. (5 S Recupero)\nRichiede Incantamento di Kul Tiras (150)\n[q]\"La magia dei Drust fa vibrare energicamente la verga. Può essere usata come Verga Runica di livello inferiore.\"\nRichiede Braccio Ghermitore di Vimini , Pietra Runica di Thros , Essenza Persistente dei Drust (50), Scheggia Ombrale (20), Cristallo Velato (10), Espulsom (10)"}
MultiLanguageItemData['it'][168025] = {name = "[q3]Libro degli Schemi: Chiave ad Arco Ultr4", additional_info = "Si vincola alla raccolta\nUsa: Riapprendi qualsiasi schema di Ingegneria appreso tramite missioni per i tuoi Ferri del Mestiere, dimenticato in seguito a un cambio di professione.\nRichiede Ingegneria di Kul Tiras (150)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][168026] = {name = "[q3]Libro di Tecniche: Penna Rosso Sangue di Lana'thel", additional_info = "Si vincola alla raccolta\nUsa: Riapprendi qualsiasi tecnica di Runografia appresa tramite missioni per i tuoi Ferri del Mestiere, dimenticata in seguito a un cambio di professione.\nRichiede Runografia di Kul Tiras (150)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][168027] = {name = "[q3]Modello: Focus di Martelgemma", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Focus di Martelgemma.\n[q2]Crea delle lenti.\nRichiede Oreficeria di Kul Tiras (150)\nPrezzo di vendita: \n[q4]Focus di Martelgemma\nSi vincola alla raccolta\nUnico\n[q2]Permette a chi la possiede di interagire con i santuari di Kul Tiras e Zandalar, concentrando la luce della zona attraverso delle lenti per poter creare un geode di gemme.\n[q2]Usa: Utilizzando il focus, estrae con cautela una gemma dall'incavo di uno dei tuoi oggetti.\nRichiede Oreficeria di Kul Tiras (150)\nRichiede Cannocchiale Tutto Tempestato di Diamanti di Sweete , Geode d'Azerite Grezzo , Polvere d'Azerite Fine (50), Occhio del Kraken (5), Espulsom (10)"}
MultiLanguageItemData['it'][168028] = {name = "[q3]Modello: Martello delle Pelli Tonanti", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Martello delle Pelli Tonanti.\n[q2]Crea un Martello delle Pelli Tonanti.\nRichiede Conciatura di Kul Tiras (150)\nPrezzo di vendita: \n[q4]Martello delle Pelli Tonanti\nSi vincola alla raccolta\nUnico\n[q2]Ti permette di interagire con i Tamburi della Forza Primordiale, fornendoti una benedizione alla velocità di movimento, alla potenza o alla resistenza.\n[q2]Usa: Aumenta la celerità del 15%. Dura 40 s.\n\n Ricevendo questo effetto, si diventa esausti e non si può beneficiare di altri effetti simili per 10 min. (10 Min Recupero)\nRichiede Conciatura di Kul Tiras (150)\n[q]\"Utile per dare la giusta forma ai pezzi di cuoio o come strumento a percussione.\"\nRichiede Tendine Regale Lungo (4), Spirito dello Sconfitto (15), Osso Sporco di Sangue (50), Pelle della Tempesta (50), Pelle della Tempesta Indurita (25), Espulsom (10)"}
MultiLanguageItemData['it'][168029] = {name = "[q3]Modello: Filo Sincronico", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Filo Sincronico.\n[q2]Crea un Filo Sincronico.\nRichiede Sartoria di Kul Tiras (150)\nPrezzo di vendita: \n[q4]Filo Sincronico\nSi vincola alla raccolta\nUnico\n[q2]È più facile recuperare stoffe di Kul Tiras e di Zandalar disperse nel tempo.\n[q2]Usa: Permette ai Sarti Sincronici di ricucire gli strappi nel tessuto del tempo di Kul Tiras e Zandalar.\nRichiede Sartoria di Kul Tiras (150)\n[q]\"Ripara persino il tessuto temporale.\"\nRichiede Essenza della Dinastia dei Troll , Essenza del Loa Regale , Essenza delle Profondità , Essenza delle Sabbie , Lino Spruzzato di Mare (75), Filo di Nylon (75), Espulsom (10)"}
