MultiLanguageItemData['it'][168436] = {name = "[q6]Punta di Stella Concentrata", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con lo Spirito della Conservazione.\nAbilità maggiore:\n Spirito della Conservazione\nPortata di 40 m Canalizzato (3 s di lancio) 1 min di recupero Canalizza un raggio d'energia su un alleato, curandolo di [( 1452 * (5) + 1452 ) * (1 + Versatilità)] in 3 s. \n Abilità minore:\n Spirito Devoto\nOgni 5 s fornisce Spirito Devoto, in modo che il successivo Cura Rapida fornisca 153 cure aggiuntive. Si accumula fino a 3 volte.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
MultiLanguageItemData['it'][168439] = {name = "[q6]Pulviscolo di Stella Turbinante", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con lo Spirito della Conservazione.\nAbilità maggiore:\n Spirito della Conservazione\nPortata di 40 m Canalizzato (3 s di lancio) 1 min di recupero Canalizza un raggio d'energia su un alleato, curandolo di [( 1452 * (5) + 1452 ) * (1 + Versatilità)] in 3 s. Fino a un massimo di 6 altri alleati sulla traiettoria del raggio vengono curati di [ 145 * (1 + Versatilità)] ogni 0.6 s. \n Abilità minore:\n Spirito Devoto\nOgni 5 s fornisce Spirito Devoto, in modo che il successivo Cura Rapida fornisca 153 cure aggiuntive. Si accumula fino a 5 volte.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
MultiLanguageItemData['it'][168440] = {name = "[q6]Frammento di Stella Luccicante", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con lo Spirito della Conservazione.\nApprendi il Grado 3 di una qualunque essenza dei Rajani o della Coalizione di Uldum su un altro personaggio per sbloccare questa essenza.\nRichiede la reputazione Riverito con i Rajani. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Spirito della Conservazione\nPortata di 40 m Canalizzato (3 s di lancio) 1 min di recupero Canalizza un raggio d'energia su un alleato, curandolo di [( 1452 * (5) + 1452 ) * (1 + Versatilità)] in 3 s. Fino a un massimo di 6 altri alleati sulla traiettoria del raggio vengono curati di [ 145 * (1 + Versatilità)] ogni 0.6 s.\n\n Ogni volta che Spirito della Conservazione cura il bersaglio primario, ottiene 1 accumulo di Spirito Devoto. \n Abilità minore:\n Spirito Devoto\nOgni 5 s fornisce Spirito Devoto, in modo che il successivo Cura Rapida fornisca 153 cure aggiuntive. Si accumula fino a 5 volte.\n\n Ogni accumulo di Spirito Devoto consumato aumenta la probabilità di critico del successivo Cura Rapida entro 15 s del 20%.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
MultiLanguageItemData['it'][168442] = {name = "[q6]Sangue Ribollente dello Sconfitto", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Sangue dei Nemici.\nAbilità maggiore:\n Sangue dei Nemici\nIstantaneo 2 min di recupero Il Cuore di Azeroth erutta violentemente, infliggendo 1739 danni da ombra ai nemici entro 12 m. Fornisce un aumento del 25% alla probabilità di critico contro questi bersagli per 10 s \n Abilità minore:\n Insanguinato\nI colpi critici con gli incantesimi e le abilità forniscono 1 accumulo di Insanguinato . Al raggiungimento di 40 accumuli, aumenta anche l'indice di celerità di 125 per 8 s."}
MultiLanguageItemData['it'][168443] = {name = "[q6]Sangue Agitato del Dominato", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Sangue dei Nemici.\nRichiede l'impresa \"Rissaiolo da battaglia\". (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Sangue dei Nemici\nIstantaneo 1.5 min di recupero Il Cuore di Azeroth erutta violentemente, infliggendo 1739 danni da ombra ai nemici entro 12 m. Fornisce un aumento del 25% alla probabilità di critico contro questi bersagli per 10 s. \n Abilità minore:\n Insanguinato\nI colpi critici con gli incantesimi e le abilità forniscono 1 accumulo di Insanguinato. Al raggiungimento di 40 accumuli, aumenta l'indice di celerità di 125 per 8 s.\n\n Ogni accumulo di Insanguinato aumenta l'indice di critico di 2 ."}
MultiLanguageItemData['it'][168444] = {name = "[q6]Sangue Turbinante del Conquistato", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Sangue dei Nemici.\nRichiede l'impresa \"Stratega del Campo di Battaglia\". (Impossibile acquistare se già in possesso.)\nApprendi il Grado 3 di Sangue dei Nemici, Artificio del Tempo o Sfera della Soppressione su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Sangue dei Nemici\nIstantaneo 1.5 min di recupero Il Cuore di Azeroth erutta violentemente, infliggendo 1739 danni da ombra ai nemici entro 12 m. Fornisce un aumento del 25% alla probabilità di critico contro questi bersagli per 10 s. Inoltre, aumenta i danni critici da te inflitti del 25% per 5 s. \n Abilità minore:\n Insanguinato\nI colpi critici con gli incantesimi e le abilità forniscono 1 accumulo di Insanguinato, aumentando l'indice di critico di 2 . Al raggiungimento di 40 accumuli, aumenta anche l'indice di celerità di 125 per 8 s.\n\n Insanguinato ha una probabilità del 25% di consumare solo 30 accumuli."}
