MultiLanguageItemData['it'][168533] = {name = "[q3]Schema: Modulo Ultr4: P.O.G.O.", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Modulo Ultr4: P.O.G.O.\n[q2]Crea un Modulo Ultr4: P.O.G.O.\nRichiede Ingegneria di Kul Tiras (150)\nRichiedeResistenza di Bullonaccio\n- Riverito\n\n\nModulo Ultr4: P.O.G.O.\nSi vincola alla raccolta\nUnico\n[q2]Usa: Le tue invenzioni Ultr4 saranno un P.O.G.O.\nRichiede Ingegneria di Kul Tiras (50)\nRichiede Minerale di Monelite (5), Minerale di Argento della Tempesta (2), Bobina Isolata (15), Esplosivo Chimico (10)"}
MultiLanguageItemData['it'][168534] = {name = "[q3]Schema: Modulo Ultr4: Ultr4-Bobina", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Modulo Ultr4: Ultr4-Bobina.\n[q2]Crea un Modulo Ultr4: P.O.G.O.\nRichiede Ingegneria di Kul Tiras (150)\nRichiedeResistenza di Bullonaccio\n- Riverito\n\n\nModulo Ultr4: Ultr4-Bobina\nSi vincola alla raccolta\nUnico\n[q2]Usa: Le tue invenzioni Ultr4 saranno una Ultr4-Bobina.\nRichiede Ingegneria di Kul Tiras (50)\nRichiede Minerale di Monelite (5), Minerale di Argento della Tempesta (2), Bobina Isolata (15), Esplosivo Chimico (10)"}
MultiLanguageItemData['it'][168535] = {name = "[q3]Schema: Modulo Ultr4: Cannone di Scarti", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Modulo Ultr4: Cannone di Scarti.\n[q2]Crea un Modulo Ultr4: Cannone di Scarti.\nRichiede Ingegneria di Kul Tiras (150)\nRichiedeResistenza di Bullonaccio\n- Riverito\n\n\nModulo Ultr4: Cannone di Scarti\nSi vincola alla raccolta\nUnico\n[q2]Usa: Le tue invenzioni Ultr4 saranno un Cannone di Scarti.\nRichiede Ingegneria di Kul Tiras (50)\nRichiede Minerale di Monelite (5), Minerale di Argento della Tempesta (2), Bobina Isolata (15), Esplosivo Chimico (10)"}
MultiLanguageItemData['it'][168536] = {name = "[q6]Formazione d'Azerite Ricristallizzante", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Dono Imperituro di Azeroth.\nAbilità maggiore:\n Dono Imperituro di Azeroth\nIstantaneo 45 s di recupero Riduce tutti i danni subiti del 20% per 4 s. \n Abilità minore:\n Azerite Indurita\nQuando si raggiunge il 35% di salute restante, si ottiene 799 armatura per 8 s.\n\n L'effetto può verificarsi solo una volta ogni 120 s. (2.5m di recupero)"}
MultiLanguageItemData['it'][168537] = {name = "[q6]Formazione d'Azerite Temprata", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Dono Imperituro di Azeroth.\nApprendi il Grado 3 di Forza Vitale Condensata, Condotto della Vitalità o Dono Imperituro di Azeroth su un altro personaggio per sbloccare questa essenza.\nAbilità maggiore:\n Dono Imperituro di Azeroth\nIstantaneo 45 s di recupero Riduce tutti i danni subiti del 40% per 2 s, quindi del 20% per i successivi 2 s. \n Abilità minore:\n Azerite Indurita\nQuando si raggiunge il 35% di salute restante, si ottiene ( 799 * 200 / 100) armatura per 4 s, quindi 799 armatura per i successivi 4 s.\n\n L'effetto può verificarsi solo una volta ogni 120 s. (2.5m di recupero)"}
MultiLanguageItemData['it'][168538] = {name = "[q6]Formazione d'Azerite Abbagliante", additional_info = "Grado 4\nSi vincola alla raccolta\nUnicoClassi: Guerriero , Paladino , Cavaliere della Morte , Monaco , Druido , Cacciatore di Demoni\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Dono Imperituro di Azeroth.\nAbilità maggiore:\n Dono Imperituro di Azeroth\nIstantaneo 45 s di recupero Riduce tutti i danni subiti del 40% per 2 s, quindi del 20% per i successivi 2 s. \n Abilità minore:\n Azerite Indurita\nQuando si raggiunge il 35% di salute restante, si ottiene ( 799 * 200 / 100) armatura per 4 s, quindi 799 armatura per i successivi 4 s.\n\n L'effetto può verificarsi solo una volta ogni 120 s. (2.5m di recupero)"}
