MultiLanguageItemData['it'][168558] = {name = "[q6]Feticcio delle Segrete Profonde", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Anima della Vita e della Morte.\nAbilità maggiore:\n Anima della Morte\nIstantaneo 2 min di recupero La tua vitalità brucia i nemici, infliggendo danni da fuoco pari al 10% della tua salute massima a tutti i nemici vicini e rigenerando il 5% della tua salute massima per ogni nemico colpito, fino a un massimo del 25% della tua salute massima. \n Abilità minore:\n Anima della Vita\nL'energia d'Azerite scorre nelle tue vene, aumentando la salute massima di 244 ogni 5 s. Si accumula fino a 10 volte.\n\n È possibile ottenere un accumulo di Anima della Vita quando si uccide un nemico che fornisce onore o esperienza.\n\n L'effetto viene annullato se si scende al di sotto del 35% di salute."}
MultiLanguageItemData['it'][168559] = {name = "[q6]Feticcio dei Labirinti Nascosti", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Anima della Vita e della Morte.\nApprendi il Grado 3 di Iride Focalizzante, Invocazione della Protettrice della Vita o Anima della Vita e della Morte su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Anima della Morte\nIstantaneo 2 min di recupero La tua vitalità brucia i nemici, infliggendo danni da fuoco pari al 10% della tua salute massima a tutti i nemici vicini e rigenerando il 10% della tua salute massima per ogni nemico colpito, fino a un massimo del 50% della tua salute massima. \n Abilità minore:\n Anima della Vita\nL'energia d'Azerite scorre nelle tue vene, aumentando la salute massima di 244 ogni 5 s. Si accumula fino a 10 volte. Al raggiungimento del numero massimo di accumuli, cura di 185 salute ogni 5 s.\n\n È possibile ottenere un accumulo di Anima della Vita quando si uccide un nemico che fornisce onore o esperienza.\n\n L'effetto viene annullato se si scende al di sotto del 35% di salute."}
MultiLanguageItemData['it'][168560] = {name = "[q6]Feticcio delle Catacombe Dorate", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Anima della Vita e della Morte.\nAbilità maggiore:\n Anima della Morte\nIstantaneo 2 min di recupero La tua vitalità brucia i nemici, infliggendo danni da fuoco pari al 10% della tua salute massima a tutti i nemici vicini e rigenerando il 10% della tua salute massima per ogni nemico colpito, fino a un massimo del 50% della tua salute massima. \n Abilità minore:\n Anima della Vita\nL'energia d'Azerite scorre nelle tue vene, aumentando la salute massima di 244 ogni 5 s. Si accumula fino a 10 volte. Al raggiungimento del numero massimo di accumuli, cura di 185 salute ogni 5 s.\n\n È possibile ottenere un accumulo di Anima della Vita quando si uccide un nemico che fornisce onore o esperienza.\n\n L'effetto viene annullato se si scende al di sotto del 35% di salute."}
MultiLanguageItemData['it'][168566] = {name = "[q6]Unità di Raffreddamento della Forza Nulla", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Dinamo della Nullificazione.\nRichiede la reputazione Onorato dalla Resistenza di Bullonaccio. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Potenziamento Barriera Nulla\nIstantaneo 2.25 min di recupero Fornisce una Barriera Nulla potenziata, assorbendo [ 11391 * (1 + Versatilità)] danni magici per 10 s. \n Abilità minore:\n Barriera Nulla\nOgni 15 s si ottiene una Barriera Nulla, assorbendo i successivi [ 2268 * (1 + Versatilità)] danni magici subiti per 10 s."}
MultiLanguageItemData['it'][168568] = {name = "[q6]Abolitore della Forza Nulla", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Dinamo della Nullificazione.\nRichiede la reputazione Riverito dalla Resistenza di Bullonaccio. (Impossibile acquistare se già in possesso.)\nApprendi il Grado 3 di una qualunque Essenza della Resistenza di Bullonaccio su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Potenziamento Barriera Nulla\nIstantaneo 2.25 min di recupero Fornisce una Barriera Nulla potenziata, assorbendo [ 11391 * (1 + Versatilità)] danni magici per 10 s e rimuovendo istantaneamente tutti gli effetti dannosi magici, le maledizioni, i veleni e le malattie su di te. \n Abilità minore:\n Barriera Nulla\nOgni 15 s si ottiene una Barriera Nulla, assorbendo i successivi [ 2268 * (1 + Versatilità)] danni magici subiti per 10 s.\n\n Quando la Barriera Nulla termina, implode, infliggendo danni da ombra pari ai danni totali assorbiti suddivisi tra tutti i nemici vicini."}
MultiLanguageItemData['it'][168569] = {name = "[q6]Visualizzatore della Forza Nulla", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Dinamo della Nullificazione.\nAbilità maggiore:\n Potenziamento Barriera Nulla\nIstantaneo 2.25 min di recupero Fornisce una Barriera Nulla potenziata, assorbendo [ 11391 * (1 + Versatilità)] danni magici per 10 s e rimuovendo istantaneamente tutti gli effetti dannosi magici, le maledizioni, i veleni e le malattie su di te. \n Abilità minore:\n Barriera Nulla\nOgni 15 s si ottiene una Barriera Nulla, assorbendo i successivi [ 2268 * (1 + Versatilità)] danni magici subiti per 10 s.\n\n Quando la Barriera Nulla termina, implode, infliggendo danni da ombra pari ai danni totali assorbiti suddivisi tra tutti i nemici vicini."}
MultiLanguageItemData['it'][168573] = {name = "[q6]Foglia Resistente alla Morte", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Tocco dell'Eterno.\nAbilità maggiore:\n Tocco dell'Eterno\nUn attacco altrimenti letale ti fa rigenerare il 20% della salute massima e riduce i danni subiti del 85% per 3 s.\n\n L'effetto non può attivarsi più di una volta ogni 10 min. \n Abilità minore:\n Volontà di Sopravvivenza\nQuando si ha meno del 35% della salute massima, l'indice d'elusione aumenta di 55 per 15 s, e la successiva Abilità difensiva dura il 30% in più . L'effetto può verificarsi solo una volta ogni 1.5 min.\n\nUnico: Resistenza alla Corruzione aumentata di 10.\n[q]\"Prospera nel vento.\""}
MultiLanguageItemData['it'][168574] = {name = "[q6]Corteccia Vivente Pietrificata", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Tocco dell'Eterno.\nAbilità maggiore:\n Tocco dell'Eterno\nUn attacco altrimenti letale ti fa rigenerare il 40% della salute massima e riduce i danni subiti del 85% per 3 s.\n\n L'effetto non può verificarsi più di una volta ogni 10 min. \n Abilità minore:\n Volontà di Sopravvivenza\nQuando si ha meno del 35% della salute massima, l'indice d'elusione aumenta di 55 per 15 s, e la successiva Abilità difensiva dura il 30% in più . L'effetto può verificarsi solo una volta ogni 60 s.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
MultiLanguageItemData['it'][168575] = {name = "[q6]Ramo degli Anelli Rinvigorenti", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Tocco dell'Eterno.\nApprendi il Grado 3 di una qualunque essenza dei Rajani o della Coalizione di Uldum su un altro personaggio per sbloccare questa essenza.\nRichiede la reputazione Riverito con i Rajani. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Tocco dell'Eterno\nUn attacco altrimenti letale ti fa rigenerare il 40% della salute massima e riduce i danni subiti del 85% per 3 s.\n\n Quando si evita la morte, il tempo di recupero di Muro di Scudi si azzera.\n\n L'effetto non può attivarsi più di una volta ogni 10 min. \n Abilità minore:\n Volontà di Sopravvivenza\nQuando si ha meno del 35% della salute massima, l'indice d'elusione aumenta di 55 per 15 s, e la successiva Abilità difensiva dura il 50% in più . L'effetto può verificarsi solo una volta ogni 60 s.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
MultiLanguageItemData['it'][168576] = {name = "[q6]Radici del Risveglio Magnifico", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Tocco dell'Eterno.\nAbilità maggiore:\n Tocco dell'Eterno\nUn attacco altrimenti letale ti fa rigenerare il 40% della salute massima e riduce i danni subiti del 85% per 3 s.\n\n Quando si evita la morte, il tempo di recupero di Muro di Scudi si azzera.\n\n L'effetto non può attivarsi più di una volta ogni 10 min. \n Abilità minore:\n Volontà di Sopravvivenza\nQuando si ha meno del 35% della salute massima, l'indice d'elusione aumenta di 55 per 15 s, e la successiva Abilità difensiva dura il 50% in più . L'effetto può verificarsi solo una volta ogni 60 s.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
