MultiLanguageItemData['it'][168611] = {name = "[q6]Scaglia d'Ebano Pietrificata", additional_info = "Grado 1\nOggetto di missione\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Crogiolo delle Fiamme.\nAbilità maggiore:\n Fiamma Concentrata\nPortata di 40 m Istantaneo 30 s di recupero 1 Carico Colpisce il bersaglio con una sfera di fiamme concentrate, infliggendo [ 824 * (1 + Versatilità)] danni da fuoco a un nemico o curando un alleato di [ 824 * (1 + Versatilità)] salute .\n\n Ogni lancio di Fiamma Concentrata infligge danni o fornisce cure aumentati del 100%. Questo bonus viene azzerato a ogni terzo lancio. \n Abilità minore:\n Fiamma Antica\nCirca 3 apparenze ogni minuto Gli incantesimi e le abilità hanno una probabilità di cauterizzare il bersaglio, infliggendo ( 351 * 5) danni da fuoco a un nemico in 10 s o rigenerando ( 351 * 5) salute a un alleato in 10 s .\n[q]\"Questa scaglia antica, che incarna la terra stessa, è stata temprata dal fuoco d'ebano.\""}
MultiLanguageItemData['it'][168612] = {name = "[q6]Scaglia di Drago del Sogno di Smeraldo", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Crogiolo delle Fiamme.\nAbilità maggiore:\n Fiamma Concentrata\nPortata di 40 m Istantaneo 30 s di recupero 1 Carico Colpisce il bersaglio con una sfera di fiamme concentrate, infliggendo [ 824 * (1 + Versatilità)] danni da fuoco a un nemico o curando un alleato di [ 824 * (1 + Versatilità)] salute, quindi brucia un bersaglio infliggendo il 75% dei danni inflitti o delle cure fornite in 6 s.\n\n Ogni lancio di Fiamma Concentrata infligge danni o fornisce cure aumentati del 100%. Questo bonus viene azzerato a ogni terzo lancio. \n Abilità minore:\n Fiamma Antica\nCirca 1.25 apparenze ogni minuto Gli incantesimi e le abilità hanno una probabilità di cauterizzare il bersaglio, infliggendo [ 351 * 5 * (1.25)] danni da fuoco a un nemico in 10 s o rigenerando [ 351 * 5 * (1.25)] salute a un alleato in 10 s.\n[q]\"La scaglia ripristinata irradia la luce del Sogno di Smeraldo e l'essenza dello Stormo dei Draghi Verdi.\""}
MultiLanguageItemData['it'][168613] = {name = "[q6]Scaglia Temprata della Madre della Stirpe Scarlatta", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Crogiolo delle Fiamme.\nApprendi il Grado 3 di Crogiolo delle Fiamme su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Fiamma Concentrata\nPortata di 40 m Istantaneo 30 s di recupero 1 Carico Colpisce il bersaglio con una sfera di fiamme concentrate, infliggendo [ 824 * (1 + Versatilità)] danni da fuoco a un nemico o curando un alleato di [ 824 * (1 + Versatilità)] salute, quindi brucia un bersaglio infliggendo il 75% dei danni inflitti o delle cure fornite in 6 s.\n\n Ogni lancio di Fiamma Concentrata infligge danni o fornisce cure aumentati del 100%. Questo bonus viene azzerato a ogni terzo lancio.\nMassimo 2 cariche. \n Abilità minore:\n Fiamma Antica\nCirca 1.25 apparenze ogni minuto Gli incantesimi e le abilità hanno una probabilità di cauterizzare il bersaglio, infliggendo [ 351 * 5 * (1.25)] danni da fuoco a un nemico in 10 s o rigenerando [ 351 * 5 * (1.25)] salute a un alleato in 10 s. Si accumula fino a 3 volte.\n[q]\"Vibranti dell'energia della vita, le fiamme della Protettrice della Vita guizzano e danzano sulla superficie della scaglia.\""}
MultiLanguageItemData['it'][168614] = {name = "[q6]Scaglia Carica dell'Aspetto Blu", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Crogiolo delle Fiamme.\nAbilità maggiore:\n Fiamma Concentrata\nPortata di 40 m Istantaneo 30 s di recupero 1 Carico Colpisce il bersaglio con una sfera di fiamme concentrate, infliggendo [ 824 * (1 + Versatilità)] danni da fuoco a un nemico o curando un alleato di [ 824 * (1 + Versatilità)] salute, quindi brucia un bersaglio infliggendo il 75% dei danni inflitti o delle cure fornite in 6 s.\n\n Ogni lancio di Fiamma Concentrata infligge danni o fornisce cure aumentati del 100%. Questo bonus viene azzerato a ogni terzo lancio.\nMassimo 2 cariche. \n Abilità minore:\n Fiamma Antica\nCirca 1.25 apparenze ogni minuto Gli incantesimi e le abilità hanno una probabilità di cauterizzare il bersaglio, infliggendo [ 351 * 5 * (1.25)] danni da fuoco a un nemico in 10 s o rigenerando [ 351 * 5 * (1.25)] salute a un alleato in 10 s. Si accumula fino a 3 volte.\n[q]\"Una scoppiettante scintilla magica blu si muove tutt'intorno alla scaglia dell'incarnazione del grande Aspetto.\""}
MultiLanguageItemData['it'][168615] = {name = "[q6]Vena del Mondo Instabile", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Risonanza della Vena del Mondo.\nAbilità maggiore:\n Risonanza della Vena del Mondo\nIstantaneo 1 min di recupero Concentra l'energia nel Cuore di Azeroth, facendo eruttare istantaneamente dal terreno 2 Schegge di Sangue Vitale per 12 s e aumentando l'attributo primario fornito dalle Schegge di Sangue Vitale del 300% per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 8 m da una Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta. \n Abilità minore:\n Sangue Vitale\nOgni 18-25 s, una Scheggia di Sangue Vitale erutta dal terreno circostante per 12 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 12 m dalla Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta.\n[q]\"Questa Vena del Mondo pulsa con un'energia che attira l'Azerite, rafforzando chiunque la maneggi.\""}
MultiLanguageItemData['it'][168616] = {name = "[q6]Vena del Mondo Solida", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Risonanza della Vena del Mondo.\nAbilità maggiore:\n Risonanza della Vena del Mondo\nIstantaneo 1 min di recupero Concentra l'energia nel Cuore di Azeroth, facendo eruttare istantaneamente dal terreno 3 Schegge di Sangue Vitale per 18 s e aumentando l'attributo primario fornito dalle Schegge di Sangue Vitale del 300% per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 8 m da una Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta. \n Abilità minore:\n Sangue Vitale\nOgni 18-25 s, una Scheggia di Sangue Vitale erutta dal terreno circostante per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 8 m dalla Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta.\n[q]\"Questa Vena del Mondo è solida e sembra potenziare l'Azerite che la circonda.\""}
MultiLanguageItemData['it'][168617] = {name = "[q6]Vena del Mondo Fluttuante", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Risonanza della Vena del Mondo.\nApprendi il Grado 3 di Risonanza della Vena del Mondo su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Risonanza della Vena del Mondo\nIstantaneo 1 min di recupero Concentra l'energia nel Cuore di Azeroth, facendo eruttare istantaneamente dal terreno 3 Schegge di Sangue Vitale per 18 s e aumentando l'attributo primario fornito dalle Schegge di Sangue Vitale del 300% per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 12 m da una Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta. \n Abilità minore:\n Sangue Vitale\nOgni 1-25 s, una Scheggia di Sangue Vitale erutta dal terreno circostante per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 12 m dalla Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta.\n[q]\"Questa Vena del Mondo ha una vibrazione interna molto intensa, attraendo più frequentemente le Schegge d'Azerite.\""}
MultiLanguageItemData['it'][168618] = {name = "[q6]Vena del Mondo Brillante", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Risonanza della Vena del Mondo.\nAbilità maggiore:\n Risonanza della Vena del Mondo\nIstantaneo 1 min di recupero Concentra l'energia nel Cuore di Azeroth, facendo eruttare istantaneamente dal terreno 3 Schegge di Sangue Vitale per 18 s e aumentando l'attributo primario fornito dalle Schegge di Sangue Vitale del 300% per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 12 m da una Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta. \n Abilità minore:\n Sangue Vitale\nOgni 1-25 s, una Scheggia di Sangue Vitale erutta dal terreno circostante per 18 s.\n\nScheggia di Sangue Vitale\n Aumenta l'attributo primario di se stessi e di tutti gli alleati con Risonanza della Vena del Mondo entro 12 m dalla Scheggia di Sangue Vitale di 13 . È possibile beneficiare di massimo 4 Schegge di Sangue Vitale alla volta.\n[q]\"La brillantezza e l'intensità di questa Vena del Mondo sono fonte di grande ispirazione.\""}
