MultiLanguageItemData['it'][168826] = {name = "[q4]Pacificatore di Meccagon", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Mantiene la pace facendoti a pezzi.\"\nBottino:\nUnità di Oppressione Aerea HK-8\nZona:\nOperazione: Meccagon (Mitica)"}
MultiLanguageItemData['it'][168827] = {name = "[q4]Meccaragno di Scarti", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Costruito a mano, con tanto coraggio. Tutto ciò che serve per un buon retaggio.\"\nMissione:\nPronto per la consegna\nZona:\nMeccagon"}
