MultiLanguageItemData['it'][168829] = {name = "[q4]Resistore di Bullonaccio", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeResistenza di Bullonaccio\n- Osannato\n\n\n[q]\"R E S I S T E R E\" è stato intagliato sul sedile, insieme ad altre cose decisamente più scurrili.\nMercante:\nVenditore Robotico Reale Rubato\nZona:\nMeccagon\nFazione:\nResistenza di Bullonaccio - Osannato\nCosto:\n524."}
MultiLanguageItemData['it'][168830] = {name = "[q4]Unità Aerea R-21/X", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Unità aerea privata di Re Meccagon, completa di un cannone riposizionabile e scaldapiedi.\"\nBottino:\nRe Meccagon"}
