MultiLanguageItemData['it'][168837] = {name = "[q6]Egida Forgiata del Profondo", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Egida del Profondo.\nRichiede la reputazione Amichevole dai Liberti. (Impossibile acquistare se già in possesso.)\nRichiede la reputazione Amichevole dagli Ankoan. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Egida del Profondo\nIstantaneo 1.5 min di recupero Gli elementi ti proteggono, riducendo i danni subiti da ogni attacco di 395 per 15 s . \n Abilità minore:\n Non Cedere il Passo\nAumenta l'indice di versatilità di 13 per ogni nemico entro 10 m, fino a un massimo di ( 13 * 10) indice di versatilità."}
MultiLanguageItemData['it'][168838] = {name = "[q6]Barricata Duratura delle Profondità", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Egida del Profondo.\nRichiede la reputazione Onorato dai Liberti. (Impossibile acquistare se già in possesso.)\nRichiede la reputazione Onorato dagli Ankoan. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Egida del Profondo\nIstantaneo 1.133 min di recupero Gli elementi ti proteggono, riducendo i danni subiti da ogni attacco di 395 per 15 s. \n Abilità minore:\n Non Cedere il Passo\nAumenta l'indice di versatilità di 13 per ogni nemico entro 10 m, fino a un massimo di ( 13 * 10) indice di versatilità. Quando si ha meno del 35% di salute massima, l'indice di versatilità raddoppia."}
MultiLanguageItemData['it'][168839] = {name = "[q6]Barriera Rigenerante delle Profondità", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Egida del Profondo.\nApprendi il Grado 3 di una qualunque Essenza della reputazione di Nazjatar su un altro personaggio per sbloccare questa Essenza.\nRichiede la reputazione Riverito dai Liberti. (Impossibile acquistare se già in possesso.)\nRichiede la reputazione Riverito dagli Ankoan. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Egida del Profondo\nIstantaneo 1.133 min di recupero Gli elementi ti proteggono, riducendo i danni subiti da ogni attacco di 395 per 15 s e, quando l'Egida del Profondo termina, aumentando l'indice d'elusione di 27 per 6 s. \n Abilità minore:\n Non Cedere il Passo\nAumenta l'indice di versatilità di 13 per ogni nemico entro 10 m, fino a un massimo di ( 13 * 10) indice di versatilità. Quando si ha meno del 35% di salute massima, l'indice di versatilità raddoppia.\n\n Inoltre, rigenera 208 salute ogni 4 s per ogni accumulo di Non Cedere il Passo."}
MultiLanguageItemData['it'][168840] = {name = "[q6]Bastione Risplendente delle Profondità", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Egida del Profondo.\nAbilità maggiore:\n Egida del Profondo\nIstantaneo 1.133 min di recupero Gli elementi ti proteggono, riducendo i danni subiti da ogni attacco di 395 per 15 s e, quando l'Egida del Profondo termina, aumentando l'indice d'elusione di 27 per 6 s. \n Abilità minore:\n Non Cedere il Passo\nAumenta l'indice di versatilità di 13 per ogni nemico entro 10 m, fino a un massimo di ( 13 * 10) indice di versatilità. Quando si ha meno del 35% di salute massima, l'indice di versatilità raddoppia.\n\n Inoltre, rigenera 208 salute ogni 4 s per ogni accumulo di Non Cedere il Passo."}
MultiLanguageItemData['it'][168841] = {name = "Pergamena degli Shirakess", additional_info = "Oggetto di missione\nUnico (8)\n[q]\"Incantesimi oscuri si contorcono su tutta la superficie della pergamena.\""}
MultiLanguageItemData['it'][168842] = {name = "[q6]Congegno della Meccaperfezione", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Visione della Perfezione.\nAbilità maggiore:\n Visione della Perfezione\nGli incantesimi e le abilità hanno una probabilità di attivare per il 25% della sua durata base . \n Abilità minore:\n Ricerca della Perfezione\nRiduce il tempo di recupero di del [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% .\n[q]\"Costruito su un antico dispositivo dei Titani, questo congegno è un trionfo d'ingegnosità gnomesca e consente ai costrutti meccanici di raggiungere prestazioni eccellenti.\""}
MultiLanguageItemData['it'][168843] = {name = "[q6]Differenziale Perfettamente a Tempo", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Visione della Perfezione.\nAbilità maggiore:\n Visione della Perfezione\nGli incantesimi e le abilità hanno una probabilità di attivare per il 35% della sua durata base . \n Abilità minore:\n Ricerca della Perfezione\nRiduce il tempo di recupero di del [(( 6849 + 3320) /- 100) ; Min 10, Max 25]%.\n\n Rigenera istantaneamente il 5% della salute massima quando si attiva ."}
MultiLanguageItemData['it'][168844] = {name = "[q6]Scatola Ingegneristica del Potenziamento Perfetto", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Visione della Perfezione.\nApprendi il Grado 3 di Visione della Perfezione su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Visione della Perfezione\nGli incantesimi e le abilità hanno una probabilità di attivare per il 35% della sua durata base .\n\n Quando Visione della Perfezione si attiva, aumenta l'indice di celerità tuo e di massimo 2 alleati vicini di 24 per 10 s. \n Abilità minore:\n Ricerca della Perfezione\nRiduce il tempo di recupero di del [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% e aumenta l'indice di versatilità di 18 .\n\n Rigenera istantaneamente il 5% della salute massima quando si attiva ."}
MultiLanguageItemData['it'][168845] = {name = "[q6]Turbina della Meccaperfezione", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Visione della Perfezione.\nAbilità maggiore:\n Visione della Perfezione\nGli incantesimi e le abilità hanno una probabilità di attivare per il 35% della sua durata base .\n\n Quando Visione della Perfezione si attiva, aumenta l'indice di celerità tuo e di massimo 2 alleati vicini di 24 per 10 s. \n Abilità minore:\n Ricerca della Perfezione\nRiduce il tempo di recupero di del [(( 6849 + 3320) /- 100) ; Min 10, Max 25]% e aumenta l'indice di versatilità di 18 .\n\n Rigenera istantaneamente il 5% della salute massima quando si attiva .\n[q]\"Migliorando il Congegno della Meccaperfezione, questa turbina ha il potenziale per scatenare enormi quantità di energia titanica in un singolo istante.\""}
MultiLanguageItemData['it'][168846] = {name = "[q6]Perla dei Sogni Lucidi", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Memoria dei Sogni Lucidi.\nAbilità maggiore:\n Memoria dei Sogni Lucidi\nIstantaneo 2 min di recupero Libera la mente e la sintonizza con il Cuore di Azeroth, aumentando la velocità di generazione della risorsa del 100% per 12 s. \n Abilità minore:\n Sogni Lucidi\nGli incantesimi e le abilità hanno una probabilità di ripristinare il 50% della risorsa consumata e di curarti di [ 764 * (1 + Versatilità)] ."}
MultiLanguageItemData['it'][168847] = {name = "[q6]Perla delle Ambizioni Manifeste", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Memoria dei Sogni Lucidi.\nRichiede l'impresa \"Gita negli abissi\". (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Memoria dei Sogni Lucidi\nIstantaneo 2 min di recupero Libera la mente e la sintonizza con il Cuore di Azeroth, aumentando la velocità di generazione della risorsa del 100% per 15 s. \n Abilità minore:\n Sogni Lucidi\nGli incantesimi e le abilità hanno una probabilità di ripristinare il 50% della risorsa consumata e di curarti di [ 764 * 1.5 * (1 + Versatilità)] ."}
MultiLanguageItemData['it'][168848] = {name = "[q6]Perla delle Intenzioni Evidenti", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Memoria dei Sogni Lucidi.\nApprendi il Grado 3 di Memoria dei Sogni Lucidi su un altro personaggio per sbloccare questa Essenza.\nRichiede l'impresa \"Addestramento di guerre nautiche\". (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Memoria dei Sogni Lucidi\nIstantaneo 2 min di recupero Libera la mente e la sintonizza con il Cuore di Azeroth, aumentando la velocità di generazione della risorsa del 100% e l'indice di ritorno vitale di 66 per 15 s. \n Abilità minore:\n Sogni Lucidi\nGli incantesimi e le abilità hanno una probabilità di ripristinare il 50% della risorsa consumata , di curare di [ 764 * (1.5) * (1 + Versatilità)] e di aumentare il tuo indice di versatilità di 74 per 8 s."}
MultiLanguageItemData['it'][168849] = {name = "[q6]Perla dei Progetti Brillanti", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Memoria dei Sogni Lucidi.\nAbilità maggiore:\n Memoria dei Sogni Lucidi\nIstantaneo 2 min di recupero Libera la mente e la sintonizza con il Cuore di Azeroth, aumentando la velocità di generazione della risorsa del 100% e l'indice di ritorno vitale di 66 per 15 s. \n Abilità minore:\n Sogni Lucidi\nGli incantesimi e le abilità hanno una probabilità di ripristinare il 50% della risorsa consumata , di curare di [ 764 * (1.5) * (1 + Versatilità)] e di aumentare il tuo indice di versatilità di 74 per 8 s."}
MultiLanguageItemData['it'][168850] = {name = "[q6]Ricordo del Campo di Battaglia Perduto", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Increspatura Spaziale\nAbilità maggiore:\n Increspatura Spaziale\nPortata di 25 m Istantaneo 1 min di recupero Crea un faro d'Azerite sulla posizione bersaglio. Dopo 4 s, il Cuore di Azeroth ti sposta verso questo faro, infliggendo 1451 danni da fuoco a tutti i nemici vicini. \n Abilità minore:\n Cambio di Realtà\nSe ci si sposta di più di 25 m in 4 s, si ottiene 47 di un attributo primario per 15 s.\n\n L'effetto può verificarsi solo una volta ogni 30 s.\n[q]\"I ricordi del passato hanno un potere profondo, capace di far rivivere momenti di grande importanza.\""}
MultiLanguageItemData['it'][168851] = {name = "[q6]Ricordo del Campo di Battaglia Persistente", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Increspatura Spaziale\nRichiede l'impresa \"In guerra su due fronti\". (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Increspatura Spaziale\nPortata di 25 m Istantaneo 1 min di recupero Crea un faro d'Azerite sulla posizione bersaglio. Dopo 2 s, il Cuore di Azeroth ti sposta verso questo faro, infliggendo 1451 danni da fuoco a tutti i nemici vicini. \n Abilità minore:\n Cambio di Realtà\nSe ci si sposta di più di 25 m in 4 s, si ottiene 47 di un attributo primario per 20 s.\n\n L'effetto può verificarsi solo una volta ogni 30 s."}
MultiLanguageItemData['it'][168852] = {name = "[q6]Ricordo del Campo di Battaglia Fedele", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Increspatura Spaziale\nApprendi il Grado 3 di Increspatura Spaziale su un altro personaggio per sbloccare questa Essenza.\nNon possiedi abbastanza Riconoscimenti della Chiamata alle Armi per acquistare l'oggetto.\nAbilità maggiore:\n Increspatura Spaziale\nPortata di 25 m Istantaneo 1 min di recupero Crea un faro d'Azerite sulla posizione bersaglio. Dopo 2 s, il Cuore di Azeroth ti sposta verso questo faro, infliggendo 1451 danni da fuoco a tutti i nemici vicini.\n\n Per 10 s dopo essere stati spostati, si subiscono danni ridotti del 10%. \n Abilità minore:\n Cambio di Realtà\nAumenta la velocità di movimento del 5%, e se ci si sposta di più di 25 m in 4 s, si ottiene 47 di un attributo primario per 20 s.\n\n L'effetto può verificarsi solo una volta ogni 30 s."}
MultiLanguageItemData['it'][168853] = {name = "[q6]Ricordo del Campo di Battaglia Luccicante", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Increspatura Spaziale\nAbilità maggiore:\n Increspatura Spaziale\nPortata di 25 m Istantaneo 1 min di recupero Crea un faro d'Azerite sulla posizione bersaglio. Dopo 2 s, il Cuore di Azeroth ti sposta verso questo faro, infliggendo 1451 danni da fuoco a tutti i nemici vicini.\n\n Per 10 s dopo essere stati spostati, si subiscono danni ridotti del 10%. \n Abilità minore:\n Cambio di Realtà\nAumenta la velocità di movimento del 5%, e se ci si sposta di più di 25 m in 4 s, si ottiene 47 di un attributo primario per 20 s.\n\n L'effetto può verificarsi solo una volta ogni 30 s."}
MultiLanguageItemData['it'][168854] = {name = "[q6]Cuore Elementale Animato", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Forza Vitale Condensata.\nAbilità maggiore:\n Guardiano di Azeroth\nIstantaneo 3 min di recupero Richiama il potere di Azeroth per evocare un Guardiano di Azeroth per 30 s, che impala il bersaglio con Spuntoni d'Azerite ogni 2.5 s, infliggendo [ 660 * (1 + Versatilità)] danni da fuoco. \n Abilità minore:\n Forza Vitale Condensata\nCirca 2 apparenze ogni minuto Gli incantesimi e le abilità hanno un'alta probabilità di impalare il bersaglio con uno spuntone d'Azerite, infliggendo [ 660 * (1 + Versatilità)] danni da fuoco.\n[q]\"Anche i più maestosi Signori Elementali nascono da semplici cuori di pietra.\""}
MultiLanguageItemData['it'][168855] = {name = "[q6]Cuore Elementale Pulsante", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Forza Vitale Condensata.\nAbilità maggiore:\n Guardiano di Azeroth\nIstantaneo 3 min di recupero Richiama il potere di Azeroth per evocare per 30 s un Guardiano di Azeroth, che impala il bersaglio con Spuntoni d'Azerite ogni 2.5 s, infliggendo [ 660 * (1 + Versatilità) * (1.25)] danni da fuoco. Ogni 8 s, il Guardiano di Azeroth lancia una raffica di Spuntoni d'Azerite sul bersaglio, infliggendo 670 danni da fuoco a tutti i nemici vicini. \n Abilità minore:\n Forza Vitale Condensata\nCirca 2 apparenze ogni minuto Gli incantesimi e le abilità hanno un'alta probabilità di impalare il bersaglio con uno spuntone d'Azerite, infliggendo [ 660 * (1 + Versatilità) * (1.25)] danni da fuoco.\n[q]\"Anche i più maestosi Signori Elementali nascono da semplici cuori di pietra.\""}
MultiLanguageItemData['it'][168856] = {name = "[q6]Cuore Elementale Risonante", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Forza Vitale Condensata.\nApprendi il Grado 3 di Forza Vitale Condensata, Condotto della Vitalità o Dono Imperituro di Azeroth su un altro personaggio per sbloccare questa essenza.\nAbilità maggiore:\n Guardiano di Azeroth\nIstantaneo 3 min di recupero Richiama il potere di Azeroth per evocare per 30 s un Guardiano di Azeroth, che impala il bersaglio con Spuntoni d'Azerite ogni 2.5 s, infliggendo [ 660 * (1 + Versatilità) * (1.25)] danni da fuoco. Ogni 8 s, il Guardiano di Azeroth lancia una raffica di Spuntoni d'Azerite sul bersaglio, infliggendo 670 danni da fuoco a tutti i nemici vicini.\n\n Ogni volta che il Guardiano di Azeroth lancia un incantesimo, aumenta la tua celerità del 2%. Si accumula fino a 5 volte. L'effetto termina quando il Guardiano di Azeroth scompare. \n Abilità minore:\n Forza Vitale Condensata\nCirca 2 apparenze ogni minuto Gli incantesimi e le abilità hanno un'alta probabilità di impalare il bersaglio con uno spuntone d'Azerite, infliggendo [ 660 * (1 + Versatilità) * (1.25)] danni da fuoco.\n\n Quando uno spuntone d'Azerite infligge danni, aumenta tutti i danni da te inflitti a quel bersaglio del 3% per 6 s.\n[q]\"Anche i più maestosi Signori Elementali nascono da semplici cuori di pietra.\""}
MultiLanguageItemData['it'][168857] = {name = "[q6]Cuore Elementale Scintillante", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Forza Vitale Condensata.\nAbilità maggiore:\n Guardiano di Azeroth\nIstantaneo 3 min di recupero Richiama il potere di Azeroth per evocare per 30 s un Guardiano di Azeroth, che impala il bersaglio con Spuntoni d'Azerite ogni 2.5 s, infliggendo [ 660 * (1 + Versatilità) * (1.25)] danni da fuoco. Ogni 8 s, il Guardiano di Azeroth lancia una raffica di Spuntoni d'Azerite sul bersaglio, infliggendo 670 danni da fuoco a tutti i nemici vicini.\n\n Ogni volta che il Guardiano di Azeroth lancia un incantesimo, aumenta la tua celerità del 2%. Si accumula fino a 5 volte. L'effetto termina quando il Guardiano di Azeroth scompare. \n Abilità minore:\n Forza Vitale Condensata\nCirca 2 apparenze ogni minuto Gli incantesimi e le abilità hanno un'alta probabilità di impalare il bersaglio con uno spuntone d'Azerite, infliggendo [ 660 * (1 + Versatilità) * (1.25)] danni da fuoco.\n\n Quando uno spuntone d'Azerite infligge danni, aumenta tutti i danni da te inflitti a quel bersaglio del 3% per 6 s.\n[q]\"Anche i più maestosi Signori Elementali nascono da semplici cuori di pietra.\""}
MultiLanguageItemData['it'][168858] = {name = "[q6]Protocolli di Purificazione Titanici", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Protocollo di Purificazione.\nRichiede la reputazione Amichevole dalla Resistenza di Bullonaccio. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Detonazione Purificante\nPortata di 40 m Istantaneo 1 min di recupero Richiama un raggio purificante sull'area bersaglio, infliggendo [ 395 * (1 + Versatilità) * 7] danni da fuoco in 6 s.\n\n Le Aberrazioni colpite dal raggio vengono stordite per 3 s. \n Abilità minore:\n Protocollo di Purificazione\nCirca 2 apparenze ogni minuto La M.A.D.R.E. ha aggiunto un Protocollo di Purificazione al tuo Cuore di Azeroth, permettendo ai tuoi incantesimi e abilità d'attacco di scatenare una detonazione d'Azerite contro il bersaglio, infliggendo [ 563 * (1 + Versatilità)] danni da fuoco a qualsiasi nemico entro 8 m .\n\n Il Protocollo di Purificazione infligge il 50% di danni aggiuntivi contro le Aberrazioni.\n[q]\"I Titani svilupparono protocolli per reagire alle eventuali corruzioni che Azeroth avrebbe potuto affrontare.\""}
MultiLanguageItemData['it'][168859] = {name = "[q6]Protocolli di Purificazione Concentrati", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Protocollo di Purificazione.\nRichiede la reputazione Onorato dalla Resistenza di Bullonaccio. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Detonazione Purificante\nPortata di 40 m Istantaneo 1 min di recupero Richiama un raggio purificante sull'area bersaglio, infliggendo [ 395 * (1 + Versatilità) * 7] danni da fuoco in 6 s. Ha una bassa probabilità di annientare istantaneamente ogni presenza giudicata non degna dalla M.A.D.R.E.\n\n Le Aberrazioni colpite dal raggio vengono stordite per 3 s. \n Abilità minore:\n Protocollo di Purificazione\nCirca 2 apparenze ogni minuto La M.A.D.R.E. ha aggiunto un Protocollo di Purificazione al tuo Cuore di Azeroth, permettendo ai tuoi incantesimi e abilità d'attacco di scatenare una detonazione d'Azerite contro il bersaglio, infliggendo [ 563 * (1 + Versatilità)] danni da fuoco a qualsiasi nemico entro 8 m e curandoti di [ 255 * (1 + Versatilità)] ogni 2 s per 8 s.\n\n Il Protocollo di Purificazione infligge il 50% di danni aggiuntivi contro le Aberrazioni.\n[q]\"Per i casi in cui serve una precisione estrema.\""}
MultiLanguageItemData['it'][168860] = {name = "[q6]Protocolli di Purificazione Potenziati", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Protocollo di Purificazione.\nRichiede la reputazione Riverito dalla Resistenza di Bullonaccio. (Impossibile acquistare se già in possesso.)\nApprendi il Grado 3 di una qualunque Essenza della Resistenza di Bullonaccio su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Detonazione Purificante\nPortata di 40 m Istantaneo 1 min di recupero Richiama un raggio purificante sull'area bersaglio, infliggendo [ 395 * (1 + Versatilità) * 7] danni da fuoco in 6 s. Ha una bassa probabilità di annientare istantaneamente ogni presenza giudicata non degna dalla M.A.D.R.E.\n\n Quando un nemico muore nell'area d'effetto del raggio, aumenta i tuoi danni del 10% per 8 s.\n\n Le Aberrazioni colpite dal raggio vengono stordite per 3 s. \n Abilità minore:\n Protocollo di Purificazione\nCirca 2 apparenze ogni minuto La M.A.D.R.E. ha aggiunto un Protocollo di Purificazione al tuo Cuore di Azeroth, permettendo ai tuoi incantesimi e abilità d'attacco di scatenare una detonazione d'Azerite contro il bersaglio, infliggendo [ 563 * (1.25) * (1 + Versatilità)] danni da fuoco a qualsiasi nemico entro 8 m e curandoti di [ 255 * (1 + Versatilità)] ogni 2 s per 8 s.\n\n Il Protocollo di Purificazione infligge il 50% di danni aggiuntivi contro le Aberrazioni.\n[q]\"Quando i precedenti protocolli hanno fallito.\""}
MultiLanguageItemData['it'][168861] = {name = "[q6]Protocolli di Purificazione Definitivi", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Protocollo di Purificazione.\nAbilità maggiore:\n Detonazione Purificante\nPortata di 40 m Istantaneo 1 min di recupero Richiama un raggio purificante sull'area bersaglio, infliggendo [ 395 * (1 + Versatilità) * 7] danni da fuoco in 6 s. Ha una bassa probabilità di annientare istantaneamente ogni presenza giudicata non degna dalla M.A.D.R.E.\n\n Quando un nemico muore nell'area d'effetto del raggio, aumenta i tuoi danni del 10% per 8 s.\n\n Le Aberrazioni colpite dal raggio vengono stordite per 3 s. \n Abilità minore:\n Protocollo di Purificazione\nCirca 2 apparenze ogni minuto La M.A.D.R.E. ha aggiunto un Protocollo di Purificazione al tuo Cuore di Azeroth, permettendo ai tuoi incantesimi e abilità d'attacco di scatenare una detonazione d'Azerite contro il bersaglio, infliggendo [ 563 * (1.25) * (1 + Versatilità)] danni da fuoco a qualsiasi nemico entro 8 m e curandoti di [ 255 * (1 + Versatilità)] ogni 2 s per 8 s.\n\n Il Protocollo di Purificazione infligge il 50% di danni aggiuntivi contro le Aberrazioni.\n[q]\"Quando tutto il resto fallisce.\""}
