MultiLanguageItemData['it'][168920] = {name = "[q6]Quarzo Temporale Incrostato d'Azerite", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Artificio del Tempo.\nAbilità maggiore:\n Immobilità\nPortata di 40 m Istantaneo 3 min di recupero Crea un vortice temporale attorno a un bersaglio alleato che assorbe 34942 danni e 34942 cure per 4 s. Al termine dell'effetto, le cure e i danni assorbiti vengono rilasciati periodicamente in 10 s . \n Abilità minore:\n Artificio del Tempo\nCirca 10 apparenze ogni minuto Le cure fornite hanno un'alta probabilità di aumentare l'indice di celerità del bersaglio di 72 per 6 s.\n[q]\"C'è sempre tempo per una pausa, in battaglia.\""}
MultiLanguageItemData['it'][168921] = {name = "[q6]Quarzo Temporale Infuso d'Azerite", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Artificio del Tempo.\nRichiede l'impresa \"Rissaiolo da battaglia\". (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Immobilità\nPortata di 40 m Istantaneo 3 min di recupero Crea un vortice temporale attorno a un bersaglio alleato che assorbe 34942 danni e 34942 cure per 6 s. Al termine dell'effetto, le cure e i danni assorbiti vengono rilasciati periodicamente in 10 s . \n Abilità minore:\n Artificio del Tempo\nCirca 10 apparenze ogni minuto Le cure fornite hanno un'alta probabilità di aumentare l'indice di celerità del bersaglio di 86 per 8 s.\n[q]\"C'è sempre tempo per una pausa, in battaglia.\""}
MultiLanguageItemData['it'][168922] = {name = "[q6]Quarzo Temporale Alimentato ad Azerite", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Artificio del Tempo.\nRichiede l'impresa \"Stratega del Campo di Battaglia\". (Impossibile acquistare se già in possesso.)\nApprendi il Grado 3 di Sangue dei Nemici, Artificio del Tempo o Sfera della Soppressione su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Immobilità\nPortata di 40 m Istantaneo 3 min di recupero Crea un vortice temporale attorno a un bersaglio alleato che assorbe 34942 danni e 34942 cure per 6 s. Al termine dell'effetto, le cure e i danni assorbiti vengono rilasciati periodicamente in 10 s e i danni vengono ridotti del 20%. \n Abilità minore:\n Artificio del Tempo\nCirca 10 apparenze ogni minuto Le cure fornite hanno un'alta probabilità di aumentare l'indice di celerità del bersaglio di 86 e la sua velocità di movimento di 72 per 8 s.\n[q]\"C'è sempre tempo per una pausa, in battaglia.\""}
MultiLanguageItemData['it'][168923] = {name = "[q6]Quarzo Temporale Alleggerito d'Azerite", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Artificio del Tempo.\nAbilità maggiore:\n Immobilità\nPortata di 40 m Istantaneo 3 min di recupero Crea un vortice temporale attorno a un bersaglio alleato che assorbe 34942 danni e 34942 cure per 6 s. Al termine dell'effetto, le cure e i danni assorbiti vengono rilasciati periodicamente in 10 s e i danni vengono ridotti del 20%. \n Abilità minore:\n Artificio del Tempo\nCirca 10 apparenze ogni minuto Le cure fornite hanno un'alta probabilità di aumentare l'indice di celerità del bersaglio di 86 e la sua velocità di movimento di 72 per 8 s.\n[q]\"C'è sempre tempo per una pausa, in battaglia.\""}
MultiLanguageItemData['it'][168924] = {name = "[q6]Seme della Vita Esplosivo", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Invocazione della Protettrice della Vita.\nAbilità maggiore:\n Invocazione della Protettrice della Vita\n2.5 s di lancio 2.5 min di recupero Pianta 30 Semi di Eonar suddivisi tra tutti gli alleati entro 30 m.\n\n Seme di Eonar\nSe il bersaglio subisce danni, il seme sboccia, curandolo di 436 . \n Abilità minore:\n Seme di Eonar\nCirca 15 apparenze ogni minuto Le cure fornite hanno un'alta probabilità di piantare un Seme di Eonar nel bersaglio per 12 s.\n\nSeme di Eonar\nSe il bersaglio subisce danni, il seme sboccia, curandolo di 436 .\n[q]\"Eonar fece piovere su Azeroth i primi semi della vita, ma solo pochi conservano ancora dentro di sé il potere del Titano.\""}
MultiLanguageItemData['it'][168925] = {name = "[q6]Seme dell'Abbondanza Replicante", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Invocazione della Protettrice della Vita.\nAbilità maggiore:\n Invocazione della Protettrice della Vita\n2.5 s di lancio 2.5 min di recupero Pianta 40 Semi di Eonar suddivisi tra tutti gli alleati entro 30 m.\n\n Seme di Eonar\nSe il bersaglio subisce danni, il seme sboccia, curandolo di 436 . \n Abilità minore:\n Seme di Eonar\nCirca 15 apparenze ogni minuto Le cure fornite hanno un'alta probabilità di piantare un Seme di Eonar nel bersaglio per 15 s.\n\nSeme di Eonar\nSe il bersaglio subisce danni, il seme sboccia, curandolo di 436 .\n[q]\"Eonar fece piovere su Azeroth i primi semi della vita, ma solo pochi conservano ancora dentro di sé il potere del Titano.\""}
MultiLanguageItemData['it'][168926] = {name = "[q6]Seme del Rinnovo Persistente", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Invocazione della Protettrice della Vita.\nApprendi il Grado 3 di Iride Focalizzante, Invocazione della Protettrice della Vita o Anima della Vita e della Morte su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Invocazione della Protettrice della Vita\n2.5 s di lancio 2.5 min di recupero Pianta 40 Semi di Eonar suddivisi tra tutti gli alleati entro 30 m.\n\n I semi che non vengono utilizzati riducono il tempo di recupero di quest'abilità di 2 s.\n\n Seme di Eonar\nRigenera 21 salute ogni 1 s. Se il bersaglio subisce danni, il seme sboccia, curandolo di 436 . \n Abilità minore:\n Seme di Eonar\nCirca 15 apparenze ogni minuto Le cure fornite hanno un'alta probabilità di piantare un Seme di Eonar nel bersaglio per 15 s.\n\nSeme di Eonar\nRigenera 21 salute ogni 1 s. Se il bersaglio subisce danni, il seme sboccia, curandolo di 436 .\n[q]\"Eonar fece piovere su Azeroth i primi semi della vita, ma solo pochi conservano ancora dentro di sé il potere del Titano.\""}
MultiLanguageItemData['it'][168927] = {name = "[q6]Seme dei Boccioli Vibranti", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con l'Invocazione della Protettrice della Vita.\nAbilità maggiore:\n Invocazione della Protettrice della Vita\n2.5 s di lancio 2.5 min di recupero Pianta 40 Semi di Eonar suddivisi tra tutti gli alleati entro 30 m.\n\n I semi che non vengono utilizzati riducono il tempo di recupero di quest'abilità di 2 s.\n\n Seme di Eonar\nRigenera 21 salute ogni 1 s. Se il bersaglio subisce danni, il seme sboccia, curandolo di 436 . \n Abilità minore:\n Seme di Eonar\nCirca 15 apparenze ogni minuto Le cure fornite hanno un'alta probabilità di piantare un Seme di Eonar nel bersaglio per 15 s.\n\nSeme di Eonar\nRigenera 21 salute ogni 1 s. Se il bersaglio subisce danni, il seme sboccia, curandolo di 436 .\n[q]\"Eonar fece piovere su Azeroth i primi semi della vita, ma solo pochi conservano ancora dentro di sé il potere del Titano.\""}
MultiLanguageItemData['it'][168928] = {name = "[q6]Tavoletta delle Maree in Equilibrio", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Marea Infinita.\nRichiede la reputazione Amichevole dai Liberti. (Impossibile acquistare se già in possesso.)\nRichiede la reputazione Amichevole dagli Ankoan. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Sovraccarico Mana\nIstantaneo 30 s di recupero Sovraccarica il mana per 8 s, così che ogni incantesimo lanciato aumenti le cure fornite del 3%. Si accumula.\n\n Durante il sovraccarico, la rigenerazione del mana si ferma . \n Abilità minore:\n Marea Infinita\nCirca 1.75 apparenze ogni minuto Le cure fornite hanno una probabilità di aumentare l'Intelletto di 115 per 10 s o di rigenerare 477 mana. La probabilità di rigenerare il mana aumenta in base al mana mancante. (3.5s di recupero)\n[q]\"I sussurri di Elune e Neptulon danzano sulle maree. Le loro parole incise sulla pietra sono un tributo all'equilibrio dei loro poteri.\""}
MultiLanguageItemData['it'][168929] = {name = "[q6]Codice delle Maree Incessanti", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Marea Infinita.\nRichiede la reputazione Onorato dai Liberti. (Impossibile acquistare se già in possesso.)\nRichiede la reputazione Onorato dagli Ankoan. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Sovraccarico Mana\nIstantaneo 30 s di recupero Sovraccarica il mana per 8 s, così che ogni incantesimo lanciato aumenti le cure fornite del 4%. Si accumula.\n\n Durante il sovraccarico, la rigenerazione del mana si ferma . \n Abilità minore:\n Marea Infinita\nCirca 1.75 apparenze ogni minuto Le cure fornite hanno una probabilità di aumentare l'Intelletto di [ 115 * (1.2)] per 10 s o di rigenerare [ 477 * (1.2)] mana. La probabilità di rigenerare il mana aumenta in base al mana mancante. [Marea Infinita: Esiste una probabilità del 20% di attivare entrambi gli effetti ] (3.5s di recupero)"}
MultiLanguageItemData['it'][168930] = {name = "[q6]Tomo delle Maree Rapide", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Marea Infinita.\nApprendi il Grado 3 di una qualunque Essenza della reputazione di Nazjatar su un altro personaggio per sbloccare questa Essenza.\nRichiede la reputazione Riverito dai Liberti. (Impossibile acquistare se già in possesso.)\nRichiede la reputazione Riverito dagli Ankoan. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Sovraccarico Mana\nIstantaneo 30 s di recupero Sovraccarica il mana per 8 s, così che ogni incantesimo lanciato aumenti le cure fornite del 4%. Si accumula.\n\n Durante il sovraccarico, la rigenerazione del mana si ferma e la celerità aumenta del 10%. \n Abilità minore:\n Marea Infinita\nCirca 1.75 apparenze ogni minuto Le cure fornite hanno una probabilità di aumentare l'Intelletto di [ 115 * (1.2)] per 10 s o di rigenerare [ 477 * (1.2)] mana. La probabilità di rigenerare il mana aumenta in base al mana mancante. Esiste una probabilità del 20% di attivare entrambi gli effetti. (3.5s di recupero)"}
MultiLanguageItemData['it'][168931] = {name = "[q6]Vello delle Maree Luminose", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Marea Infinita.\nAbilità maggiore:\n Sovraccarico Mana\nIstantaneo 30 s di recupero Sovraccarica il mana per 8 s, così che ogni incantesimo lanciato aumenti le cure fornite del 4%. Si accumula.\n\n Durante il sovraccarico, la rigenerazione del mana si ferma e la celerità aumenta del 10%. \n Abilità minore:\n Marea Infinita\nCirca 1.75 apparenze ogni minuto Le cure fornite hanno una probabilità di aumentare l'Intelletto di [ 115 * (1.2)] per 10 s o di rigenerare [ 477 * (1.2)] mana. La probabilità di rigenerare il mana aumenta in base al mana mancante. Esiste una probabilità del 20% di attivare entrambi gli effetti. (3.5s di recupero)"}
MultiLanguageItemData['it'][168932] = {name = "[q6]Batteria a Esistenza Reattiva", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Pozzo dell'Esistenza.\nRichiede la reputazione Amichevole dalla Resistenza di Bullonaccio. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Rinfresco\nPortata di 100 m Istantaneo 15 s di recupero Rilascia tutte le cure immagazzinate nel Pozzo dell'Esistenza su un alleato. Queste cure sono amplificate del 20 %. \n Abilità minore:\n Pozzo dell'Esistenza\nIl 15% delle tue sovracure viene conservato nel Pozzo dell'Esistenza. Quando si cura un bersaglio al di sotto del 40% di salute, il Pozzo rilascia fino a 547 delle cure in esso conservate."}
MultiLanguageItemData['it'][168933] = {name = "[q6]Condensatore a Esistenza Potenziata", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Pozzo dell'Esistenza.\nRichiede la reputazione Onorato dalla Resistenza di Bullonaccio. (Impossibile acquistare se già in possesso.)\nAbilità maggiore:\n Rinfresco\nPortata di 100 m Istantaneo 15 s di recupero Rilascia tutte le cure immagazzinate nel Pozzo dell'Esistenza su un alleato. Queste cure sono amplificate del 50%. \n Abilità minore:\n Pozzo dell'Esistenza\nIl 15% delle tue sovracure viene conservato nel Pozzo dell'Esistenza. Quando si cura un bersaglio al di sotto del 50% di salute, il Pozzo rilascia fino a 547 delle cure in esso conservate."}
MultiLanguageItemData['it'][168934] = {name = "[q6]Spessore a Esistenza Calibrata", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Pozzo dell'Esistenza.\nRichiede la reputazione Riverito dalla Resistenza di Bullonaccio. (Impossibile acquistare se già in possesso.)\nApprendi il Grado 3 di una qualunque Essenza della Resistenza di Bullonaccio su un altro personaggio per sbloccare questa Essenza.\nAbilità maggiore:\n Rinfresco\nPortata di 100 m Istantaneo 15 s di recupero Rilascia tutte le cure immagazzinate nel Pozzo dell'Esistenza su un alleato. Queste cure sono amplificate del 50%. Il pozzo non rilascia più cure di quante necessarie a ripristinare completamente la salute del bersaglio. \n Abilità minore:\n Pozzo dell'Esistenza\nIl 15% delle tue sovracure viene conservato nel Pozzo dell'Esistenza. Quando si cura un bersaglio al di sotto del 50% di salute, il Pozzo rilascia fino a 547 delle cure in esso conservate.\n\n Quando l'ammontare di cure conservato nel pozzo è inferiore a 1398 , assorbe le cure con il doppio della velocità."}
MultiLanguageItemData['it'][168935] = {name = "[q6]Schermo delle Vibrazioni Esistenziali", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Pozzo dell'Esistenza.\nAbilità maggiore:\n Rinfresco\nPortata di 100 m Istantaneo 15 s di recupero Rilascia tutte le cure immagazzinate nel Pozzo dell'Esistenza su un alleato. Queste cure sono amplificate del 50%. Il pozzo non rilascia più cure di quante necessarie a ripristinare completamente la salute del bersaglio. \n Abilità minore:\n Pozzo dell'Esistenza\nIl 15% delle tue sovracure viene conservato nel Pozzo dell'Esistenza. Quando si cura un bersaglio al di sotto del 50% di salute, il Pozzo rilascia fino a 547 delle cure in esso conservate.\n\n Quando l'ammontare di cure conservato nel pozzo è inferiore a 1398 , assorbe le cure con il doppio della velocità."}
MultiLanguageItemData['it'][168936] = {name = "[q6]Protezione della Speranza Incrollabile", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Protezione Incrollabile.\nAbilità maggiore:\n Guscio Guardiano\nCanalizzato (4 s di lancio) 3 min di recupero Rilascia 12 sfere protettive in 4 s, fornendo al primo alleato con cui entrano in contatto una barriera che assorbe 1840 danni subiti per 10 s. \n Abilità minore:\n Protezione Incrollabile\nOgni 10 s, gli alleati entro 15 m ottengono uno scudo che assorbe [ 113 * (1 + Versatilità)] danni. Si accumula fino a [ 848 * (1 + Versatilità)] volte.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
MultiLanguageItemData['it'][168937] = {name = "[q6]Protezione del Contraccambio", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Protezione Incrollabile.\nAbilità maggiore:\n Guscio Guardiano\nCanalizzato (4 s di lancio) 3 min di recupero Rilascia 12 sfere protettive in 4 s, fornendo al primo alleato con cui entrano in contatto una barriera che assorbe 1840 danni subiti per 10 s.\n\n Ogni volta che si genera una sfera protettiva, si ottiene uno scudo protettivo che assorbe danni pari al 2% della propria salute massima. \n Abilità minore:\n Protezione Incrollabile\nOgni 10 s, gli alleati entro 15 m ottengono uno scudo che assorbe [ 113 * (1 + Versatilità)] danni. Si accumula fino a [ 848 * (1 + Versatilità) * (1.2)] danni.\n\nUnico: Resistenza alla Corruzione aumentata di 10.\n[q]\"Non fare agli altri...\""}
MultiLanguageItemData['it'][168938] = {name = "[q6]Protezione dell'Aiuto Reciproco", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Protezione Incrollabile.\nApprendi il Grado 3 di una qualunque essenza delle Visioni Orripilanti su un altro personaggio per sbloccare questa essenza.\nAbilità maggiore:\n Guscio Guardiano\nCanalizzato (4 s di lancio) 3 min di recupero Rilascia 12 sfere protettive in 4 s, fornendo al primo alleato con cui entrano in contatto una barriera che assorbe 1840 danni subiti per 10 s.\n\n Ogni volta che si genera una sfera protettiva, si ottiene uno scudo protettivo che assorbe danni pari al 2% della propria salute massima.\n\n Lo scudo protettivo ottenuto da un alleato cura te e quell'alleato di [ 346 * (1 + Versatilità)]. \n Abilità minore:\n Protezione Incrollabile\nOgni 10 s, gli alleati entro 15 m ottengono uno scudo che assorbe [ 113 * (1 + Versatilità)] danni. Si accumula fino a [ 848 * (1 + Versatilità) * (1.2)] volte.\n\n I bersagli protetti da Protezione Incrollabile subiscono danni ridotti del 3%.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
