MultiLanguageItemData['it'][168940] = {name = "[q6]Protezione della Genialità Inimmaginabile", additional_info = "Grado 4\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Protezione Incrollabile.\nAbilità maggiore:\n Guscio Guardiano\nCanalizzato (4 s di lancio) 3 min di recupero Rilascia 12 sfere protettive in 4 s, fornendo al primo alleato con cui entrano in contatto una barriera che assorbe 1840 danni subiti per 10 s.\n\n Ogni volta che si genera una sfera protettiva, si ottiene uno scudo protettivo che assorbe danni pari al 2% della propria salute massima.\n\n Lo scudo protettivo ottenuto da un alleato cura te e quell'alleato di [ 346 * (1 + Versatilità)]. \n Abilità minore:\n Protezione Incrollabile\nOgni 10 s, gli alleati entro 15 m ottengono uno scudo che assorbe [ 113 * (1 + Versatilità)] danni. Si accumula fino a [ 848 * (1 + Versatilità) * (1.2)] volte.\n\n I bersagli protetti da Protezione Incrollabile subiscono danni ridotti del 3%.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
MultiLanguageItemData['it'][168941] = {name = "[q6]Reticolo di Redistribuzione della Vitalità", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Condotto della Vitalità.\nAbilità maggiore:\n Condotto della Vitalità\nPortata di 40 m Istantaneo 1 min di recupero Dirige il Condotto della Vitalità verso un alleato. Ogni 0.5 s per 6 s, rigenera [ 958 * (1 + Versatilità)] salute, trasferendola dall'alleato con salute maggiore entro 30 m. \n Abilità minore:\n Trasferimento\nCirca 15 apparenze ogni minuto I bersagli delle tue cure hanno un'alta probabilità di trasferire [ 958 * (1 + Versatilità)] salute dall'alleato con salute maggiore entro 30 m."}
MultiLanguageItemData['it'][168942] = {name = "[q6]Rete della Vitalità Crescente", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Condotto della Vitalità.\nAbilità maggiore:\n Condotto della Vitalità\nPortata di 40 m Istantaneo 45 s di recupero Dirige il Condotto della Vitalità verso un alleato. Ogni 0.5 s per 6 s, rigenera [ 958 * 1.2 * (1 + Versatilità)] salute, trasferendola dall'alleato con salute maggiore entro 30 m. \n Abilità minore:\n Trasferimento\nCirca 15 apparenze ogni minuto I bersagli delle tue cure hanno un'alta probabilità di trasferire [ 958 * 1.2 * (1 + Versatilità)] salute dall'alleato con salute maggiore entro 30 m."}
MultiLanguageItemData['it'][168943] = {name = "[q6]Griglia della Vitalità Esplosiva", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con il Condotto della Vitalità.\nApprendi il Grado 3 di Forza Vitale Condensata, Condotto della Vitalità o Dono Imperituro di Azeroth su un altro personaggio per sbloccare questa essenza.\nAbilità maggiore:\n Condotto della Vitalità\nPortata di 40 m Istantaneo 45 s di recupero Dirige il Condotto della Vitalità verso un alleato. Ogni 0.5 s per 6 s, rigenera [ 958 * 1.2 * (1 + Versatilità)] salute, trasferendola dall'alleato con salute maggiore entro 30 m.\n\n Se il bersaglio raggiunge la salute massima, l'effetto salta sul bersaglio vicino con meno salute per la durata restante. \n Abilità minore:\n Trasferimento\nCirca 15 apparenze ogni minuto I bersagli delle tue cure hanno un'alta probabilità di trasferire [ 958 * 1.2 * (1 + Versatilità)] salute dall'alleato con salute maggiore entro 30 m.\n\n I trasferimenti di salute lasciano uno scudo sul bersaglio che assorbe 575 danni subiti per 5 s."}
