MultiLanguageItemData['it'][169305] = {name = "[q4]Nautilus Acquipotente", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+7 Intelletto\n[q2]Usa: Scatena un'ondata che travolge il bersaglio e poi torna verso il punto d'origine, infliggendo [ 24 * (5) * (1 + Versatilità)] danni da gelo in 4 s ai nemici lungo la traiettoria. Riprendere l'onda riduce il tempo di recupero di questa abilità di 30 s. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][169306] = {name = "[q4]Chiave del Portale di Za'qul", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 10 Celerità\n[q2]Equipaggia: Le abilità hanno una bassa probabilità di creare uno Squarcio del Vuoto nelle vicinanze per 30 s. Avvicinarsi a uno Squarcio del Vuoto apre un portale per 10 s che aumenta l'Intelletto di 28 .\nPrezzo di vendita:"}
MultiLanguageItemData['it'][169307] = {name = "[q4]Visione di Disfatta", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+7 [Agilità o Forza]\n[q2]Usa: Rivela l'imminente rovina del tuo nemico, aumentando il tuo indice di celerità di 30 per 10 s. Per ogni 10% di salute mancante del bersaglio, fornisce 4 indice di celerità aggiuntivo. (1 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][169308] = {name = "[q4]Catena della Sofferenza", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+7 [Agilità o Forza]\n[q2]Usa: Trasferisce il 50% dei danni da te subiti a un alleato entro 25 m per 25 s, fino a un massimo di 1644 danni. Se il bersaglio non è più a portata o scende al di sotto del 25% della salute massima, l'effetto termina. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][169309] = {name = "[q4]Sacca di Uova di Zoatroidi", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+7 Intelletto\n[q2]Equipaggia: Lanciare un incantesimo di cura a bersaglio singolo ha una probabilità di evocare uno Zoatroide sul bersaglio, assorbendo [ 76 * (1 + Versatilità)] danni subiti e fornendo fino a 11 indice di versatilità in base ai danni assorbiti rimanenti. Ogni 10% del mana utilizzato nutre i tuoi Zoatroidi, aumentandone di [ 8 * (1 + Versatilità)] i danni assorbiti e di 1 l'indice di versatilità fornito.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][169310] = {name = "[q4]Riccio Sanguinario", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+7 [Agilità o Forza]\n[q2]Equipaggia: Il 10% dei danni subiti diventa Sangue Rigenerante, fino a un massimo di [ 315 * (1 + Versatilità)] danni totali. Ogni 3 s, [ 41 * (1 + Versatilità)] Sangue Rigenerante viene consumato per fornire cure quando si è feriti.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][169311] = {name = "[q4]Corallo Tagliente dei Bracescura", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+7 [Agilità o Forza]\n[q2]Usa: Infligge [ 25 * (1 + Versatilità)] danni fisici e applica Corallo Tagliente al bersaglio, aumentando la probabilità che le tue abilità d'attacco contro di lui infliggano [ 25 * (1 + Versatilità)] danni fisici aggiuntivi e aggiungano un accumulo di Corallo Tagliente.\n\n Rilanciare quest'abilità dissolve Corallo Tagliente dal bersaglio, aumentando il tuo indice di critico di 3 per accumulo per 20 s. (20 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][169312] = {name = "[q4]Alga Gelatinosa Luminosa", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+7 Intelletto\n[q2]Equipaggia: Le cure fornite hanno una probabilità di fornire l'effetto Luminescenza all'alleato più ferito entro 40 m. Le cure ricevute dagli alleati con l'effetto Luminescenza sono aumentate del 10%, fino a un massimo di [ 87 * (1 + Versatilità)] cure aggiuntive totali.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][169313] = {name = "[q4]Fiala della Tempesta Arcana", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+7 [Agilità o Forza]\n[q2]Equipaggia: La abilità d'attacco hanno una bassa probabilità di circondarti con un Temporale Arcano per 20 s, infliggendo 5 danni da arcano ogni 2 s ai nemici vicini. Il temporale accelera ogni volta che colpisce un nemico da solo, infliggendo danni più spesso.\nPrezzo di vendita:"}
