MultiLanguageItemData['it'][170211] = {name = "[q2]Ricetta: BAsta Non CHiedere E Trangugiare Tutte le Ordinazioni", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare un BA.N.CH.E.T.T.O. più efficacemente.\n[q2]Prepara un BA.N.CH.E.T.TO. in modo più efficiente, usando molti meno ingredienti.\nRichiede Cucina di Kul Tiras (175)\nPrezzo di vendita: \nBAsta Non CHiedere E Trangugiare Tutte le Ordinazioni\n[q2]Usa: Prepara un BA.N.CH.E.T.TO per un massimo di 35 membri del gruppo o dell'incursione.\n\n Rigenera 50769 salute e 30769 mana in 20 s. Devi sederti per mangiare. Se mangi per almeno 10 s diventi Ben Nutrito e guadagni 50 in un attributo per 1 ora.\nPrezzo di vendita: \nRichiede Pesce Vipera (15), Tinca Ionizzata (15), Lonza Fibrosa (15), Cosciotto Carnoso (15), Patata Novella (20), Cassa di Pezzi di Ricambio"}
MultiLanguageItemData['it'][170212] = {name = "[q2]Ricetta: Meccabocconcini", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare dei Meccaboccincini.\n[q2]Prepara dei Meccabocconcini.\nRichiede Cucina di Kul Tiras (150)\nPrezzo di vendita: \nMeccabocconcini\n[q2]Usa: Mi mangi?\n[q]\"Contengono tante meccavitamine arrugginite!\"\nPrezzo di vendita: \nRichiede Pezzi di Ricambio (25)"}
MultiLanguageItemData['it'][170213] = {name = "[q3]Formula: Pelle di Naga", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\nUsa: Ti insegna a creare un Incantamento Arma - Pelle di Naga più efficacemente.\n[q2]Incanta in modo permanente un'arma con un incantesimo di protezione dei Naga. Quando si blocca, schiva o para un attacco, si ha una probabilità di aumentare la Forza o l'Agilità di 4 per 15 s. Finché è attivo, la tua pelle è ricoperta di scaglie spesse che assorbono 1573 danni subiti. Non applicabile a un oggetto di livello superiore a 376.\n\n Costo in materiali significativamente ridotto.\nRichiede Incantamento di Kul Tiras (175)\nPrezzo di vendita:"}
