MultiLanguageItemData['it'][173288] = {name = "[q6]Geode d'Azerite Traboccante", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Scintilla dell'Ispirazione.\nAbilità maggiore:\n Momento di Gloria\nPortata di 40 m 1.5 s di lancio 1 min di recupero Scatena un'ondata di energia dal tuo Cuore di Azeroth, aumentando i danni inflitti dalle Essenze d'Azerite di tutti i membri del gruppo entro 15 m del 45% per i successivi 10 s. \n Abilità minore:\n Forza Unificata\nPortata di 40 m\n Circa 3 apparenze ogni minuto Gli incantesimi e le abilità hanno una probabilità di aumentare [tuo e di 2 altri alleati][l'indice di celerità] di 30 per 8 s e di ridurre il tempo di recupero dell'Essenza Maggiore attualmente equipaggiata [da te e da 2 altri alleati][da te] di 1.0 s.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
MultiLanguageItemData['it'][173289] = {name = "[q6]Geode d'Azerite Pulsante", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Scintilla dell'Ispirazione.\nAbilità maggiore:\n Momento di Gloria\nPortata di 40 m 1.5 s di lancio 1 min di recupero Scatena un'ondata di energia dal tuo Cuore di Azeroth, aumentando i danni inflitti dalle Essenze d'Azerite di tutti i membri del gruppo entro 15 m del 45% per i successivi 20 s. \n Abilità minore:\n Forza Unificata\nPortata di 40 m\n Circa 4 apparenze ogni minuto Gli incantesimi e le abilità hanno una probabilità di aumentare l'indice di celerità tuo e di 1 altro alleato di 30 per 8 s e di ridurre il tempo di recupero dell'Essenza Maggiore attualmente equipaggiata da te e da 1 altro alleato di 1.0 s.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
