MultiLanguageItemData['it'][173308] = {name = "[q6]Marchio del Compito Turbolento", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Forza del Custode.\nAbilità maggiore:\n Protettore Vigile\nIstantaneo 2 min di recupero Provoca tutti i nemici vicini, obbligandoli ad attaccarti per 6 s . \n Abilità minore:\n Vigore\nOgni 2 s, accumula 188 cure, fino a un massimo di ([Total Health] * 0.1). Quando si schiva o si para un attacco, fornisce tutte le cure accumulate.\n\nUnico: Resistenza alla Corruzione aumentata di 10.\n[q]\"È inutile cercare di sfuggire dallo scontro, bisogna abbracciarlo.\""}
MultiLanguageItemData['it'][173309] = {name = "[q6]Tecnica della Danza dell'Acqua", additional_info = "Grado 2\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Forza del Custode.\nAbilità maggiore:\n Protettore Vigile\nIstantaneo 2 min di recupero Provoca tutti i nemici vicini, obbligandoli ad attaccarti per 6 s e aumentando la tua probabilità di schivata del 15% per 6 s. \n Abilità minore:\n Vigore\nOgni 2 s, accumula [ 158 * (1 + Versatilità) * (1.25)] cure, fino a un massimo di ([Total Health] * 0.1). Quando si schiva o si para un attacco, fornisce tutte le cure accumulate.\n\nUnico: Resistenza alla Corruzione aumentata di 10.\n[q]\"Rapida... e improvvisa!\""}
MultiLanguageItemData['it'][173310] = {name = "[q6]Manuale delle Tattiche Sbilanciate", additional_info = "Grado 3\nSi vincola alla raccolta\nUnico\n[q2]Usa: Infonde il tuo Cuore di Azeroth con la Forza del Custode.\nApprendi il Grado 3 di una qualunque essenza delle Visioni Orripilanti su un altro personaggio per sbloccare questa essenza.\nAbilità maggiore:\n Protettore Vigile\nIstantaneo 2 min di recupero Provoca tutti i nemici vicini, obbligandoli ad attaccarti per 6 s e aumentando la tua probabilità di schivata del 15% per 6 s\n\n I personaggi con Protettore Vigile subiscono il 50% di danni aggiuntivi. \n Abilità minore:\n Vigore\nOgni 2 s, accumula [ 158 * (1 + Versatilità) * (1.25)] cure, fino a un massimo di ([Total Health] * 0.1). Quando si schiva o si para un attacco, fornisce tutte le cure accumulate.\n\n Aumenta la salute massima di tutti i personaggi con una specializzazione da difensore nel tuo gruppo o gruppo d'incursione del 3%. Si accumula.\n\nUnico: Resistenza alla Corruzione aumentata di 10."}
