MultiLanguageItemData['it'][180413] = {name = "[q4]Cervo delle Rune Foglialosca", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede Fama 23\nPrezzo di vendita:\n[q]\"I Cervi delle Rune Foglialosca vengono allevati dalla Caccia Selvaggia per la loro ferocia e la loro bellezza. Non hanno alcuna paura a penetrare nella tana di qualsiasi predatore.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180414] = {name = "[q4]Cervo delle Rune del Risvegliatore", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Ai Cervi delle Rune piace sdraiarsi vicino ai Semebrado. I Risvegliatori credono che possano sentire i sogni dei dormienti. I Cervi delle Rune mostrano un'ampia varietà di emozioni durante questa veglia, riflettendo i sogni o gli incubi degli spiriti nei Semebrado.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180415] = {name = "[q4]Cervo delle Rune Invernale", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeCorte della Notte\n- Riverito\nDevi essere un membro della Congrega dei Silfi della Notte.\nPrezzo di vendita:\n[q]\"I Cervi delle Rune Invernali sono benedetti dalla Regina dell'Inverno in persona. Le loro rune brillano quando i predatori sono nelle vicinanze, avvertendo l'intero branco.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
