MultiLanguageItemData['it'][180721] = {name = "[q4]Cervo delle Rune della Luce dei Sogni Incantato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"I maestosi Cervi delle Rune sono capaci di risucchiare l'Animum ambientale di Selvarden con le loro antiche corna. L'Animum viene usato come nutrimento e potenzia la velocità e la magia dei Cervi delle Rune.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180722] = {name = "[q4]Cervo delle Rune Foglialosca Incantato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede Fama 39\nPrezzo di vendita:\n[q]\"Un Cervo delle Rune Foglialosca è capace di squartare creature potenti come una Matriarca Gorm, per difendere il suo branco. La Caccia Selvaggia cavalca queste cavalcature negli angoli più pericolosi delle Terretetre, quando il suo dominio dev'essere difeso da coloro che minacciano la natura selvaggia.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180723] = {name = "[q4]Cervo delle Rune del Risvegliatore Incantato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"I Cervi delle Rune del Risvegliatore proteggono con ferocia la loro foresta di Semebrado. Quando i boschi iniziarono a seccarsi, molti esemplari s'infuriarono.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180724] = {name = "[q4]Cervo delle Rune Invernale Incantato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeMarasmio\n- Riverito\nPrezzo di vendita:\n[q]\"I Cervi delle Rune Invernali sono la cavalcatura preferita dalla Regina dell'Inverno in persona, la quale concede tale creatura solo ai suoi prediletti.\"\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180725] = {name = "[q4]Masticaradure Spinafauce", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"I cavalieri Spriggan mettono dei pezzetti di Animum alla fine di bastoni che tengono sospesi davanti alle loro cavalcature gorm. È... un'arte ancora da perfezionare.\"\nBottino:\nDomagorm Tizo\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180726] = {name = "[q4]Acidalingua Pallido", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nDevi essere Osannato dai Maestri delle Suture.\nCompi l'impresa \"Lo stretto necessario\" per acquistare questa cavalcatura.\nPrezzo di vendita:\n[q]\"L'acido presente nell'icore di questa creatura ha cancellato il colore del suo guscio, rendendolo bianco come la neve.\"\nEdificio della Congrega:\nCorte delle Braci\nCongrega:\nVenthyr\n\nEdificio della Congrega:\nVivaio della Regina\nCongrega:\nSilfi della Notte\n\nEdificio della Congrega:\nVia dell'Ascensione\nCongrega:\nKyrian\n\nEdificio della Congrega:\nFabbrica degli Abomini\nCongrega:\nNecrosignori"}
MultiLanguageItemData['it'][180727] = {name = "[q4]Cavalcatore Brumaluce", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"I fastidiosi Spriggan e i calcavalle hanno una naturale inimicizia. Nessun calcavalle consentirebbe mai di essere cavalcato da uno Spriggan, perché ne può percepire l'intrinseca malvagità. Questo fa arrabbiare gli Spriggan, che si divertono a fare scherzi crudeli a queste maestose creature.\"\nArea:\nIntrico Velofosco\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180728] = {name = "[q4]Zoccolotetro Rapido", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Le ballate di Selvarden sostengono che la nascita del calcatenebre abbia provocato la morte di un Dio Selvatico particolarmente benevolo. Quindi, un calcatenebre è sia una benedizione che una maledizione.\"\nBottino:\nIncubo\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180729] = {name = "[q4]Falenarden Battivespro", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeCaccia Selvaggia\n- Osannato\nPrezzo di vendita:\n[q]\"Queste falenarden preferiscono le oscure foreste di Selvarden a nord-ovest, dove le colonie fungine sono sempre fiorite.\"\nMercante:\nAithlyn\nZona:\nSelvarden\nFazione:\nCaccia Selvaggia - Osannato\nCosto:\n30."}
MultiLanguageItemData['it'][180730] = {name = "[q4]Predatore Mantolume Selvaggio", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Il manto verde brillante di questo predatore lo distingue da quelli blu e viola di Selvarden, rendendo più facile l'individuazione nelle foreste notturne degli altri della sua razza.\"\nBottino:\nValfir l'Inarrestabile\nCongrega:\nSilfi della Notte\nZona:\nSelvarden"}
MultiLanguageItemData['it'][180731] = {name = "[q4]Culla di Semebrado", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Il carico più prezioso di tutta Selvarden, i Semebrado, viene trasportato da questo carro costruito con amore. È l'infusione d'Animum che gli permette di librarsi sul terreno.\"\nTesoro:\nScrigno della Luna\nZona:\nSelvarden"}
