MultiLanguageItemData['it'][180761] = {name = "[q4]Falince della Lealtà", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Alcuni Ascesi hanno una falince come famiglio, che non sarà pelosa come un larion, ma è molto meno predisposta a mangiare gli altri famigli presenti.\"\nCongrega:\nKyrian\nZona:\nBastione"}
MultiLanguageItemData['it'][180762] = {name = "[q4]Falince dell'Umiltà", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Le falinci non sono capaci di giocare al riporto, anche se nessuno sa il perché.\"\nCongrega:\nKyrian\nZona:\nBastione"}
MultiLanguageItemData['it'][180763] = {name = "[q4]Falince del Coraggio", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Una falince è considerata sia un famiglio degno che un avversario impegnativo contro cui mettere alla prova i propri riflessi.\"\nCongrega:\nKyrian\nZona:\nBastione"}
MultiLanguageItemData['it'][180764] = {name = "[q4]Falince della Purezza", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede Fama 23\n\n\n[q]\"Si sa poco sulla tecnologia che ha dato origine alle falinci, ma erano probabilmente macchinazioni più in sintonia con la religione che con l'ingegneria.\"\nCongrega:\nKyrian\nZona:\nBastione"}
MultiLanguageItemData['it'][180765] = {name = "[q4]Falince Eterna della Purezza", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede Fama 39\n\n\n[q]\"La falince corazzata è il famiglio preferito tra i più potenti guerrieri Ascesi, perché in battaglia è impavida e spietata.\"\nCongrega:\nKyrian\nZona:\nBastione"}
MultiLanguageItemData['it'][180766] = {name = "[q4]Falince Eterna del Coraggio", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Sono richieste molte sbarre di aureonite, per forgiare una di queste cavalcature luminose, ma il loro meraviglioso aspetto vale la fatica.\"\nCongrega:\nKyrian\nZona:\nBastione"}
