MultiLanguageItemData['it'][180948] = {name = "[q4]Gargon da Battaglia Vrednic", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Vrednic, il fedele Gargon del Principe Renathal, è stato al suo fianco per millenni. Ornato con la sua armatura di Peccavyr, la mera presenza di Vrednic incute terrore a chiunque posi gli occhi su di lui, mentre accompagna il suo cavaliere in battaglia.\"\nCongrega:\nVenthyr\nZona:\nRevendreth"}
MultiLanguageItemData['it'][180949] = {name = "[q3]Stabilizzatore del Flusso d'Animum", additional_info = "Potenziamento Permanente: La Fauce\nSi vincola alla raccolta\nUnico\n[q2]Usa: Sblocca il Teletrasporto del Flusso d'Animum nel Rifugio di Ve'nari, permettendoti di raggiungere velocemente il Tremacolo.\nRichiede che Ve'nari abbia di te un'opinione Incerta o superiore."}
MultiLanguageItemData['it'][180950] = {name = "[q0]The Maw - Pet Cosmetic - NYI", additional_info = "Si vincola alla raccolta\n[q]\"Molto carino, ma probabilmente letale per tutta la vita su Azeroth.\""}
