MultiLanguageItemData['it'][181818] = {name = "[q4]Redini Masticate dell'Alalacera Immaturo", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un'Alalacera Immaturo.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli Alalacera sono una forza necessaria nel ciclo vitale delle Terretetre, perché sono sia preda che predatore nel duro ambiente di Maldraxxus.\"\nZona:\nMaldraxxus"}
MultiLanguageItemData['it'][181819] = {name = "[q4]Redini di Midollorosso", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare Ossazanna.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Ossazanna, progenie di Ossartiglio, era amato da Amarth il Mietitore per la sua insaziabile sete, anche se interrompeva tutti gli esperimenti che il sadico comandante provava a fare.\"\nBottino:\nNalthor il Vincolabrina\nZona:\nScia Necrotica (Mitica)\n\nBottino:\nCassa dello Sfidante\nZona:\nScia Necrotica"}
MultiLanguageItemData['it'][181820] = {name = "[q4]Tauralus Prescelto Corazzato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I tauralus hanno due code, entrambe assolutamente necessarie a spazzare via i parassiti come i pidocchi del sangue.\"\nImpresa:\nCose da fare da morti\nCategoria:\nSantuari delle Congreghe"}
MultiLanguageItemData['it'][181821] = {name = "[q4]Tauralus della Piaga Corrotta Corazzato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede Fama 39\n\n\n[q]\"Quando è completamente corazzato, un tauralus può sostenere un'incredibile quantità di danni, prima di cadere, rivelandosi un prezioso alleato in battaglia.\"\nCongrega:\nNecrosignori\nMercante:\nSu Zettai\nZona:\nMaldraxxusCosto:\n3000"}
MultiLanguageItemData['it'][181822] = {name = "[q4]Tauralus da Guerra Corazzato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"L'addestramento dei tauralus che servono le armate di Maldraxxus serve a rimuovere da loro ogni briciolo di compassione, e vengono corazzati quando dimostrano che nessuna spada o incantesimo può impedire loro di portare alla vittoria il proprio cavaliere.\"\nCongrega:\nNecrosignori\nZona:\nMaldraxxus"}
