MultiLanguageItemData['it'][182074] = {name = "[q4]Tauralus Prescelto", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Anche un tauralus non corazzato è un alleato prezioso in battaglia, perché i suoi enormi corni possono perforare anche le piastre delle armature.\"\nImpresa:\nLa banda è di nuovo riunita\nCategoria:\nSantuari delle Congreghe"}
MultiLanguageItemData['it'][182075] = {name = "[q4]Tauralus Zoccolo Osseo", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Ci sono molti motivi per cui è meglio non stare dietro a un tauralus, non ultimo il rischio di zoccolate e colpi di frusta con la coda.\"\nBottino:\nTahonta\nCongrega:\nNecrosignori\nZona:\nMaldraxxus"}
MultiLanguageItemData['it'][182076] = {name = "[q4]Tauralus della Piaga Corrotta", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede Fama 23\n\n\n[q]\"Il tauralus è considerato molto coraggioso, anche se gli studiosi di Maldraxxus si sono chiesti a lungo se la sua mancanza di paura è semplicemente dovuta alle minuscole dimensioni del cervello.\"\nCongrega:\nNecrosignori\nZona:\nMaldraxxus"}
MultiLanguageItemData['it'][182077] = {name = "[q4]Tauralus da Guerra", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"I soldati di Maldraxxus proteggono le Terretetre e richiedono una cavalcatura che sia tanto abile quanto calma, in caso di circostanze avverse.\"\nCongrega:\nNecrosignori\nZona:\nMaldraxxus"}
MultiLanguageItemData['it'][182078] = {name = "[q4]Grifalco d'Ossa Ricucite", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Solo gli esperti ricucitori di carne che hanno dimostrato maestria nella magia di Maldraxxus sono abbastanza potenti da costruire un Grifalco della Morte di queste dimensioni.\"\nProfessione:\nCuciture Abominevoli\nZona:\nMaldraxxus"}
MultiLanguageItemData['it'][182079] = {name = "[q4]Redini Coperte di Poltiglia del Grifalco della Morte Gigantesco", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Grifalco della Morte Gigantesco.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Grifalchi della Morte sono mostruosità ricucite con visceri, ossa e organi non necessari a ricostruire soldati per la Casata dei Costrutti.\"\nBottino:\nErrore Violaceo\nZona:\nMaldraxxus"}
MultiLanguageItemData['it'][182080] = {name = "[q4]Grifalco della Piaga Predatore", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"La fame eterna di Gieger è leggendaria nella Casata dei Costrutti, e nessuna bestia è troppo grande o con troppe ossa per entrare nel suo grosso stomaco.\"\nBottino:\nGieger\nCongrega:\nNecrosignori\nZona:\nMaldraxxus"}
MultiLanguageItemData['it'][182081] = {name = "[q4]Redini dell'Artigliamassacro Colossale", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Artigliamassacro Colossale.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Solo i più possenti stallieri di Maldraxxus sono in grado di controllare il volere dei colossali Artigliamassacro, fornendo a tutti i campioni dell'Armata Imperitura un temibile alleato nelle Terretetre.\"\nBottino:\nRifornimenti dell'Armata Imperitura\nZona:\nMaldraxxus"}
MultiLanguageItemData['it'][182082] = {name = "[q4]Zannacruenta Vivace", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeArmata Imperitura\n- Osannato\n\n\n[q]\"Solo gli Zannacruenta che sopravvivono alla Prova della Conquista sono considerati degni di diventare una cavalcatura dell'Armata Imperitura.\"\nMercante:\nNalcorn Talsen\nZona:\nMaldraxxus\nFazione:\nArmata Imperitura - Osannato\nCosto:\n30."}
MultiLanguageItemData['it'][182083] = {name = "[q4]Cinghiale Scheletrico della Fendiossa", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Sabreil era nota per la spietata efficienza con cui smembrava i nemici, dando da mangiare le loro ossa al suo fedele cinghiale.\"\nMercante:\nCollezionista Ta'steld\nZona:\nOribos\nCosto:\n5.000"}
