MultiLanguageItemData['it'][182625] = {name = "[q5]Ricordo della Stretta dell'Imperituro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nStretta dell'Imperituro Abilità dell'Incisione Runica\nRiduce il tempo di recupero di Presa Mortale di 3 s. Per 3 s dopo aver lanciato Presa Mortale, è possibile lanciarla nuovamente a dispetto del tempo di recupero.\nIncisione Runica su: Fianchi, Piedi\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Cavaliere della Morte"}
MultiLanguageItemData['it'][182626] = {name = "[q5]Ricordo di Morte e Disperazione", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nMorte e Disperazione Abilità dell'Incisione Runica\nAumenta la tua celerità e quella dei tuoi servitori del [ Sangue : 10% /\n\nGelo, Empietà\n15% ] finché restate nell'area d'effetto di una tua Morte e Distruzione. I nemici feriti da Morte e Distruzione hanno una probabilità di tremare di paura sul posto per 3 s.\nIncisione Runica su: Testa, Collo, Spalle\nFonte: Missione: La Gran Banca\nRichiede: Cavaliere della Morte"}
MultiLanguageItemData['it'][182627] = {name = "[q5]Ricordo del Supersforzo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSupersforzo Abilità dell'Incisione Runica\nL'effetto Febbre del Gelo, Morbo del Sangue e Piaga Virulenta applica anche gli effetti delle altre due abilità con un'efficacia ridotta.\nIncisione Runica su: Collo, Torso\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Cavaliere della Morte"}
MultiLanguageItemData['it'][182628] = {name = "[q5]Ricordo del Vigore di Bryndaor", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVigore di Bryndaor Abilità dell'Incisione Runica\nAssalto della Morte rigenera il 15% della potenza runica consumata se le cure a te fornite rigenerano più del 10% della tua salute massima.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Cavaliere della Morte (Sangue)"}
MultiLanguageItemData['it'][182629] = {name = "[q5]Ricordo dell'Arma Runica Cremisi", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nArma Runica Cremisi Abilità dell'Incisione Runica\nArma Runica Danzante fornisce 5 cariche di Scudo d'Ossa. Quando viene consumata una carica di Scudo d'Ossa, il tempo di recupero di Arma Runica Danzante si riduce di 5 s. Inoltre, quando Arma Runica Danzante termina, la velocità di rigenerazione delle rune aumenta del 40% per 10 s.\nIncisione Runica su: Spalle, Fianchi, Mani\nFonte: Bottino Spedizione: Halkias, Mastodonte Macchiato dal Peccato\nRichiede: Cavaliere della Morte (Sangue)"}
MultiLanguageItemData['it'][182630] = {name = "[q5]Ricordo del Dominio di Malacarne", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nDominio di Malacarne Abilità dell'Incisione Runica\nSangue Vampirico genera 45 potenza runica. Inoltre, Assalto al Cuore riduce il tempo di recupero restante di Sangue Vampirico di 2 s.\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino Incursione: Distruttore Famelico\nRichiede: Cavaliere della Morte (Sangue)"}
MultiLanguageItemData['it'][182631] = {name = "[q5]Ricordo dell'Aura Vampirica", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAura Vampirica Abilità dell'Incisione Runica\nSangue Vampirico aumenta il ritorno vitale del 5% e dura 3 s aggiuntivi. Inoltre, il tuo effetto di Sangue Vampirico agisce su tutti i membri del gruppo al 50% dell'efficacia che ha su di te.\nIncisione Runica su: Torso, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Bastioni Superiori, Blocco 3+\nRichiede: Cavaliere della Morte (Sangue)"}
MultiLanguageItemData['it'][182632] = {name = "[q5]Ricordo dello Zero Assoluto", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nZero Assoluto Abilità dell'Incisione Runica\nRiduce il tempo di recupero di Furia del Dragone del Gelo del 50% e fa sì che congeli tutti i nemici colpiti per 3 s.\nIncisione Runica su: Collo, Polsi\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Cavaliere della Morte (Gelo)"}
MultiLanguageItemData['it'][182633] = {name = "[q5]Ricordo del Freddo Pungente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFreddo Pungente Abilità dell'Incisione Runica\nAumenta i danni inflitti da Inverno Spietato del 30%. La prima volta che Inverno Spietato infligge danni a 3 nemici diversi, attiva Brina.\nIncisione Runica su: Testa, Fianchi\nFonte: Bottino Spedizione: Nalthor il Vincolabrina\nRichiede: Cavaliere della Morte (Gelo)"}
MultiLanguageItemData['it'][182634] = {name = "[q5]Ricordo della Rabbia del Campione Ghiacciato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRabbia del Campione Ghiacciato Abilità dell'Incisione Runica\nDisintegrazione ha una probabilità aggiuntiva del 15% di attivare Brina e Folata Gelida genera 12 potenza runica quando Brina è attiva.\nIncisione Runica su: Polsi, Mani, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Cavaliere della Morte (Gelo)"}
MultiLanguageItemData['it'][182635] = {name = "[q5]Ricordo del Favore di Koltira", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFavore di Koltira Abilità dell'Incisione Runica\nAumenta i danni inflitti da Disintegrazione del 10% e gli fornisce una probabilità del 12% di ripristinare 2 rune. (Possibilità di Apparire:12%, 700ms di recupero)\nIncisione Runica su: Spalle, Dito\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Cavaliere della Morte (Gelo)"}
MultiLanguageItemData['it'][182636] = {name = "[q5]Ricordo della Spira Letale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSpira Letale Abilità dell'Incisione Runica\nRiduce il costo in potenza runica di Spira Mortale di 10 e Spira Mortale aumenta la durata di Trasformazione Oscura di 1 s.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Cavaliere della Morte (Empietà)"}
MultiLanguageItemData['it'][182637] = {name = "[q5]Ricordo della Certezza della Morte", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nCertezza della Morte Abilità dell'Incisione Runica\nAssalto della Morte e Spira Mortale infliggono il 35% di danni aggiuntivi e riducono il tempo di recupero restante di [ Profanazione ] Morte e Distruzione di 2.0 s.\nIncisione Runica su: Testa, Collo, Mani\nFonte: Bottino Spedizione: Margravio Stradama\nRichiede: Cavaliere della Morte (Empietà)"}
MultiLanguageItemData['it'][182638] = {name = "[q5]Ricordo della Mostruosità Frenetica", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nMostruosità Frenetica Abilità dell'Incisione Runica\nTrasformazione Oscura aumenta la velocità d'attacco e i danni inflitti da te e dalla tua Mostruosità del 12%.\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino Boss Esterno: Nurgash Tuttomuco\nRichiede: Cavaliere della Morte (Empietà)"}
