MultiLanguageItemData['it'][183188] = {name = "Pergamena di Cromie", additional_info = "Oggetto di missione\nUnico\n[q2]Usa: Una volta usata questa pergamena, verrai rimosso dalle Campagne nel Tempo.\n\n Nuove avventure ti attendono a Orgrimmar! (8 S Recupero)\n[q]\"Da dove viene questa pergamena? L'hai sempre avuta? Meglio non pensarci troppo...\""}
