MultiLanguageItemData['it'][183210] = {name = "[q5]Ricordo del Vilbombardamento", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVilbombardamento Abilità dell'Incisione Runica\nI danni inflitti da Rogo Rovente hanno una probabilità di fornire 1 accumulo di Vilbombardamento, aumentando i danni inflitti dal successivo Lancio Lama al bersaglio primario del 50% e lanciando una lama aggiuntiva contro un bersaglio vicino. Si accumula fino a 5 volte.\nIncisione Runica su: Testa, Collo, Spalle\nFonte: Missione: La Gran Banca\nRichiede: Cacciatore di Demoni"}
MultiLanguageItemData['it'][183211] = {name = "[q5]Ricordo dell'Ora Più Oscura", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nOra Più Oscura Abilità dell'Incisione Runica\nQuando si scende al di sotto del 35% della salute massima, Oscurità si attiva automaticamente. L'effetto può verificarsi solo una volta ogni 2 min.\nIncisione Runica su: Torso, Gambe\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Cacciatore di Demoni"}
MultiLanguageItemData['it'][183212] = {name = "[q5]Ricordo del Medaglione Lumenero", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nDono Lumenero Abilità dell'Incisione Runica\nRovina\n Raggio Oculare ha una probabilità del 40% di non attivare il tempo di recupero e di ripristinare 30 furia.\n\nVendetta\n Vildevastazione ha una probabilità del 40% di non attivare il tempo di recupero e di ripristinare 50 furia.\nIncisione Runica su: Collo, Fianchi\nFonte: Bottino Spedizione: Margravio Stradama\nRichiede: Cacciatore di Demoni"}
MultiLanguageItemData['it'][183213] = {name = "[q5]Ricordo dell'Angoscia Collettiva", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAngoscia Collettiva Abilità dell'Incisione Runica\nRovina\n Lanciare Raggio Oculare evoca un Cacciatore di Demoni della Vendetta alleato che lancia Vildevastazione.\n\nVendetta\n Lanciare Vildevastazione evoca un Cacciatore di Demoni della Rovina alleato che lancia Raggio Oculare.\nIncisione Runica su: Polsi, Schiena\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Cacciatore di Demoni"}
MultiLanguageItemData['it'][183214] = {name = "[q5]Ricordo della Teoria del Caos", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTeoria del Caos Abilità dell'Incisione Runica\nIl lancio di Lame Danzanti ha una probabilità del 30% di attivare Lame Caotiche, aumentando i danni inflitti da Assalto del Caos del 50% e la probabilità che ripristini furia del 60% aggiuntivo per 8 s. (500ms di recupero)\nIncisione Runica su: Fianchi, Mani\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Cacciatore di Demoni (Rovina)"}
MultiLanguageItemData['it'][183215] = {name = "[q5]Ricordo del Vilnucleo Erratico", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVilnucleo Erratico Abilità dell'Incisione Runica\nRiduce il tempo di recupero di Vilscatto del 30%.\nIncisione Runica su: Piedi, Dito\nFonte: Bottino Boss Esterno: Nurgash Tuttomuco\nRichiede: Cacciatore di Demoni (Rovina)"}
MultiLanguageItemData['it'][183216] = {name = "[q5]Ricordo della Ferita Bruciante", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\nFerita Bruciante Abilità dell'Incisione Runica Portata di mischia\nMorso del Demone lascia una ferita aperta sul nemico, infliggendo ([100% of Attack Power]) danni da caos in 15 s e aumentandone i danni subiti da Rogo Rovente del 65%.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Spedizione: I Manalampo\nRichiede: Cacciatore di Demoni (Rovina)"}
MultiLanguageItemData['it'][183217] = {name = "[q5]Ricordo della Mia Natura Oscura", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nNatura Oscura Abilità dell'Incisione Runica\nI nemici uccisi entro 4 s dall'aver subito i danni di Raggio Oculare hanno una probabilità del 25% di convertire i propri Frammenti dell'Anima in un Frammento dell'Anima di Demone.\nIncisione Runica su: Spalle, Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Cacciatore di Demoni (Rovina)"}
MultiLanguageItemData['it'][183218] = {name = "[q5]Ricordo della Fortificazione di Vilfiamma", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFortificazione di Vilfiamma Abilità dell'Incisione Runica\nRiduce i danni magici subiti del 15% quando Rogo Rovente è attivo.\nIncisione Runica su: Fianchi, Dito\nFonte: Bottino Incursione: Dama Inerva Venascura\nRichiede: Cacciatore di Demoni (Vendetta)"}
MultiLanguageItemData['it'][183219] = {name = "[q5]Ricordo dell'Anima Ardente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAnima Ardente Abilità dell'Incisione Runica\nOgni Frammento dell'Anima consumato da Fendente d'Anima riduce il tempo di recupero di Marchiatura Ardente di 2 s.\nIncisione Runica su: Polsi, Mani\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Cacciatore di Demoni (Vendetta)"}
MultiLanguageItemData['it'][183220] = {name = "[q5]Ricordo della Profanazione di Razelikh", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nProfanazione di Razelikh Abilità dell'Incisione Runica\nFendente d'Anima riduce il tempo di recupero restante di un Sigillo casuale di 8 s . (500ms di recupero)\nIncisione Runica su: Gambe, Polsi\nFonte: Bottino Spedizione: Xav l'Immortale\nRichiede: Cacciatore di Demoni (Vendetta)"}
MultiLanguageItemData['it'][183221] = {name = "[q5]Ricordo dello Spirito delle Fiamme Oscure", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSpirito delle Fiamme Oscure Abilità dell'Incisione Runica\nMarchiatura Ardente cura del 100% dei danni iniziali inflitti in 8 s e ogni nemico colpito da Sigillo della Fiamma aumenta i danni istantanei inflitti dalla successiva Marchiatura Ardente del 15%. Si accumula fino a 15 volte.\nIncisione Runica su: Testa, Collo\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Cacciatore di Demoni (Vendetta)"}
MultiLanguageItemData['it'][183222] = {name = "[q5]Ricordo del Giuramento del Druido Anziano", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nGiuramento del Druido Anziano Abilità dell'Incisione Runica\nAumenta gli effetti di Pelle Spessa, Influenza Astrale, Rapidità Felina e Dono di Ysera del 75%.\n\n Quando si assume la forma della propria Affinità, si ottiene Cuore Selvaggio per 10 s, una volta ogni 1 min.\nIncisione Runica su: Spalle, Polsi\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Druido"}
MultiLanguageItemData['it'][183223] = {name = "[q5]Ricordo del Circolo della Vita e della Morte", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nCircolo della Vita e della Morte Abilità dell'Incisione Runica\nGli effetti periodici dannosi infliggono i loro danni in un tempo ridotto del 25% e le cure periodiche vengono fornite in un tempo ridotto del 15%.\nIncisione Runica su: Testa, Dito\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Druido"}
MultiLanguageItemData['it'][183224] = {name = "[q5]Ricordo della Fiasca del Focus Profondo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFiasca del Focus Profondo Abilità dell'Incisione Runica\nQuando Fuoco Lunare, Graffio, Squarcio o Rinvigorimento è attivo su un bersaglio singolo, l'effetto aumenta del 40%.\nIncisione Runica su: Collo, Torso\nFonte: Missione: La Gran Banca\nRichiede: Druido"}
MultiLanguageItemData['it'][183225] = {name = "[q5]Ricordo del Barlume Sfuggente di Lycara", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBarlume Sfuggente di Lycara Abilità dell'Incisione Runica\nOgni 45 s quando si è in combattimento, lancia un incantesimo in base alla tua forma\n\n Nessuna forma: Crescita Rigogliosa\n Forma Felina: Ira Primordiale\n Forma d'Orso: Pelledura\n Forma di Lunagufo: Pioggia di Stelle\n Forma Celere: Ruggito Impetuoso\nIncisione Runica su: Fianchi, Piedi\nFonte: Bottino Spedizione: Mordretha, l'Imperatrice Eterna\nRichiede: Druido"}
MultiLanguageItemData['it'][183226] = {name = "[q5]Ricordo dell'Equilibrio di Tutte le Cose", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nEquilibrio di Tutte le Cose Abilità dell'Incisione Runica\nEclissi aumenta la probabilità di critico con gli incantesimi arcani o di natura del 24%. L'effetto cala del 3% ogni 1 s.\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Druido (Equilibrio)"}
MultiLanguageItemData['it'][183227] = {name = "[q5]Ricordo della Visione Limpida di Oneth", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVisione Limpida di Oneth Abilità dell'Incisione Runica\nCometa Arcana ha una probabilità del 20% di azzerare il costo di Pioggia di Stelle. Pioggia di Stelle ha una probabilità del 40% di azzerare il costo di Cometa Arcana.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Druido (Equilibrio)"}
MultiLanguageItemData['it'][183228] = {name = "[q5]Ricordo della Pulsazione Arcanica Primordiale", additional_info = "Si vincola alla raccolta\nUnicoClassi: Druido\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPulsazione Arcanica Primordiale Abilità dell'Incisione Runica\nOgni 300 potere astrale consumato fornisce Allineamento Celeste per 12 s.\nIncisione Runica su: Spalle, Mani, Dito\nFonte: Bottino: La Fauce, Ira del Carceriere\nRichiede: Druido (Equilibrio)"}
MultiLanguageItemData['it'][183229] = {name = "[q5]Ricordo del Vincolasogni Logoro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVincolasogni Logoro Abilità dell'Incisione Runica\nCometa Arcana e Pioggia di Stelle riducono il costo di Cometa Arcana e Pioggia di Stelle del 10% e ne aumentano i danni del 10% per 5 s. Si accumula fino a 2 volte.\nIncisione Runica su: Torso, Dito\nFonte: Bottino Spedizione: Tred'ova\nRichiede: Druido (Equilibrio)"}
MultiLanguageItemData['it'][183230] = {name = "[q5]Ricordo della Bramosia del Grande Predatore", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBramosia del Grande Predatore Abilità dell'Incisione Runica\nI danni inflitti da Squarcio hanno una probabilità del 4% di azzerare il costo del successivo lancio di Morso Feroce e di far sì che infligga i danni massimi.\nIncisione Runica su: Spalle, Fianchi\nFonte: Bottino: Torgast, Torre dei Dannati. Bastioni Superiori, Blocco 3+\nRichiede: Druido (Aggressore Ferino)"}
MultiLanguageItemData['it'][183231] = {name = "[q5]Ricordo del Ninnolo Occhio Felino", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nNinnolo Occhio Felino Abilità dell'Incisione Runica\nLe abilità lanciate durante Lancio Istintivo generano energia pari al 30% del loro costo. Inoltre, aumenta l'energia massima di 60.\nIncisione Runica su: Collo, Dito\nFonte: Bottino Spedizione: Kin-Tara\nRichiede: Druido (Aggressore Ferino)"}
MultiLanguageItemData['it'][183232] = {name = "[q5]Ricordo dell'Occhio della Simmetria Spaventosa", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nOcchio della Simmetria Spaventosa Abilità dell'Incisione Runica\nFuria della Tigre fa sì che le successive 2 mosse risolutive ripristinino 2 punti combo.\nIncisione Runica su: Testa, Collo, Mani\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Druido (Aggressore Ferino)"}
MultiLanguageItemData['it'][183233] = {name = "[q5]Ricordo della Frenesia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFrenesia Abilità dell'Incisione Runica Portata di 100 m\nLe abilità che forniscono punti combo riducono il tempo di recupero di [ Incarnazione: Avatar di Grigiomanto : Incarnazione: Re della Giungla di 0.3 / Berserk di 0.3] s.\n\n Durante [ Incarnazione: Avatar di Grigiomanto : Incarnazione: Re della Giungla / Berserk], fanno sanguinare il bersaglio, infliggendo danni aggiuntivi pari al 150% dei loro danni in 8 s.\nIncisione Runica su: Fianchi, Polsi\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Druido (Aggressore Ferino)"}
MultiLanguageItemData['it'][183234] = {name = "[q5]Ricordo dell'Abbraccio Infuso di Luffa", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAbbraccio Infuso di Luffa Abilità dell'Incisione Runica\nAumenta i danni inflitti da Falciata del 20%, la sua portata del 30% e gli accumuli massimi di 1.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Spedizione: Kryxis il Vorace\nRichiede: Druido (Guardiano Ferino)"}
MultiLanguageItemData['it'][183235] = {name = "[q5]Ricordo della Volontà dell'Ordine Naturale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVolontà dell'Ordine Naturale Abilità dell'Incisione Runica\nPelledura riduce i danni subiti del 10% aggiuntivo. Quando l'effetto inizia o termina in Forma d'Orso, ti fornisce Vello di Ferro e Rigenerazione Furiosa.\nIncisione Runica su: Testa, Polsi, Mani\nFonte: Bottino Incursione: Altimor il Predatore\nRichiede: Druido (Guardiano Ferino)"}
MultiLanguageItemData['it'][183236] = {name = "[q5]Ricordo dello Spirito Persistente di Ursoc", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRinomata Furia di Ursoc Abilità dell'Incisione Runica\nIn Forma d'Orso, Falciata ha una probabilità del 15% di attivare un'ulteriore Falciata.\n\n Falciata fornisce uno scudo che assorbe danni pari al 75% di tutti i danni che infligge.\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Druido (Guardiano Ferino)"}
MultiLanguageItemData['it'][183237] = {name = "[q5]Ricordo del Retaggio del Dormiente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRetaggio del Dormiente Abilità dell'Incisione Runica\n[ Incarnazione: Guardiano di Ursoc : Incarnazione: Guardiano di Ursoc / Berserk in Forma d'Orso] aumenta i danni inflitti del 0%, aumenta il ritorno vitale del 25% e fornisce immunità agli effetti di perdita di controllo del personaggio.\n\n Il suo tempo di recupero è ridotto di 30 s.\nIncisione Runica su: Fianchi, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Druido (Guardiano Ferino)"}
MultiLanguageItemData['it'][183238] = {name = "[q5]Ricordo dell'Infusione Verdeggiante", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nInfusione Verdeggiante Abilità dell'Incisione Runica\nGuarigione Immediata non consuma alcun effetto di cura periodico ed estende la durata dei tuoi effetti di cura periodici sul bersaglio di 10 s.\nIncisione Runica su: Spalle, Mani, Schiena\nFonte: Bottino Boss Esterno: Oranomonos la Ramificante\nRichiede: Druido (Rigenerazione)"}
MultiLanguageItemData['it'][183239] = {name = "[q5]Ricordo della Visione della Crescita Eterna", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVisione della Crescita Eterna Abilità dell'Incisione Runica\nLe cure fornite da Rinvigorimento hanno una probabilità del 2.5% di fornire un nuovo effetto di Rinvigorimento a un bersaglio vicino. (Possibilità di Apparire:3%)\nIncisione Runica su: Testa, Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Druido (Rigenerazione)"}
MultiLanguageItemData['it'][183240] = {name = "[q5]Ricordo dell'Albero Madre", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRicordo dell'Albero Madre Abilità dell'Incisione Runica\nCrescita Rigogliosa ha una probabilità del 40% di far sì che il successivo lancio di Rinvigorimento o Ricrescita raggiunga 3 alleati aggiuntivi entro 20 m dal bersaglio. (Possibilità di Apparire:40%)\nIncisione Runica su: Gambe, Polsi\nFonte: Bottino Incursione: Dama Inerva Venascura\nRichiede: Druido (Rigenerazione)"}
MultiLanguageItemData['it'][183241] = {name = "[q5]Ricordo della Lezione del Titano Oscuro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nLezione del Titano Oscuro Abilità dell'Incisione Runica\nPermette di lanciare Bocciolo di Vita su due bersagli alla volta, ma ne riduce le cure del 10%.\nIncisione Runica su: Collo, Schiena\nFonte: Bottino Spedizione: Ciambellano Supremo\nRichiede: Druido (Rigenerazione)"}
MultiLanguageItemData['it'][183242] = {name = "[q5]Ricordo dell'Eco di Eonar", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nPer acquisire questo ricordo, devi avere la reputazione Riverito con la Caccia Selvaggia e aver sbloccato Incisione Runica.\n\n\nEco di Eonar Abilità dell'Incisione Runica Circa 1 apparenze ogni minuto\nGli incantesimi e le abilità hanno una bassa probabilità di evocare un famiglio spirituale al tuo fianco, aumentando i danni inflitti del 10%, le cure fornite del 10% o la riduzione dei danni del 10% per 10 s in base al tuo ruolo. L'effetto è ripetuto su massimo 3 alleati al 50% dell'efficacia, preferendo gli alleati con lo stesso ruolo.\nIncisione Runica su: Fianchi, Polsi, Dito\nFonte: Per acquisire questo ricordo, devi avere la reputazione Riverito con la Caccia Selvaggia e aver sbloccato Incisione Runica."}
MultiLanguageItemData['it'][183243] = {name = "[q5]Ricordo del Giudizio dell'Arbiter", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nPer acquisire questo ricordo, devi avere la reputazione Riverito con gli Ascesi e aver sbloccato Incisione Runica.\n\n\nGiudizio dell'Arbiter Livello 80 Abilità dell'Incisione Runica Circa 6 apparenze ogni minuto\nInfliggere danni fornisce un'alta probabilità di scatenare un'esplosione di energia spirituale, infliggendo 2003 danni da ombra. Se entro 5-20 m c'è un altro alleato con il Giudizio dell'Arbiter, l'esplosione lo coinvolge, infliggendo 2003 danni da ombra ai nemici sulla traiettoria.\nIncisione Runica su: Polsi, Mani, Dito\nFonte: Per acquisire questo ricordo, devi avere la reputazione Riverito con gli Ascesi e aver sbloccato Incisione Runica."}
MultiLanguageItemData['it'][183244] = {name = "[q5]Ricordo del Rantolo della Fauce", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nPer acquisire questo ricordo, devi avere la reputazione Riverito con l'Armata Imperitura e aver sbloccato Incisione Runica.\n\n\nRantolo della Fauce Livello 80 Abilità dell'Incisione Runica Circa 6 apparenze ogni minuto\nUccidere un nemico ha un'alta probabilità di evocare un Rattofauce Esplosivo sulla posizione del cadavere. Dopo 6 s, il Rattofauce esplode, infliggendo 31747 danni da natura a tutti i nemici vicini, avvelenandoli e riducendone i danni inflitti del 5% per 10 s.\nIncisione Runica su: Gambe, Piedi, Mani\nFonte: Per acquisire questo ricordo, devi avere la reputazione Riverito con l'Armata Imperitura e aver sbloccato Incisione Runica."}
MultiLanguageItemData['it'][183245] = {name = "[q5]Ricordo della Sagacia di Norgannon", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nPer acquisire questo ricordo, devi avere la reputazione Riverito con la Corte dei Mietitori e aver sbloccato Incisione Runica.\n\n\nSagacia di Norgannon Abilità dell'Incisione Runica\nLanciare un incantesimo fornisce Sagacia, che si accumula fino a 10 volte. Quando ci si muove, è possibile lanciare incantesimi in movimento per 0.5 s per ogni accumulo di Sagacia. (100ms di recupero)\nIncisione Runica su: Gambe, Piedi, Schiena\nFonte: Per acquisire questo ricordo, devi avere la reputazione Riverito con la Corte dei Mietitori e aver sbloccato Incisione Runica."}
MultiLanguageItemData['it'][183246] = {name = "[q5]Ricordo della Proclamazione di Sephuz", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nProclamazione di Sephuz Livello 80 Abilità dell'Incisione Runica\nRiduce l'efficacia degli effetti di controllo delle creature subiti del 10%. Affliggere un nemico con un effetto di perdita di controllo delle creature, interrompere il lancio d'incantesimi di un nemico o dissolvere un effetto da un qualsiasi bersaglio, aumenta tutti i tuoi attributi secondari di 217 per 15 s. L'effetto non può verificarsi più di una volta ogni 30 s. (30s di recupero)\nIncisione Runica su: Collo, Spalle, Torso\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo."}
MultiLanguageItemData['it'][183247] = {name = "[q5]Ricordo dell'Esca di Fantaplasma Stabile", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nEsca di Fantaplasma Stabile Abilità dell'Incisione Runica Circa 4 apparenze ogni minuto\nAumenta il Fantaplasma ottenuto del 25%. Depredare il Fantaplasma dai nemici fornisce una probabilità di evocare un Demone di Fantaplasma, che inizia a correre verso una direzione casuale. Uccidere il demone aumenta il Fantaplasma ottenuto dall'intero gruppo del 10% aggiuntivo per 1 min.\nIncisione Runica su: Collo, Polsi, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Blocco 6+"}
MultiLanguageItemData['it'][183248] = {name = "[q5]Ricordo dell'Occhio del Carceriere", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nPer acquisire questo ricordo, devi avere la reputazione Ambivalente con Ve'nari e aver sbloccato Incisione Runica.\n\n\nTerzo Occhio del Carceriere Abilità dell'Incisione Runica\nUccidere un nemico fornisce Terzo Occhio, aumentando [[Primary Stat]] del 1% per 10 s. Si accumula fino a 7 volte. La durata aumenta di 1 s per ogni accumulo aggiuntivo. La durata di Terzo Occhio aumenta del 50% nella Fauce.\nIncisione Runica su: Testa, Collo, Spalle, Fianchi\nFonte: Per acquisire questo ricordo, devi avere la reputazione Ambivalente con Ve'nari e aver sbloccato Incisione Runica."}
MultiLanguageItemData['it'][183249] = {name = "[q5]Ricordo del Sacrificio della Vitalità", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nRichiede Fama 14\n\n\nSacrificio della Vitalità Abilità dell'Incisione Runica\nSubire danni ingenti da un personaggio o da un nemico élite aumenta i danni inflitti e le cure fornite del 3% dei danni subiti, fino a un massimo del 9% per 20 s.\n\n L'effetto può verificarsi solo una volta ogni 30 s. (30s di recupero)\nIncisione Runica su: Testa, Spalle, Torso, Dito\nFonte: Acquistato in cambio di Animum dal Quartiermastro della Fama. Devi avere Fama 14 con la tua Congrega per acquistare questo ricordo."}
MultiLanguageItemData['it'][183250] = {name = "[q5]Ricordo del Richiamo Selvaggio", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRichiamo Selvaggio Abilità dell'Incisione Runica\nRiduce il tempo di recupero degli Aspetti [ Precisione di Tiro : e di Precisione / Sopravvivenza : e di Assalto Coordinato ] del 35%.\nIncisione Runica su: Polsi, Dito\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Cacciatore"}
MultiLanguageItemData['it'][183251] = {name = "[q5]Ricordo dello Stratagemma Vile", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nStratagemma Vile Abilità dell'Incisione Runica Istantaneo\nRiduce il tempo di recupero di Morte Apparente di 15.0 s. Morte Apparente dissolve la maggior parte delle penalità.\nIncisione Runica su: Collo, Torso\nFonte: Missione: La Gran Banca\nRichiede: Cacciatore"}
MultiLanguageItemData['it'][183252] = {name = "[q5]Ricordo dell'Apparato da Bracconaggio", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nApparato da Bracconaggio di Nesingwary Abilità dell'Incisione Runica\nQuando una trappola viene attivata, rigenera 45 focus e aumenta la rigenerazione di focus del 100% per 5 s.\nIncisione Runica su: Collo, Fianchi, Piedi\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Cacciatore"}
MultiLanguageItemData['it'][183253] = {name = "[q5]Ricordo delle Braci della Forgia dell'Anima", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBraci della Forgia dell'Anima Abilità dell'Incisione Runica\nLanciare un Bengala su una propria Trappola di Pece fa bruciare fino a 5 nemici all'interno dell'area d'effetto, infliggendo ([240% of Attack Power]) danni da fuoco in 12 s.\nIncisione Runica su: Testa, Spalle, Dito\nFonte: Bottino Spedizione: Ingra Maloch\nRichiede: Cacciatore"}
MultiLanguageItemData['it'][183254] = {name = "[q5]Ricordo del Comando Feroce", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nComando Feroce Abilità dell'Incisione Runica\nOrdine di Morte ha una probabilità del 30% di evocare anche una Bestia Feroce che attacca il bersaglio.\nIncisione Runica su: Torso, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Cacciatore (Affinità Animale)"}
MultiLanguageItemData['it'][183255] = {name = "[q5]Ricordo del Morso del Cobra del Destafiamme", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nMorso del Cobra del Destafiamme Abilità dell'Incisione Runica\nTiro del Cobra ha una probabilità del 50% di azzerare il costo in focus del successivo Ordine di Morte. (Possibilità di Apparire:50%)\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Cacciatore (Affinità Animale)"}
MultiLanguageItemData['it'][183256] = {name = "[q5]Ricordo di Qa'pla, Ordine di Guerra in Eredun", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nQa'pla, Ordine di Guerra in Eredun Abilità dell'Incisione Runica\nAumenta i danni inflitti da Tiro Lacerante del 10%. Inoltre, applicare l'effetto di Tiro Lacerante azzera il tempo di recupero di Ordine di Morte.\nIncisione Runica su: Spalle, Mani\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Cacciatore (Affinità Animale)"}
MultiLanguageItemData['it'][183257] = {name = "[q5]Ricordo delle Zanne Perforanti del Predatore di Rylak", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nZanne Perforanti del Predatore di Rylak Abilità dell'Incisione Runica\nQuando Ira Bestiale è attiva, i danni critici inflitti dal tuo famiglio sono aumentati del 35%.\nIncisione Runica su: Gambe, Piedi, Schiena\nFonte: Bottino Spedizione: Devos, Eletta del Dubbio\nRichiede: Cacciatore (Affinità Animale)"}
MultiLanguageItemData['it'][183258] = {name = "[q5]Ricordo del Focus Preciso dell'Artiglio dell'Aquila", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFocus Preciso dell'Artiglio dell'Aquila Abilità dell'Incisione Runica\nPrecisione dura 3.0 s aggiuntivi e riduce il costo in focus di tutte le abilità del 25%.\nIncisione Runica su: Testa, Fianchi, Mani\nFonte: Bottino Incursione: Altimor il Predatore\nRichiede: Cacciatore (Precisione di Tiro)"}
MultiLanguageItemData['it'][183259] = {name = "[q5]Ricordo dei Segreti della Veglia Impassibile", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSegreti della Veglia Impassibile Abilità dell'Incisione Runica\nTiri Ingannevoli fornisce una probabilità del 50% di ripristinare una carica di Tiro Mirato e di azzerare il costo in focus del successivo Tiro Mirato.\nIncisione Runica su: Polsi, Mani\nFonte: Bottino: Torgast, Torre dei Dannati. Bastioni Superiori, Blocco 3+\nRichiede: Cacciatore (Precisione di Tiro)"}
MultiLanguageItemData['it'][183260] = {name = "[q5]Ricordo dell'Astuzia dell'Inseguitore di Serpenti", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAstuzia dell'Inseguitore di Serpenti Abilità dell'Incisione Runica\nTiro Mirato lancia anche un Morso del Serpente al bersaglio primario.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino Spedizione: Domina Lamatossica\nRichiede: Cacciatore (Precisione di Tiro)"}
MultiLanguageItemData['it'][183261] = {name = "[q5]Ricordo dei Tiri Crescenti", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTiri Crescenti Abilità dell'Incisione Runica\nAumenta i danni inflitti da Rapidità di Tiro del 35%. Inoltre, Tiro Mirato ha una probabilità del 15% di azzerare il tempo di recupero di Rapidità di Tiro. (Possibilità di Apparire:15%)\nIncisione Runica su: Collo, Polsi\nFonte: Bottino Boss Esterno: Oranomonos la Ramificante\nRichiede: Cacciatore (Precisione di Tiro)"}
MultiLanguageItemData['it'][183262] = {name = "[q5]Ricordo dei Frammenti d'Ossa del Macellaio", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFrammenti d'Ossa del Macellaio Abilità dell'Incisione Runica\n[ Morso della Mangusta / Assalto del Raptor] aumenta i danni inflitti dalla successiva [ Macellazione / Scorticatura] del 20%. Si accumula fino a 6 volte.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Cacciatore (Sopravvivenza)"}
MultiLanguageItemData['it'][183263] = {name = "[q5]Ricordo degli Iniettori di Veleno Latente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nIniettori di Veleno Latente Abilità dell'Incisione Runica\nI danni inflitti da Morso del Serpente affliggono il bersaglio con Veleno Latente. Si accumula fino a 10 volte. [ Morso della Mangusta / Assalto del Raptor] consuma tutti gli accumuli di Veleno Latente, infliggendo ([20.7% of Attack Power]) danni da natura per accumulo consumato.\nIncisione Runica su: Testa, Mani\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Cacciatore (Sopravvivenza)"}
MultiLanguageItemData['it'][183264] = {name = "[q5]Ricordo degli Assalti Frustranti del Predatore di Rylak", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAssalti Frustranti del Predatore di Rylak Abilità dell'Incisione Runica\n[ Morso della Mangusta / Assalto del Raptor] ha una probabilità del 15% di azzerare il tempo di recupero di Bomba di Fuocobrado. (Possibilità di Apparire:15%)\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Cacciatore (Sopravvivenza)"}
MultiLanguageItemData['it'][183265] = {name = "[q5]Ricordo del Fascio di Fuocobrado", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFascio di Fuocobrado Abilità dell'Incisione Runica\nLa Bomba di Fuocobrado rilascia un fascio di bombe aggiuntivo intorno al bersaglio, ciascuna delle quali esplode, infliggendo ([33% of Attack Power]) danni da fuoco. Danni ridotti oltre i 8 bersagli.\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino Spedizione: Fornitrice Xy'exa\nRichiede: Cacciatore (Sopravvivenza)"}
MultiLanguageItemData['it'][183266] = {name = "[q5]Ricordo del Comando Disciplinare", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nComando Disciplinare Abilità dell'Incisione Runica\nLanciare un incantesimo arcano, di gelo e di fuoco entro 10 s uno dall'altro aumenta i danni critici inflitti da tutti i tuoi incantesimi del 20%. Può verificarsi solo una volta ogni 30 s.\nIncisione Runica su: Polsi, Dito\nFonte: Bottino Spedizione: Evocanebbie"}
MultiLanguageItemData['it'][183267] = {name = "[q5]Ricordo del Potenziale Esteso", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPotenziale Esteso Abilità dell'Incisione Runica Circa 2 apparenze ogni minuto\nPalla di Fuoco, Dardo di Gelo e Detonazione Arcana hanno una probabilità di attivare Potenziale Esteso, in modo che il successivo effetto di Serie Bollente, Mente Fredda o Lancio Istintivo non venga consumato.\nIncisione Runica su: Fianchi, Piedi\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Mago"}
MultiLanguageItemData['it'][183268] = {name = "[q5]Ricordo della Stalattite Spaventosa", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nStalattite Spaventosa Abilità dell'Incisione Runica\nI tuoi incantesimi non interrompono l'effetto di Esplosione Gelida e i nemici colpiti da Esplosione Gelida subiscono il 15% di danni aggiuntivi dagli incantesimi di fuoco e arcani per 8 s.\nIncisione Runica su: Testa, Collo, Spalle\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Mago"}
MultiLanguageItemData['it'][183269] = {name = "[q5]Ricordo della Protezione della Trinità", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nProtezione della Trinità Abilità dell'Incisione Runica\nLanciare un qualsiasi incantesimo Barriera fornisce gli effetti di Barriera Fiammeggiante, Barriera di Ghiaccio e Barriera Prismatica. L'effetto di assorbimento di ogni scudo ha il 65% dell'efficacia. (750ms di recupero)\nIncisione Runica su: Collo, Torso\nFonte: Missione: La Gran Banca\nRichiede: Mago"}
MultiLanguageItemData['it'][183270] = {name = "[q5]Ricordo del Bombardamento Arcano", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBombardamento Arcano Abilità dell'Incisione Runica\nSbarramento Arcano infligge il 130% di danni aggiuntivi contro i bersagli che sono al di sotto del 35% della salute massima.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Mago (Arcano)"}
MultiLanguageItemData['it'][183271] = {name = "[q5]Ricordo dell'Infinito Arcano", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\nArmonia Arcana Abilità dell'Incisione Runica\nOgni volta che Missili Arcani colpisce un nemico, i danni inflitti dal successivo Sbarramento Arcano aumentano del 8%. Si accumula fino a 18 volte.\nIncisione Runica su: Spalle, Mani\nFonte: Bottino Spedizione: I Manalampo\nRichiede: Mago (Arcano)"}
MultiLanguageItemData['it'][183272] = {name = "[q5]Ricordo della Tempesta d'Aspirazione", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTempesta d'Aspirazione Abilità dell'Incisione Runica\nEvocazione fornisce 1 carica arcana e, durante la canalizzazione, l'Intelletto aumenta del 2% ogni 0.5 s. Dura 30 s.\nIncisione Runica su: Gambe, Piedi, Mani\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Mago (Arcano)"}
MultiLanguageItemData['it'][183273] = {name = "[q5]Ricordo della Distorsione Temporale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nDistorsione Temporale Abilità dell'Incisione Runica\nDurante Spiazzamento Temporale o un altro effetto simile, è possibile lanciare Distorsione Temporale aumentando la propria celerità del 30% per 40 s.\nIncisione Runica su: Torso, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Bastioni Superiori, Blocco 3+"}
MultiLanguageItemData['it'][183274] = {name = "[q5]Ricordo dell'Incantamento Febbrile", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nIncantamento Febbrile Abilità dell'Incisione RunicaOgni colpo critico consecutivo aumenta i danni critici inflitti del 3%, fino a un massimo del 15%.\nIncisione Runica su: Testa, Fianchi, Mani\nFonte: Bottino Boss Esterno: Oranomonos la Ramificante\nRichiede: Mago (Fuoco)"}
MultiLanguageItemData['it'][183275] = {name = "[q5]Ricordo della Tempesta di Fuoco", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTempesta di Fuoco Abilità dell'Incisione Runica Circa 1.66 apparenze ogni minuto\nQuando Serie Bollente si attiva, fornisce una bassa probabilità di azzerare il tempo di lancio di Pirosfera e Colonna di Fuoco e di fare in modo che tutti i danni da loro inflitti per 4 s siano critici.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino Spedizione: Ciambellano Supremo\nRichiede: Mago (Fuoco)"}
MultiLanguageItemData['it'][183276] = {name = "[q5]Ricordo del Cielo Fuso", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nCielo Fuso Abilità dell'Incisione Runica\nInfliggere danni a un nemico con 18 Palle di Fuoco o Pirosfere fa sì che la tua prossima Palla di Fuoco richiami una Meteora sul bersaglio. Colpire un personaggio nemico conta il doppio.\nIncisione Runica su: Collo, Polsi\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Mago (Fuoco)"}
MultiLanguageItemData['it'][183277] = {name = "[q5]Ricordo della Benedizione del Re del Sole", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\nBenedizione del Re del Sole Abilità dell'Incisione Runica\nAl termine di 8 Serie Bollenti, la successiva Pirosfera non istantanea lanciata entro 15 s attiva Combustione per 6 s.\nIncisione Runica su: Polsi, Mani\nFonte: Bottino Incursione: Salvezza del Re del Sole\nRichiede: Mago (Fuoco)"}
MultiLanguageItemData['it'][183278] = {name = "[q5]Ricordo del Fronte Gelido", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFronte Gelido Abilità dell'Incisione Runica\nLanciare 30 Dardi di Gelo o Raffiche di Colpi richiama un Globo Congelato verso il bersaglio. Colpire un giocatore nemico conta il doppio.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Spedizione: Nalthor il Vincolabrina\nRichiede: Mago (Gelo)"}
MultiLanguageItemData['it'][183279] = {name = "[q5]Ricordo dei Venti Gelidi", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVenti Gelidi Abilità dell'Incisione Runica\nQuando Globo Congelato è attivo, fornisce l'effetto Dita di Gelo ogni 2 s.\nIncisione Runica su: Testa, Mani\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Mago (Gelo)"}
MultiLanguageItemData['it'][183280] = {name = "[q5]Ricordo dei Frammenti Glaciali", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFrammenti Glaciali Abilità dell'Incisione Runica\nLancia di Ghiaccio ha una probabilità del 20% di esplodere in schegge di ghiaccio quando colpisce un bersaglio, infliggendo ([40% of Spell Power]) danni da gelo a tutti i nemici vicini al bersaglio. Infligge danni ridotti oltre i 5 bersagli. La probabilità aumenta del 100% se il bersaglio si trova nell'area d'effetto di una tua Tormenta.\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Mago (Gelo)"}
MultiLanguageItemData['it'][183281] = {name = "[q5]Ricordo del Ghiaccio Scivoloso", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nGhiaccio Scivoloso Abilità dell'Incisione Runica\nQuando Vene Gelide è attivo, ogni Dardo di Gelo riduce il tempo di lancio di Dardo di Gelo del 2% e aumenta i danni che infligge del 2%. Si accumula fino a 10 volte.\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Mago (Gelo)"}
MultiLanguageItemData['it'][183282] = {name = "[q5]Ricordo del Tocco Fatale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTocco Fatale Abilità dell'Incisione Runica Istantaneo\nRiduce il tempo di recupero di Tocco della Morte di 120 s.\nIncisione Runica su: Polsi, Dito\nFonte: Bottino Spedizione: Mueh'zala\nRichiede: Monaco"}
MultiLanguageItemData['it'][183283] = {name = "[q5]Ricordo della Delizia dell'Invocatore", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nDelizia dell'Invocatore Abilità dell'Incisione Runica\nAumenta la celerità del 33% per 20 s dopo avere evocato un Celestiale.\nIncisione Runica su: Testa, Spalle, Schiena\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Monaco"}
MultiLanguageItemData['it'][183284] = {name = "[q5]Ricordo del Kata", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFuga dalla Realtà Abilità dell'Incisione Runica\nDopo aver lanciato Trascendenza: Trasferimento, è possibile rilanciare Trascendenza: Trasferimento entro 10 s ignorandone il tempo di recupero.\n\n Durante questo lasso di tempo, se si lancia Vivificazione su se stessi, le cure fornite sono aumentate del 70% e il costo è ridotto del 50%.\nIncisione Runica su: Collo, Torso\nFonte: Missione: La Gran Banca\nRichiede: Monaco"}
MultiLanguageItemData['it'][183285] = {name = "[q5]Ricordo della Ricapriola", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nRicapriola Abilità dell'Incisione Runica Istantaneo\nDurante [ Dardo del Chi / Capriola] si è immuni a effetti d'immobilizzazione e rallentamento.\nIncisione Runica su: Fianchi, Piedi\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Monaco"}
MultiLanguageItemData['it'][183286] = {name = "[q5]Ricordo del Palmo ad Alta Fermentazione", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVigore di Shaohao Abilità dell'Incisione Runica\nPalmo della Tigre ha una probabilità del 40% di infliggere il 300% dei danni normali e ridurre il tempo di recupero restante delle tue Birre di 2 s aggiuntivi.\nIncisione Runica su: Torso, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Monaco (Mastro Birraio)"}
MultiLanguageItemData['it'][183287] = {name = "[q5]Ricordo delle Passioni Carbonizzate", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPassioni Carbonizzate Abilità dell'Incisione Runica\nSoffio di Fuoco incendia la tua gamba destra per 8 s, permettendo a Calcio dell'Oscuramento e Calcio Rotante della Gru di infliggere il 100% di danni aggiuntivi come danni da fuoco e di rinnovare la durata di Soffio di Fuoco sul bersaglio.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Monaco (Mastro Birraio)"}
MultiLanguageItemData['it'][183288] = {name = "[q5]Ricordo dell'Infusione Celestiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nMescita Vigorosa Abilità dell'Incisione Runica\nBirra Purificatrice ha una probabilità del 35% di non consumare alcuna carica e Birra Celestiale aumenta l'armatura del 50% per 8 s.\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Monaco (Mastro Birraio)"}
MultiLanguageItemData['it'][183289] = {name = "[q5]Ricordo dell'Ultimo Respiro di Triplo Malto", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nUltimo Barilotto di Triplo Malto Abilità dell'Incisione Runica\nAumenta i danni inflitti da Lancio del Barile del 30% e le sue cariche di 1.\nIncisione Runica su: Spalle, Fianchi, Mani\nFonte: Bottino Spedizione: Generale Kaal\nRichiede: Monaco (Mastro Birraio)"}
MultiLanguageItemData['it'][183290] = {name = "[q5]Ricordo degli Antichi Insegnamenti del Monastero", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAntichi Insegnamenti del Monastero Abilità dell'Incisione Runica\nDopo aver lanciato Fonte dell'Essenza, Palmo della Tigre, Calcio dell'Oscuramento e Calcio del Sole Nascente forniscono cure pari al 250% dei danni inflitti a un alleato ferito entro 20 m. Dura 15 s.\nIncisione Runica su: Polsi, Mani\nFonte: Bottino Spedizione: Devos, Eletta del Dubbio\nRichiede: Monaco (Misticismo)"}
MultiLanguageItemData['it'][183291] = {name = "[q5]Ricordo del Sussurro di Yu'lon", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSussurro di Yu'lon Abilità dell'Incisione Runica Portata di 100 m\nTè della Concentrazione del Tuono ti permette di usare il soffio di Yu'lon, che cura fino a 6 alleati entro 15 m di [([60% of Spell Power]) * (3)] in 2 s.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Monaco (Misticismo)"}
MultiLanguageItemData['it'][183292] = {name = "[q5]Ricordo del Focus Torbido", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFocus Torbido Abilità dell'Incisione Runica\nFornire cure con Nebbia Avvolgente o Vivificazione mentre si canalizza Nebbie del Sollievo aumenta le cure fornite del 20% e ne riduce il costo in mana del 20%. Si accumula fino a 3 volte.\n\n Al termine della canalizzazione di Nebbie del Sollievo, l'effetto si dissolve.\nIncisione Runica su: Collo, Polsi\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Monaco (Misticismo)"}
MultiLanguageItemData['it'][183293] = {name = "[q5]Ricordo della Lacrima del Mattino", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nLacrima del Mattino Abilità dell'Incisione Runica\nLanciare Vivificazione o Nebbia Avvolgente su un bersaglio con Nebbia Curativa ha una probabilità del 10% di diffondere Nebbia Curativa su un altro bersaglio.\n\n Le cure fornite da Vivificazione tramite Nebbia Curativa aumentano del 20% e Nebbia Avvolgente cura anche gli alleati con Nebbia Curativa del 20% delle cure fornite.\nIncisione Runica su: Testa, Fianchi\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Monaco (Misticismo)"}
MultiLanguageItemData['it'][183294] = {name = "[q5]Ricordo dell'Accensione di Giada", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAccensione di Giada Abilità dell'Incisione Runica\nQuando si infliggono danni a un bersaglio con Pugni della Furia, si ottiene 1 accumulo di Energia Chi, fino a un massimo di 30 accumuli.\n\n Usare Calcio Rotante della Gru causa un'Esplosione di Chi, infliggendo ([65% of Attack Power]) danni a tutti i nemici entro 8 m. I danni aumentano del 5% per ogni accumulo di Energia Chi.\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Monaco (Impeto)"}
MultiLanguageItemData['it'][183295] = {name = "[q5]Ricordo dell'Altocielo di Keefer", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAltocielo di Keefer Abilità dell'Incisione Runica\nPalmo della Tigre ha una portata di 10 m e, quando viene lanciato, ti fa scattare istantaneamente verso il bersaglio.\n\n Palmo della Tigre applica un effetto che aumenta la probabilità di critico contro quel bersaglio del 50% per 6 s. L'effetto non può applicarsi più di una volta ogni 1 min per bersaglio.\nIncisione Runica su: Testa, Collo, Mani\nFonte: Bottino Boss Esterno: Mortanis\nRichiede: Monaco (Impeto)"}
MultiLanguageItemData['it'][183296] = {name = "[q5]Ricordo del Condensatore dell'Ultimo Imperatore", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nCondensatore dell'Ultimo Imperatore Abilità dell'Incisione Runica\nLe abilità che consumano chi aumentano i danni inflitti dal successivo Fulmine di Giada Crepitante del 100% e ne riducono il costo del 5%. Si accumula fino a 20 volte.\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino Incursione: Ingegnere Xy'mox\nRichiede: Monaco (Impeto)"}
MultiLanguageItemData['it'][183297] = {name = "[q5]Ricordo del Tesoro di Xuen", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTenuta Feroce di Xuen Abilità dell'Incisione Runica\nI colpi critici di Calcio del Sole Nascente riducono il tempo di recupero di Pugni della Furia di 5.0 s.\n\n Al termine di Pugni della Furia, la probabilità di critico di Calcio del Sole Nascente aumenta del 40% per 5 s.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Spedizione: Kryxis il Vorace\nRichiede: Monaco (Impeto)"}
MultiLanguageItemData['it'][183298] = {name = "[q5]Ricordo dell'Eletto Pazzo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nEletto Pazzo Abilità dell'Incisione Runica\nMartello dell'Ira infligge il 30% di danni aggiuntivi ed estende la durata di [ Crociata ] [ Crociato Vendicatore / Ira Vendicatrice ] di 1 s.\nIncisione Runica su: Fianchi, Piedi\nFonte: Missione: La Gran Banca\nRichiede: Paladino"}
MultiLanguageItemData['it'][183299] = {name = "[q5]Ricordo del Tramonto e dell'Alba", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nDel Tramonto e dell'Alba Abilità dell'Incisione Runica\nAl raggiungimento di 5 cariche di potere sacro, si ottiene Benedizione dell'Alba. Al raggiungimento di 0 cariche di potere sacro, si ottiene Benedizione del Tramonto.\n\nBenedizione dell'Alba\nAumenta i danni inflitti e le cure fornite del 6% per 12 s.\n\nBenedizione del Tramonto\nRiduce i danni subiti del 4% per 12 s.\nIncisione Runica su: Testa, Collo, Spalle\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Paladino"}
MultiLanguageItemData['it'][183300] = {name = "[q5]Ricordo del Giudizio del Magistrato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nGiudizio del Magistrato Abilità dell'Incisione Runica\nGiudizio ha una probabilità del [ Sacro : 60% / Protezione : 45% /\n\nCastigo\n 75% ] di ridurre il costo della successiva abilità che consuma cariche di potere sacro di 1. (700ms di recupero)\nIncisione Runica su: Polsi, Dito\nFonte: Bottino Spedizione: Xav l'Immortale\nRichiede: Paladino"}
MultiLanguageItemData['it'][183301] = {name = "[q5]Ricordo della Devozione di Uther", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nDevozione di Uther Abilità dell'Incisione Runica\nRiduce i tempi di recupero di Benedizione della Libertà [ Benedizione del Sacrificio : Benedizione del Sacrificio ] e [ Benedizione della Protezione Magica / Benedizione della Protezione] di 1 s per ogni carica di potere sacro consumata.\nIncisione Runica su: Collo, Torso\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Paladino"}
MultiLanguageItemData['it'][183302] = {name = "[q5]Ricordo dell'Inflorescenza del Pozzo Solare", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nInflorescenza del Pozzo Solare Abilità dell'Incisione Runica\nAumenta le cariche di Infusione di Luce di 1 e ne aumenta gli effetti del 30%.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Paladino (Sacro)"}
MultiLanguageItemData['it'][183303] = {name = "[q5]Ricordo dell'Ultimo Respiro di Maraad", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nUltimo Respiro di Maraad Abilità dell'Incisione Runica\nLuce dell'Alba aumenta le successive cure fornite da Luce del Martire del 10% per ogni alleato curato e permette a Luce del Martire di curare tramite l'effetto di Faro di Luce.\n\n Inoltre, Luce del Martire infligge danni nel corso di 5 s, invece che istantaneamente.\nIncisione Runica su: Torso, Dito\nFonte: Bottino Spedizione: Gran Supervisore Berillia\nRichiede: Paladino (Sacro)"}
MultiLanguageItemData['it'][183304] = {name = "[q5]Ricordo di Spezzaombre, Alba del Sole", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\nSpezzaombre, Alba del Sole Abilità dell'Incisione Runica\nAumenta la portata di Luce dell'Alba a 40 m. Tutti gli alleati nell'area d'effetto di Luce dell'Alba beneficiano di Maestria: Araldo della Luce come se fossero entro 10 m per 8 s.\n\n Parola di Gloria riceve un beneficio aggiuntivo del 50% dalla maestria.\nIncisione Runica su: Spalle, Fianchi, Mani\nFonte: Bottino Incursione: Salvezza del Re del Sole\nRichiede: Paladino (Sacro)"}
MultiLanguageItemData['it'][183305] = {name = "[q5]Ricordo della Barriera Folgorante", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBarriera Folgorante Abilità dell'Incisione Runica\nFolgore Sacra protegge il bersaglio con uno scudo di Luce Sacra per 18 s, assorbendone danni subiti pari al 20% dei danni da sacro inflitti da Folgore Sacra ogni 6 s. Si possono proteggere fino a un massimo di 5 bersagli.\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Paladino (Sacro)"}
MultiLanguageItemData['it'][183306] = {name = "[q5]Ricordo del Baluardo della Giusta Furia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBaluardo della Giusta Furia Abilità dell'Incisione Runica\nOgni bersaglio colpito da Scudo del Vendicatore aumenta i danni inflitti dal successivo Scudo del Virtuoso del 30%. Si accumula fino a 5 volte e ne aumenta la portata di 6 m.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino Spedizione: Gran Giudice Aleez\nRichiede: Paladino (Protezione)"}
MultiLanguageItemData['it'][183307] = {name = "[q5]Ricordo del Sigillo Inciso del Vendicatore Sacro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSigillo Inciso del Vendicatore Sacro Abilità dell'Incisione Runica\nGli usi di Scudo del Vendicatore hanno una probabilità del 35% di azzerarne istantaneamente il tempo di recupero. (Possibilità di Apparire:35%)\nIncisione Runica su: Testa, Fianchi\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Paladino (Protezione)"}
MultiLanguageItemData['it'][183308] = {name = "[q5]Ricordo del Regno dei Re Eterni", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRegno dei Re Eterni Abilità dell'Incisione Runica\nQuando si è al di sotto del 20% della salute massima, si viene infusi dal Guardiano dei Re Antichi per 4 s. L'effetto non può verificarsi più di una volta ogni 45 s.\nIncisione Runica su: Collo, Torso, Polsi\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Paladino (Protezione)"}
MultiLanguageItemData['it'][183309] = {name = "[q5]Ricordo del Santuario del Protettore Ardente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSantuario del Protettore Ardente Abilità dell'Incisione Runica\nSe Fervido Difensore salva dalla morte, rigenera il 40% di salute aggiuntiva.\n\n Se Fervido Difensore termina senza aver salvato dalla morte, il suo tempo di recupero si riduce del 40%.\nIncisione Runica su: Collo, Polsi\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Paladino (Protezione)"}
MultiLanguageItemData['it'][183310] = {name = "[q5]Ricordo dell'Impeto dell'Avanguardia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nImpeto dell'Avanguardia Abilità dell'Incisione Runica\nAumenta le cariche di Martello dell'Ira di 1 e ne aumenta i danni da sacro inflitti del 4% per 10 s. Si accumula fino a 3 volte.\nIncisione Runica su: Testa, Piedi, Mani\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Paladino (Castigo)"}
MultiLanguageItemData['it'][183311] = {name = "[q5]Ricordo del Verdetto Finale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVerdetto Finale Abilità dell'Incisione Runica Portata di 10 m\nRichiede il livello 1"}
MultiLanguageItemData['it'][183312] = {name = "[q5]Ricordo dell'Inquisitore Implacabile", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nInquisitore Implacabile Abilità dell'Incisione Runica\nConsumare cariche di potere sacro aumenta la celerità del 1% per ogni lancio che consuma cariche di potere sacro per 12 s. Si accumula fino a 5 volte. (500ms di recupero)\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Bastioni Superiori, Blocco 3+\nRichiede: Paladino"}
MultiLanguageItemData['it'][183313] = {name = "[q5]Ricordo della Tempesta dell'Araldo della Luce", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTempesta dell'Araldo della Luce Abilità dell'Incisione Runica\nTempesta Divina proietta un'ondata di luce aggiuntiva che colpisce tutti i nemici frontali entro 20 m infliggendo il 20% dei danni di Tempesta Divina.\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino Spedizione: Orifrion\nRichiede: Paladino (Castigo)"}
MultiLanguageItemData['it'][183314] = {name = "[q5]Ricordo delle Ombre Cauterizzanti", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nOmbre Cauterizzanti Abilità dell'Incisione Runica\nQuando l'effetto [ Epurazione dal Male / Parola d'Ombra: Dolore] termina su un bersaglio, 3 alleati entro 30 m dal bersaglio rigenerano ([75% of Spell Power]) salute.\nIncisione Runica su: Fianchi, Piedi\nFonte: Bottino Spedizione: Mordretha, l'Imperatrice Eterna\nRichiede: Sacerdote"}
MultiLanguageItemData['it'][183315] = {name = "[q5]Ricordo della Contemplazione Moderata", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nContemplazione Moderata Abilità dell'Incisione Runica\nOgni 15 s durante i quali non si sta lanciando Cura Rapida, le cure fornite dalla successiva Cura Rapida sono aumentate del 50%. Si accumula fino a 4 volte.\nIncisione Runica su: Collo, Torso\nFonte: Missione: La Gran Banca\nRichiede: Sacerdote"}
MultiLanguageItemData['it'][183316] = {name = "[q5]Ricordo dei Gemelli delle Sacerdotesse del Sole", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nGemelli delle Sacerdotesse del Sole Abilità dell'Incisione Runica\nInfusione di Potere fornisce il 100% dei propri effetti anche a chi la lancia, se lanciata su un alleato.\nIncisione Runica su: Testa, Collo, Spalle\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Sacerdote"}
MultiLanguageItemData['it'][183317] = {name = "[q5]Ricordo della Volta dei Cieli", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nVolta dei Cieli Abilità dell'Incisione Runica\nBalzo della Fede fa balzare verso il bersaglio e ha 2 cariche.\nIncisione Runica su: Polsi, Dito\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Sacerdote"}
MultiLanguageItemData['it'][183318] = {name = "[q5]Ricordo del Vuoto Mentale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nLucidità Mentale Abilità dell'Incisione Runica\n[ Involucro Spirituale : Involucro Spirituale aumenta la durata degli effetti di Espiazione attivi di 3 s e riduce il costo in mana degli incantesimi d'attacco del 30% / Durante Estasi, Parola del Potere: Scudo ha un costo in mana ridotto del 20% e fornisce effetti di Espiazione più lunghi di 6 s.] (Possibilità di Apparire:50%)\nIncisione Runica su: Torso, Dito\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Sacerdote (Disciplina)"}
MultiLanguageItemData['it'][183319] = {name = "[q5]Ricordo del Riflesso Cristallino", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRiflesso Cristallino Abilità dell'Incisione Runica\nParola del Potere: Scudo cura istantaneamente il bersaglio di ([42% of Spell Power]) e riflette il 20% dei danni subiti assorbiti.\nIncisione Runica su: Spalle, Mani\nFonte: Bottino Spedizione: Margravio Stradama\nRichiede: Sacerdote (Disciplina)"}
MultiLanguageItemData['it'][183320] = {name = "[q5]Ricordo del Bacio della Morte", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBacio della Morte Abilità dell'Incisione Runica\nRiduce il tempo di recupero di Parola d'Ombra: Morte di 12 s e fa sì che i suoi danni attivino l'effetto di Espiazione quando viene lanciata su bersagli con meno del ([85% of Spell Power])% della salute massima.\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Sacerdote (Disciplina)"}
MultiLanguageItemData['it'][183321] = {name = "[q5]Ricordo del Penitente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nIl Penitente Abilità dell'Incisione Runica\nParola del Potere: Radiosità ha una probabilità del 60% di aumentare i colpi lanciati dalla successiva Contrizione di 3 e di renderla priva di costo.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Sacerdote (Disciplina)"}
MultiLanguageItemData['it'][183322] = {name = "[q5]Ricordo dell'Immagine Divina", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nImmagine Divina Abilità dell'Incisione Runica\nLe Parole Sacre hanno una probabilità di evocare un'immagine di un Naaru al tuo fianco. Per 15 s, ogni volta che si lancia un incantesimo, il Naaru ne lancia uno simile. (Possibilità di Apparire:25%)\nIncisione Runica su: Testa, Fianchi, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Sacerdote (Sacro)"}
MultiLanguageItemData['it'][183323] = {name = "[q5]Ricordo della Concentrazione Rapida", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nConcentrazione Rapida Abilità dell'Incisione Runica\nOgni volta che si lancia Cura Rapida, il tempo di lancio di Cura si riduce di 0.2 s e le cure che fornisce aumentano del 3% per 20 s. Si accumula fino a 5 volte.\nIncisione Runica su: Collo, Polsi\nFonte: Bottino Spedizione: Gran Supervisore Berillia\nRichiede: Sacerdote (Sacro)"}
MultiLanguageItemData['it'][183324] = {name = "[q5]Ricordo dell'Apparato Armonioso", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nApparato Armonioso Abilità dell'Incisione Runica\nCircolo di Guarigione riduce il tempo di recupero di Parola Sacra: Santificazione, Preghiera di Guarigione riduce il tempo di recupero di Parola Sacra: Serenità e Fuoco Sacro riduce il tempo di recupero di Parola Sacra: Castigo di 4 s.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Sacerdote (Sacro)"}
MultiLanguageItemData['it'][183325] = {name = "[q5]Ricordo di X'anshi, Ritorno dell'Arcivescovo Benedictus", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nX'anshi, Ritorno dell'Arcivescovo Benedictus Abilità dell'Incisione Runica\nAl termine di Spirito di Redenzione, si rinasce con una percentuale di salute che varia in base a quanto si è stati efficaci durante Spirito della Redenzione, fino a un massimo del 100%. Dopo essere rinati, non si può beneficiare dell'effetto per 10 min.\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino Boss Esterno: Valinor, la Luce degli Eoni\nRichiede: Sacerdote (Sacro)"}
MultiLanguageItemData['it'][183326] = {name = "[q5]Ricordo del Richiamo Eterno del Vuoto", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRichiamo Eterno del Vuoto Abilità dell'Incisione Runica Circa 1.3 apparenze ogni minuto\nAculeo Mentale e Flagello Mentale hanno una probabilità di evocare un Tentacolo del Vuoto o un Tentacolo Sferzante del Vuoto che canalizza sul bersaglio per 15 s, generando 3 pazzia ogni 1 s.\nIncisione Runica su: Polsi, Mani\nFonte: Bottino Incursione: Il Concilio del Sangue\nRichiede: Sacerdote (Ombra)"}
MultiLanguageItemData['it'][183327] = {name = "[q5]Ricordo del Salmo Alleviante", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSalmo Alleviante Abilità dell'Incisione Runica\nParola d'Ombra: Morte consuma 8 s della durata degli effetti di Parola d'Ombra: Dolore e Tocco Vampirico sul bersaglio, infliggendo istantaneamente quei danni al bersaglio e generando fino a 30 pazzia.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Sacerdote (Ombra)"}
MultiLanguageItemData['it'][183328] = {name = "[q5]Ricordo dello Stratagemma di Talbadar", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nStratagemma di Talbadar Abilità dell'Incisione Runica\nQuando Parola d'Ombra: Dolore, Piaga Divoratrice e Tocco Vampirico sono attivi sullo stesso bersaglio, Detonazione Mentale infligge il 55% di danni aggiuntivi.\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino: Torgast, Torre dei Dannati. Bastioni Superiori, Blocco 3+\nRichiede: Sacerdote (Ombra)"}
MultiLanguageItemData['it'][183329] = {name = "[q5]Ricordo del Prisma d'Ombrofuoco", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPrisma d'Ombrofuoco Abilità dell'Incisione Runica\nDetonazione Mentale e Parola d'Ombra: Morte fanno sì che il tuo Spirito d'Ombra si teletrasporti alle spalle del bersaglio, colpendo fino a 5 nemici vicini e infliggendo [ Plagiamente : [.442 * ([190% of Spell Power])] / [.408 * ([190% of Spell Power])]] danni da ombrofuoco. Ogni volta che si attiva una fenditura, la durata dello Spirito d'Ombra aumenta di 1.0 s.\nIncisione Runica su: Testa, Mani\nFonte: Bottino Spedizione: Mueh'zala\nRichiede: Sacerdote (Ombra)"}
MultiLanguageItemData['it'][183330] = {name = "[q5]Ricordo dell'Essenza di Zannacremisi", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nEssenza di Zannacremisi Abilità dell'Incisione Runica\nLe abilità che forniscono punti combo hanno una probabilità di infettare il bersaglio con Zannacremisi, infliggendo 0 danni da sanguinamento in 6 s e rigenerando salute pari al 50% dei danni inflitti. (Possibilità di Apparire:30%, 200ms di recupero)\nIncisione Runica su: Testa, Spalle, Dito\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Ladro"}
MultiLanguageItemData['it'][183331] = {name = "[q5]Ricordo della Polvere d'Ombra Rinvigorente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nPolvere d'Ombra Rinvigorente Abilità dell'Incisione Runica\nSparizione riduce il tempo di recupero restante delle altre abilità di 20 s.\nIncisione Runica su: Collo, Torso\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Ladro"}
MultiLanguageItemData['it'][183332] = {name = "[q5]Ricordo del Marchio del Maestro Assassino", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\nMarchio del Maestro Assassino Abilità dell'Incisione Runica\nFinché Furtività è attiva e per 4 s dopo che è terminata, la probabilità di critico aumenta del 100%.\nIncisione Runica su: Polsi, Dito\nFonte: Bottino Spedizione: Affronto degli Sfidanti\nRichiede: Ladro"}
MultiLanguageItemData['it'][183333] = {name = "[q5]Ricordo della Piccola Lama Tossica", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPiccola Lama Tossica Abilità dell'Incisione Runica\nAumenta i danni inflitti da Stilettata del 500% e ne azzera il costo in energia.\nIncisione Runica su: Fianchi, Piedi\nFonte: Missione: La Gran Banca\nRichiede: Ladro"}
MultiLanguageItemData['it'][183334] = {name = "[q5]Ricordo del Farabutto Ardito", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFarabutto Ardito Abilità dell'Incisione Runica\nAffondo Venefico aumenta la probabilità di critico dei tuoi veleni del 15% e i suoi colpi critici generano 1 energia.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino Incursione: Il Concilio del Sangue\nRichiede: Ladro (Assassinio)"}
MultiLanguageItemData['it'][183335] = {name = "[q5]Ricordo della Lama Spietata", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nLama Spietata Abilità dell'Incisione Runica\nMutilazione infligge il 45% di danni da sanguinamento aggiuntivi in 8 s.\n\n Aumenta i danni inflitti da Affondo Venefico del 5% per ogni tuo effetto di sanguinamento sul bersaglio.\nIncisione Runica su: Spalle, Mani, Schiena\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Ladro (Assassinio)"}
MultiLanguageItemData['it'][183336] = {name = "[q5]Ricordo della Pezza del Calcavespro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPezza del Calcavespro Abilità dell'Incisione Runica\nIl tempo di recupero restante di Stigma Letale si riduce di 1 s ogni 30 energia consumata.\nIncisione Runica su: Torso, Dito\nFonte: Bottino Spedizione: Evocanebbie\nRichiede: Ladro (Assassinio)"}
MultiLanguageItemData['it'][183337] = {name = "[q5]Ricordo del Fregio di Zoldyck", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFregio di Zoldyck Abilità dell'Incisione Runica\nAumenta del 30% i danni da sanguinamento e da veleno inflitti ai bersagli con meno del 30% di salute restante.\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Ladro (Assassinio)"}
MultiLanguageItemData['it'][183338] = {name = "[q5]Ricordo della Fluidità", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFluidità Abilità dell'Incisione Runica\nScarica d'Adrenalina aumenta i danni inflitti del 8%. Inoltre, fornisce una probabilità che durante Fendenti Furiosi si attivi l'effetto Scarica d'Adrenalina per 3 s.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino Spedizione: Ventunax\nRichiede: Ladro (Fuorilegge)"}
MultiLanguageItemData['it'][183339] = {name = "[q5]Ricordo dello Schioppo Nascosto", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSchioppo Nascosto Abilità dell'Incisione Runica\nQuando Assalto Funesto colpisce una volta aggiuntiva, fornisce una probabilità del 40% che il successivo Colpo di Pistola spari 3 volte aggiuntive.\nIncisione Runica su: Polsi, Mani\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Ladro (Fuorilegge)"}
MultiLanguageItemData['it'][183340] = {name = "[q5]Ricordo dei Vimini di Pelleverde", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVimini di Pelleverde Abilità dell'Incisione Runica\nIn Mezzo agli Occhi ha una probabilità del 20% per punto combo di aumentare i danni inflitti dal successivo Colpo di Pistola del 300%.\nIncisione Runica su: Testa, Fianchi\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Ladro (Fuorilegge)"}
MultiLanguageItemData['it'][183341] = {name = "[q5]Ricordo del Talismano dell'Astuzia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTalismano dell'Astuzia Abilità dell'Incisione Runica\nL'allenamento permette di riconoscere e volgere a proprio vantaggio il naturale flusso del combattimento. Assalto Funesto aumenta gradualmente i danni inflitti fino al 15%. L'effetto massimo dura 12 s prima di dissolversi e iniziare poi un nuovo ciclo.\nIncisione Runica su: Collo, Polsi\nFonte: Bottino Boss Esterno: Mortanis\nRichiede: Ladro (Fuorilegge)"}
MultiLanguageItemData['it'][183342] = {name = "[q5]Ricordo del Frammento d'Anima di Akaari", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFrammento d'Anima di Akaari Abilità dell'Incisione Runica\nDopo aver lanciato Assalto d'Ombra o Colpo Basso, il bersaglio subisce un Assalto d'Ombra dalle ombre dopo 2 s, con un'efficacia del 25%.\nIncisione Runica su: Testa, Collo, Mani\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Ladro (Scaltrezza)"}
MultiLanguageItemData['it'][183343] = {name = "[q5]Ricordo delle Ombre Letali", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nOmbre Letali Abilità dell'Incisione Runica\nSparizione fornisce 5 punti combo e aumenta tutti i danni inflitti del [ Scaltrezza : 20% per 15 s /\n\nAssassinio, Fuorilegge\n15% per 12 s ] (500ms di recupero)\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Ladro"}
MultiLanguageItemData['it'][183344] = {name = "[q5]Ricordo dell'Atto Finale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAtto Finale Abilità dell'Incisione Runica\nSventramento, Perforazione e Polvere Nera aumentano i danni inflitti dalla successiva mossa risolutiva del 25%.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Ladro (Scaltrezza)"}
MultiLanguageItemData['it'][183345] = {name = "[q5]Ricordo del Marcio", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nIl Marcio Abilità dell'Incisione Runica\nDopo aver attivato Simboli di Morte, il successivo lancio di Assalto d'Ombra o [ Lama Tenebrosa / Pugnalata alle Spalle] infligge il 50% di danni aggiuntivi e fornisce 4 punti combo aggiuntivi.\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino Spedizione: Domina Lamatossica\nRichiede: Ladro (Scaltrezza)"}
MultiLanguageItemData['it'][183346] = {name = "[q5]Ricordo del Promemoria Ancestrale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPromemoria Ancestrale Abilità dell'Incisione Runica\nAumenta la durata su se stessi di [ Eroismo / Brama di Sangue] o altri effetti simili di 20.0 s. Inoltre, durante l'effetto la celerità ottenuta aumenta del 10% aggiuntivo.\nIncisione Runica su: Polsi, Dito\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Sciamano"}
MultiLanguageItemData['it'][183347] = {name = "[q5]Ricordo delle Catene della Devastazione", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nCatene della Devastazione Abilità dell'Incisione Runica Istantaneo\nElementale\n Lanciare Catena di Guarigione rende la successiva Catena di Fulmini istantanea e ne aumenta i danni inflitti del 50%. Lanciare Catena di Fulmini rende la successiva Catena di Guarigione istantanea e ne azzera il costo in mana.\n\nPotenziamento, Rigenerazione\n Lanciare Catena di Guarigione rende la successiva Catena di Fulmini istantanea. Lanciare Catena di Fulmini rende la successiva Catena di Guarigione istantanea.\nIncisione Runica su: Collo, Torso\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Sciamano"}
MultiLanguageItemData['it'][183348] = {name = "[q5]Ricordo degli Elementi Profondamente Radicati", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nElementi Profondamente Radicati Abilità dell'Incisione Runica\nPotenziamento\n Lanciare Assalto della Tempesta fornisce una probabilità del 8% di attivare Ascesa per 6.0 s.\n\nElementale\n Lanciare Getto di Lava fornisce una probabilità del 7% di attivare Ascesa per 6.0 s.\n\nRigenerazione\n Lanciare Marea Benefica fornisce una probabilità del 7% di attivare Ascesa per 6.0 s.\nIncisione Runica su: Testa, Spalle, Polsi\nFonte: Missione: La Gran Banca\nRichiede: Sciamano"}
MultiLanguageItemData['it'][183349] = {name = "[q5]Ricordo della Pietra del Tremore Profondo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPietra del Tremore Profondo Abilità dell'Incisione Runica\nL'Elementale della Terra è sempre accompagnato da un Terremoto.\nIncisione Runica su: Fianchi, Piedi, Dito\nFonte: Bottino Spedizione: Eminenth\nRichiede: Sciamano"}
MultiLanguageItemData['it'][183350] = {name = "[q5]Ricordo degli Echi della Grande Separazione", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nEchi della Grande Separazione Abilità dell'Incisione Runica\nQuando si lancia Folgore della Terra, il successivo Terremoto infligge il 120% di danni aggiuntivi.\nIncisione Runica su: Spalle, Mani\nFonte: Bottino Spedizione: Mueh'zala\nRichiede: Sciamano (Elementale)"}
MultiLanguageItemData['it'][183351] = {name = "[q5]Ricordo dell'Equilibrio Elementale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nEquilibrio Elementale Abilità dell'Incisione Runica\nInfliggere danni da fuoco, da gelo e da natura diretti entro 10 s aumenta tutti i danni inflitti del 15% per 10 s. L'effetto può verificarsi solo una volta ogni 30 s.\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Sciamano (Elementale)"}
MultiLanguageItemData['it'][183352] = {name = "[q5]Ricordo della Disfatta Ardente della Spaccacieli", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nDisfatta Ardente della Spaccacieli Abilità dell'Incisione Runica\nI danni periodici critici inflitti da Folgore del Fuoco riducono il tempo di recupero dell' [ Elementale della Tempesta / Elementale del Fuoco] di [ Elementale della Tempesta : 1.0 / 1.0] s. Inoltre, Folgore del Fuoco ha una probabilità di critico aumentata del 50%.\nIncisione Runica su: Torso, Dito\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Sciamano (Elementale)"}
MultiLanguageItemData['it'][183353] = {name = "[q5]Ricordo della Rinascita di Lava dell'Oratore del Vento", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRinascita di Lava dell'Oratore del Vento Abilità dell'Incisione Runica\nQuando si lancia Folgore della Terra, si attiva Eruzione di Lava e i danni inflitti dal successivo Getto di Lava aumentano del 20%.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino Boss Esterno: Valinor, la Luce degli Eoni\nRichiede: Sciamano (Elementale)"}
MultiLanguageItemData['it'][183354] = {name = "[q5]Ricordo dei Venti del Fato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVenti del Fato Abilità dell'Incisione Runica\nPiazzare un Totem della Furia del Vento fornisce una probabilità del 100% di ottenere Arma della Furia del Vento e aumentarne i danni inflitti del 25% per 12 s.\n\n L'effetto può attivarsi solo una volta ogni 1 min.\nIncisione Runica su: Testa, Fianchi, Schiena\nFonte: Bottino Spedizione: Devos, Eletta del Dubbio\nRichiede: Sciamano (Potenziamento)"}
MultiLanguageItemData['it'][183355] = {name = "[q5]Ricordo del Retaggio della Megera del Gelo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRetaggio della Megera del Gelo Abilità dell'Incisione Runica\nConsumare 5 accumuli di Arma del Maelstrom azzera il tempo di recupero di Assalto della Tempesta e aumenta i danni inflitti dal successivo Assalto della Tempesta del 30%.\nIncisione Runica su: Collo, Polsi\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Sciamano (Potenziamento)"}
MultiLanguageItemData['it'][183356] = {name = "[q5]Ricordo degli Attuatori della Lava Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAttuatori della Lava Primordiale Abilità dell'Incisione Runica\nOgni volta che Folgore del Fuoco infligge danni periodici, aumenta i danni inflitti dalla successiva Sferzata Lavica del 12% e riduce il tempo di recupero di Sferzata Lavica di 0.5 s.\nIncisione Runica su: Polsi, Mani\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Sciamano (Potenziamento)"}
MultiLanguageItemData['it'][183357] = {name = "[q5]Ricordo delle Ossa di Lupo del Taumaturgo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nOssa di Lupo del Taumaturgo Abilità dell'Incisione Runica\nAumenta la probabilità di ottenere un accumulo di Arma del Maelstrom del 3%. Ogni volta che si ottiene un accumulo di Arma del Maelstrom, il tempo di recupero di Lupi Spirituali si riduce di 2.0 s.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Sciamano (Potenziamento)"}
MultiLanguageItemData['it'][183358] = {name = "[q5]Ricordo dell'Armonia Terrestre", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nArmonia Terrestre Abilità dell'Incisione Runica\nSe il bersaglio di Scudo di Terra ha meno del 75% della salute massima, le cure fornite da Scudo di Terra aumentano del 150% e Ondata di Cura aggiunge un accumulo di Scudo di Terra al bersaglio, fino a un massimo di 9 accumuli.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Spedizione: Generale Kaal\nRichiede: Sciamano (Rigenerazione)"}
MultiLanguageItemData['it'][183359] = {name = "[q5]Ricordo del Focus Naturale di Jonat", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFocus Naturale di Jonat Abilità dell'Incisione Runica\nOndata di Cura ed Eruzione Benefica aumentano le cure fornite dalla successiva Catena di Guarigione del 20%. Si accumula fino a 5 volte.\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Sciamano (Rigenerazione)"}
MultiLanguageItemData['it'][183360] = {name = "[q5]Ricordo del Nucleo della Marea Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nNucleo della Marea Primordiale Abilità dell'Incisione Runica\nOgni 4 lanci di Marea Benefica, l'effetto di Marea Benefica si applica anche a un altro bersaglio alleato vicino al bersaglio primario.\nIncisione Runica su: Testa, Mani\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Sciamano (Rigenerazione)"}
MultiLanguageItemData['it'][183361] = {name = "[q5]Ricordo del Totem della Marea dello Spiritista", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTotem della Marea dello Spiritista Abilità dell'Incisione Runica\nLanciare il Totem della Marea di Mana riduce il tempo di lancio di Ondata di Cura e Catena di Guarigione del 50% e il costo in mana di Ondata di Cura e Catena di Guarigione del 40% per 10 s.\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino Incursione: Altimor il Predatore\nRichiede: Sciamano (Rigenerazione)"}
MultiLanguageItemData['it'][183362] = {name = "[q5]Ricordo dell'Ira Malefica", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nIra Malefica Abilità dell'Incisione Runica\nEstasi Malefica aumenta i danni inflitti da [ Risucchio d'Anima / Dardo d'Ombra] del 35% per 10 s. Si accumula fino a 3 volte. (100ms di recupero)\nIncisione Runica su: Spalle, Mani\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Stregone (Afflizione)"}
MultiLanguageItemData['it'][183363] = {name = "[q5]Ricordo dell'Agonia Perpetua di Azj'aqir", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAgonia Perpetua di Azj'aqir Abilità dell'Incisione Runica\nAgonia ha una probabilità aggiuntiva del 20% di fornire un frammento d'anima.\nIncisione Runica su: Torso, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Interstizi dei Cuorfreddo, Blocco 3+\nRichiede: Stregone (Afflizione)"}
MultiLanguageItemData['it'][183364] = {name = "[q5]Ricordo dell'Assalto Oscuro di Sacrolash", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAssalto Oscuro di Sacrolash Abilità dell'Incisione Runica\nAumenta i danni inflitti da Corruzione del 25%. Inoltre, ogni volta che infligge danni, la durata di tutte le maledizioni attive sul bersaglio si estende di 2 s.\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Stregone (Afflizione)"}
MultiLanguageItemData['it'][183365] = {name = "[q5]Ricordo dell'Ira della Consunzione", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nIra della Consunzione Abilità dell'Incisione Runica\nCorruzione e Agonia forniscono 1 accumulo ciascuna di Ira della Consunzione quando un bersaglio muore, aumentando tutti i danni periodici inflitti del 6% per 30 s. Si accumula fino a 5 volte.\nIncisione Runica su: Piedi, Schiena\nFonte: Bottino Spedizione: Ventunax\nRichiede: Stregone (Afflizione)"}
MultiLanguageItemData['it'][183366] = {name = "[q5]Ricordo dell'Artiglio di Endereth", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nArtiglio di Endereth Abilità dell'Incisione Runica\nAumenta la velocità di canalizzazione di Risucchio di Vita del 100% e ne aumenta la velocità di rigenerazione della salute del 100%.\nIncisione Runica su: Fianchi, Piedi\nFonte: Missione: La Gran Banca\nRichiede: Stregone"}
MultiLanguageItemData['it'][183367] = {name = "[q5]Ricordo della Sinergia Demoniaca", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nReliquia della Sinergia Demoniaca Abilità dell'Incisione Runica Circa 3 apparenze ogni minuto\nI danni inflitti da te e dal tuo servitore principale hanno una probabilità di aumentare i danni inflitti dall'altro, ossia rispettivamente dal servitore o da te, del [ Demonologia : 15% /\n\nAfflizione, Distruzione\n10% ] per 15 s.\nIncisione Runica su: Testa, Spalle, Schiena\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Stregone"}
MultiLanguageItemData['it'][183368] = {name = "[q5]Ricordo dei Pilastri del Portale Oscuro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nPilastri del Portale Oscuro Abilità dell'Incisione Runica\nVarco Demoniaco è istantaneo e il primo uso del proprio varco non ne attiva il tempo di recupero.\n\n In aggiunta, l'energia fatua si scatena sui nemici attraverso cui si passa, respingendoli indietro.\nIncisione Runica su: Collo, Torso\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Stregone\nModifies Cast Time -100%:\nVarco Demoniaco"}
MultiLanguageItemData['it'][183369] = {name = "[q5]Ricordo del Sigillo di Wilfred dell'Evocazione Superiore", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\nSigillo di Wilfred dell'Evocazione Superiore Abilità dell'Incisione Runica\nDistruzione\n Ogni frammento d'anima consumato riduce il tempo di recupero di Evocazione: Infernale di 1.5 s.\n\nAfflizione\n Ogni frammento d'anima consumato riduce il tempo di recupero di Evocazione: Lumenero di 2.0 s.\n\nDemonologia\n Ogni frammento d'anima consumato riduce il tempo di recupero di Evocazione: Tiranno Demoniaco di 0.6 s.\nIncisione Runica su: Polsi, Dito\nFonte: Bottino Spedizione: I Manalampo\nRichiede: Stregone"}
MultiLanguageItemData['it'][183370] = {name = "[q5]Ricordo del Nucleo Ardente della Pena del Ragno", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nNucleo Ardente della Pena del Ragno Abilità dell'Incisione Runica\nDardo d'Ombra aumenta i danni inflitti da Dardo Demoniaco del 15%. Si accumula fino a 4 volte. Dura 20 s.\nIncisione Runica su: Polsi, Mani\nFonte: Bottino Incursione: Ingegnere Xy'mox\nRichiede: Stregone (Demonologia)"}
MultiLanguageItemData['it'][183371] = {name = "[q5]Ricordo delle Forze dell'Incubo Cornuto", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nForze dell'Incubo Cornuto Abilità dell'Incisione Runica\nMano di Gul'dan ha una probabilità del 15% di essere lanciata una seconda volta sul bersaglio senza alcun costo.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino: Torgast, Torre dei Dannati. Stanze delle Fratture, Blocco 3+\nRichiede: Stregone (Demonologia)"}
MultiLanguageItemData['it'][183372] = {name = "[q5]Ricordo dell'Evocazione del Terrore dell'Inquisitore Tetro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nEvocazione del Terrore dell'Inquisitore Tetro Abilità dell'Incisione Runica\nOgni frammento d'anima consumato da Mano di Gul'dan aumenta i danni inflitti dal successivo Richiamo Inseguitore Maligno del 4%.\nIncisione Runica su: Collo, Polsi\nFonte: Bottino: Torgast, Torre dei Dannati. Bastioni Superiori, Blocco 3+\nRichiede: Stregone (Demonologia)"}
MultiLanguageItemData['it'][183373] = {name = "[q5]Ricordo del Potenziale Implosivo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPotenziale Implosivo Abilità dell'Incisione Runica\nImplosione aumenta la celerità del 1% per 12 s per ogni Imp esploso. Se infligge danni ad almeno 3 bersagli, la celerità aumenta del 5% per Imp. Al massimo 15 Imp esplosi possono fornire il beneficio.\nIncisione Runica su: Testa, Fianchi, Mani\nFonte: Bottino Spedizione: Chirurgo Cucicarne\nRichiede: Stregone (Demonologia)"}
MultiLanguageItemData['it'][183374] = {name = "[q5]Ricordo delle Braci degli Azj'aqir", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBraci degli Azj'aqir Abilità dell'Incisione Runica\nAumenta le cariche di Conflagrazione di 1 e ne riduce il tempo di ricarica di 3.0 s.\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Stregone (Distruzione)"}
MultiLanguageItemData['it'][183375] = {name = "[q5]Ricordo delle Braci della Divisa del Diabolico", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBraci della Divisa del Diabolico Abilità dell'Incisione Runica\nIncenerimento fornisce il 100% aggiuntivo di schegge di frammento d'anima.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Spedizione: Kul'tharok\nRichiede: Stregone (Distruzione)"}
MultiLanguageItemData['it'][183376] = {name = "[q5]Ricordo della Follia degli Azj'aqir", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFollia degli Azj'aqir Abilità dell'Incisione Runica\nDardo del Caos aumenta i danni inflitti da Dardo del Caos del 25% e ne riduce il tempo di lancio del 20% per 4 s.\nIncisione Runica su: Testa, Mani\nFonte: Bottino Boss Esterno: Nurgash Tuttomuco\nRichiede: Stregone (Distruzione)"}
MultiLanguageItemData['it'][183377] = {name = "[q5]Ricordo di Odr, Scialle degli Ymirjar", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nOdr, Scialle degli Ymirjar Abilità dell'Incisione Runica\nI nemici marchiati da Calamità subiscono il 25% di danni aggiuntivi dai tuoi incantesimi a bersaglio singolo.\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Stregone (Distruzione)"}
MultiLanguageItemData['it'][183378] = {name = "[q5]Ricordo del Saltatore", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\nAcquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\n\n\nSaltatore Abilità dell'Incisione Runica\nAumenta le cariche di Balzo Eroico di 2.\nIncisione Runica su: Fianchi, Piedi\nFonte: Acquistato con i Punti Onore dal Fornitore Zo'kruul. Devi aver sbloccato Incisione Runica per acquistare questo ricordo.\nRichiede: Guerriero"}
MultiLanguageItemData['it'][183379] = {name = "[q5]Ricordo dello Specchio Deformato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSpecchio Deformato Abilità dell'Incisione Runica\nAumenta la durata di Rifletti Incantesimo del 60%. Il suo effetto si applica anche all'alleato più vicino. (1s di recupero)\nIncisione Runica su: Collo, Torso\nFonte: Missione: La Gran Banca\nRichiede: Guerriero"}
MultiLanguageItemData['it'][183380] = {name = "[q5]Ricordo del Riverbero Sismico", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRiverbero Sismico Abilità dell'Incisione Runica\nFuria\n Se Turbine colpisce 3 o più nemici, li colpisce 1 volta aggiuntiva, infliggendo il 100% dei danni.\n\nArmi\n Se Turbine colpisce 3 o più nemici, li colpisce 1 volta aggiuntiva, infliggendo il 80% dei danni.\n\nProtezione\n Se Turbine o Rivincita colpisce 3 o più nemici, li colpisce 1 volta aggiuntiva, infliggendo il 75% dei danni.\nIncisione Runica su: Testa, Spalle, Piedi\nFonte: Bottino Spedizione: Halkias, Mastodonte Macchiato dal Peccato\nRichiede: Guerriero"}
MultiLanguageItemData['it'][183381] = {name = "[q5]Ricordo dell'Anello con Sigillo dei Re Tormentati", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAnello con Sigillo dei Re Tormentati Abilità dell'Incisione Runica\nLanciare Tempesta di Lame, Avventatezza o Avatar lancia una a caso delle altre due abilità a efficacia ridotta.\nIncisione Runica su: Polsi, Dito\nFonte: Bottino Incursione: Generali della Legione di Pietra\nRichiede: Guerriero"}
MultiLanguageItemData['it'][183382] = {name = "[q5]Ricordo del Signore della Battaglia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSignore della Battaglia Abilità dell'Incisione Runica\nDominazione ha una probabilità del 40% di azzerare il tempo di recupero di Assalto Mortale e di ridurre il costo in rabbia del successivo Assalto Mortale di 15. (Possibilità di Apparire:40%, 100ms di recupero)\nIncisione Runica su: Collo, Polsi\nFonte: Bottino: Torgast, Torre dei Dannati. Forge dell'Anima, Blocco 3+\nRichiede: Guerriero (Armi)"}
MultiLanguageItemData['it'][183383] = {name = "[q5]Ricordo del Colpo Duraturo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nColpo Duraturo Abilità dell'Incisione Runica\nAssalto Mortale ha una probabilità del 25% di attivare l'effetto di Colpo del Colosso sul bersaglio per 6 s. (Possibilità di Apparire:25%)\nIncisione Runica su: Testa, Fianchi\nFonte: Bottino: Torgast, Torre dei Dannati. Sala di Skoldus, Blocco 3+\nRichiede: Guerriero (Armi)"}
MultiLanguageItemData['it'][183384] = {name = "[q5]Ricordo dello Sfruttatore", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSfruttatore Abilità dell'Incisione Runica\nEsecuzione aumenta i danni inflitti al bersaglio dal tuo successivo Assalto Mortale del 50%. Si accumula fino a 2 volte.\nIncisione Runica su: Spalle, Dito\nFonte: Bottino Incursione: Sire Denathrius\nRichiede: Guerriero (Armi)"}
MultiLanguageItemData['it'][183385] = {name = "[q5]Ricordo dello Squilibrato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSquilibrato Abilità dell'Incisione Runica\nMentre Tempesta di Lame è attiva, automaticamente vengono lanciati un totale di 2 Assalti Mortali contro nemici vicini casuali.\nIncisione Runica su: Polsi, Mani, Dito\nFonte: Bottino Spedizione: Xav l'Immortale\nRichiede: Guerriero (Armi)"}
MultiLanguageItemData['it'][183386] = {name = "[q5]Ricordo della Cadenza di Fujieda", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nCadenza di Fujieda Abilità dell'Incisione Runica\nSete di Sangue aumenta la celerità del 1% per 12 s. Si accumula fino a 5 volte. (500ms di recupero)\nIncisione Runica su: Fianchi, Gambe\nFonte: Bottino Boss Esterno: Mortanis\nRichiede: Guerriero (Furia)"}
MultiLanguageItemData['it'][183387] = {name = "[q5]Ricordo del Portatore di Morte", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPortatore di Morte Abilità dell'Incisione Runica\nScatto d'Ira ha una probabilità del 30% di attivare l'effetto di Spezzassedio sul bersaglio per 6 s. (Possibilità di Apparire:30%)\nIncisione Runica su: Gambe, Schiena\nFonte: Bottino Spedizione: Amarth, il Mietitore\nRichiede: Guerriero (Furia)"}
MultiLanguageItemData['it'][183388] = {name = "[q5]Ricordo della Difesa Sprezzante", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nDifesa Sprezzante Abilità dell'Incisione Runica\nI colpi di Scatto d'Ira hanno una probabilità del 20% di ridurre il tempo di recupero restante di Avventatezza e Rigenerazione Furente di 1 s.\nIncisione Runica su: Testa, Fianchi, Mani\nFonte: Bottino: Torgast, Torre dei Dannati. Mort'regar, Blocco 3+\nRichiede: Guerriero (Furia)"}
MultiLanguageItemData['it'][183389] = {name = "[q5]Ricordo della Volontà del Berserker", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVolontà del Berserker Abilità dell'Incisione Runica\nQuando Avventatezza termina, la probabilità di critico aumenta del 7% per 12 s. Colpo Furente rinnova la durata dell'effetto.\nIncisione Runica su: Torso, Schiena\nFonte: Bottino Incursione: Picchiapoltiglia\nRichiede: Guerriero (Furia)"}
MultiLanguageItemData['it'][183390] = {name = "[q5]Ricordo della Rappresaglia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRappresaglia Abilità dell'Incisione Runica\nCarica e Intervento attivano Scudo Saldo per 4 s, Rivincita! e generano 20 rabbia. (100ms di recupero)\nIncisione Runica su: Gambe, Piedi\nFonte: Bottino: Torgast, Torre dei Dannati. Bastioni Superiori, Blocco 3+\nRichiede: Guerriero (Protezione)"}
MultiLanguageItemData['it'][183391] = {name = "[q5]Ricordo del Muro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nMuro Abilità dell'Incisione Runica\nColpo di Scudo genera 5 rabbia aggiuntiva e riduce il tempo di recupero restante di Muro di Scudi di 5 s.\nIncisione Runica su: Spalle, Schiena\nFonte: Bottino Incursione: Distruttore Famelico\nRichiede: Guerriero (Protezione)"}
MultiLanguageItemData['it'][183392] = {name = "[q5]Ricordo dello Spaccatuono", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSpaccatuono Abilità dell'Incisione Runica\nOgni nemico colpito da Schianto del Tuono riduce il tempo di recupero restante di Urlo Demoralizzante di 1.5 s, fino a un massimo di 4.5 s.\nIncisione Runica su: Piedi, Mani\nFonte: Bottino Spedizione: Orifrion\nRichiede: Guerriero (Protezione)"}
