MultiLanguageItemData['it'][183798] = {name = "[q4]Imbracatura da Battaglia di Silessa", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare il Gargon da Battaglia Silessa come cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Silessa ha combattuto con coraggio al fianco del proprio padrone nella grande incursione della Luce. Dopo la battaglia, il suo padrone l'ha messa a guardia di una cripta molto preziosa.\"\nCongrega:\nVenthyr\nZona:\nRevendreth"}
MultiLanguageItemData['it'][183799] = {name = "Catalizzatore Mutevole", additional_info = "Etereo\nLa Fauce\nSi vincola alla raccolta\nUnico\nDurata: 10 min (tempo reale)\n[q2]Usa: Piazza un Catalizzatore Mutevole che, quando usato, fornisce l'abilità Cambiamento d'Essenza sul campo di battaglia.\n\nUtilizzabile nei Campi Macchiati d'Anime o nel Tugurio del Torturatore della Fauce.\nRichiede dal livello 60 al 60 ( 60)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][183800] = {name = "[q4]Falenarden Ambrata", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"La brillante tonalità arancione della Falenarden Ambrata segnala ai predatori che è pericolosa da mangiare. Consumare una di queste creature farebbe cadere il predatore in un sonno senza sogni per anni.\"\nBottino:\nRifornimenti della Caccia Selvaggia\nZona:\nSelvarden"}
MultiLanguageItemData['it'][183801] = {name = "[q4]Alasalda Vivace", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeMarasmio\n- Riverito\n\n\n[q]\"Queste piccole falene verdi sono molto amichevoli. Si divertono particolarmente a farsi spazzolare vigorosamente la peluria sulla testa. Sono anche appassionate di musica e poesia.\"\nMercante:\nCortinario\nZona:\nSelvarden"}
MultiLanguageItemData['it'][183802] = {name = "Ricordo dell'Indegno", additional_info = "Oggetto di missione\n[q]\"Un piccolo pezzo dei ricordi di Lysonia durante il tempo trascorso tra gli Indegni.\""}
