MultiLanguageItemData['it'][184016] = {name = "[q4]Ala di Furtivo", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+28 [Agilità o Forza]\n[q2]Usa: Diventa il Predatore Furtivo per 10 s, aumentando la velocità di movimento di 69 e saltando sul successivo nemico entro 8 m, infliggendo 3874 danni fisici. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184017] = {name = "[q4]Guinzaglio di Bargast", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+28 [Agilità o Forza]\n[q2]Usa: Stabilisce un Vincolo del Predatore con un bersaglio alleato per 30 s. Il 25% dei danni subiti vengono reindirizzati sull'alleato vincolato, fino a un massimo di [ 11389 * (1 + Versatilità)] danni totali reindirizzati. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184018] = {name = "[q4]Cuore di Al'ar Spezzato", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+28 [Agilità o Forza]\n[q2]Equipaggia: Assorbe fino a 10234 danni subiti da un attacco letale. Quando l'effetto si attiva, esplode in una fiammata, infliggendo [ 2433 * (1 + Versatilità)] danni da fuoco agli alleati e ai nemici vicini e rigenerando [ 7025 * (1 + Versatilità)] salute.\n\n L'effetto può attivarsi solo una volta ogni 8 min.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184019] = {name = "[q4]Brucianima", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+28 Intelletto\n[q2]Usa: Attiva Brucianima, sacrificando fino a 2157 salute in 15 s per potenziare Impeto Fiammeggiante.\n\n Rilanciare Brucianima attiva Impeto Fiammeggiante, infliggendo [ 1541 * (1 + Versatilità)] danni da fuoco suddivisi tra i nemici entro un cono di 40 m e fino al 40% di danni aggiuntivi in base alla durata di Brucianima.\n I danni aumentano per ogni nemico colpito, fino a un massimo di 5 nemici. (Tempo di recupero di 1 min)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184020] = {name = "[q4]Ciuffo di Piumaggio Infuocato", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+28 Intelletto\n[q2]Usa: Infondi il tuo alleato con un ciuffo di piume di fenice, curandolo di [ 5199 * (1 + Versatilità)] dopo 6 s, quantità aumentata di massimo il 25% in base alla salute mancante al bersaglio. Se l'alleato subisce danni letali, l'effetto si attiva istantaneamente. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184021] = {name = "[q4]Glifo dell'Assimilazione", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+28 Intelletto\n[q2]Usa: Infligge 1786 danni da arcano a un nemico in 10 s.\n\n Se il bersaglio muore mentre è affetto dal Glifo dell'Assimilazione, il tuo indice di maestria aumenta di 160 per 2 volte la durata restante del glifo. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184022] = {name = "[q4]Infusione Tisica", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+28 Intelletto\n[q2]Equipaggia: Lanciare un incantesimo d'attacco permette alla successiva cura a bersaglio singolo di aumentare il ritorno vitale di 138 per 10 s. L'effetto può verificarsi solo una volta ogni 30 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184023] = {name = "[q4]Punta Ingorda", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+28 Forza\n[q2]Equipaggia: Le abilità d'attacco hanno un'alta probabilità di infliggere 116 danni fisici, rigenerando salute pari al 300% dei danni inflitti. Se l'effetto fornisce delle sovracure, infligge [ 98 * 5 * (1 + Versatilità)] danni fisici suddivisi tra i nemici vicini in 15 s, ma sopprimendo l'effetto di cura.\n\n I danni aumentano per ogni nemico colpito, fino a un massimo di 5 nemici.\nPrezzo di vendita:"}
