MultiLanguageItemData['it'][184613] = {name = "[q2]Essenza del Calcavarchi Intrappolata", additional_info = "Potenziamento Permanente: La Fauce\nSi vincola alla raccolta\nUnico\n[q2]Usa: Attiva un trasporto tramite le Pietre del Varco Caotiche che possono essere trovate nella Fauce.\nRichiede che Ve'nari abbia di te un'opinione Ansiosa o superiore.\n[q]\"Un pezzo di anima di un Giurafauce, intrappolata nella pietra vetrosa, che inganna le Pietre del Varco Caotiche in modo che consentano l'accesso al possessore.\""}
MultiLanguageItemData['it'][184614] = {name = "Essenza della Miseria", additional_info = "Oggetto di missione"}
MultiLanguageItemData['it'][184615] = {name = "[q2]Tasche Extradimensionali", additional_info = "Potenziamento Permanente: Torgast\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce spazio aggiuntivo quando si è a Torgast, permettendo di trovare gli Armamenti di Obleron in grande quantità.\nRichiede che Ve'nari abbia di te un'opinione Ansiosa o superiore.\n[q]\"Queste tasche sono notevolmente più grandi all'interno di quanto sembrino.\""}
MultiLanguageItemData['it'][184617] = {name = "[q3]Ciondolo dell'Anzianità di Servizio", additional_info = "Potenziamento Permanente: Torgast\nSi vincola alla raccolta\nUnico\n[q2]Usa: A Torgast, i mercanti Alienatori hanno una possibilità di fornirti un'opzione pregiata.\nRichiede che Ve'nari abbia di te un'opinione Incerta o superiore.\n[q]\"Il ciondolo che una volta indicava lo status di Ve'nari nel Cartello Ve. Ora appartiene a te.\""}
MultiLanguageItemData['it'][184618] = {name = "[q4]Grado Fregio: Acquisizionista", additional_info = "Potenziamento Permanente: Torgast\nSi vincola alla raccolta\nUnico\n[q2]Usa: A Torgast, i mercanti Alienatori hanno una possibilità di fornirti un'opzione rara.\nRichiede che Ve'nari abbia di te un'opinione Cordiale o superiore.\n[q]\"Questo ti certifica come un responsabile del Cartello Ve. Non lo sei assolutamente, ma loro non lo sanno.\""}
MultiLanguageItemData['it'][184619] = {name = "[q4]Lente del Talismano Inusuale", additional_info = "Potenziamento Permanente: Torgast\nSi vincola alla raccolta\nUnico\n[q2]Usa: A Torgast, i mercanti Alienatori hanno una possibilità di fornirti delle Scorte di Animum scontate.\nRichiede che Ve'nari abbia di te un'opinione Cordiale o superiore.\n[q]\"Ve'nari ha infuso questa lente da orefice con un incantesimo di soggiogazione, così che gli Alienatori si sentano indotti a offrirti degli affari speciali.\""}
MultiLanguageItemData['it'][184620] = {name = "[q2]Ricettacolo degli Spiriti Sfortunati", additional_info = "Potenziamento Permanente: Torgast\nSi vincola alla raccolta\nUnico\n[q2]Usa: A Torgast, la prima morte non viene conteggiata.\nRichiede che Ve'nari abbia di te un'opinione Ansiosa o superiore.\n[q]\"Una magia pericolosa vincola il destino di chiunque possegga questo ricettacolo con lo spirito contenuto all'interno.\""}
MultiLanguageItemData['it'][184621] = {name = "[q4]Prisma della Fortuna Rituale", additional_info = "Potenziamento Permanente: Torgast\nSi vincola alla raccolta\nUnico\n[q2]Usa: A Torgast, la probabilità di ottenere Poteri d'Animum epici è aumentata in modo permanente.\nRichiede che Ve'nari abbia di te un'opinione Ambivalente o superiore.\n[q]\"Ve'nari ha inciso su questo cristallo dei glifi che si dice proteggano contro i capricci del destino.\""}
