MultiLanguageItemData['it'][184649] = {name = "[q2]Cannone dei Rattifauce", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Lancia un Rattofauce esplosivo sul bersaglio, infliggendo ([Total Health] / 10) danni da ombrofuoco a tutti i nemici entro 8 m e uccidendo il Rattofauce. Utilizzabile solo a Torgast. (5 Min Recupero)\n[q]\"Un'arma con una canna estremamente grossa, costruita per sparare i ratti che chiamano Torgast casa contro altre creature ad alta velocità.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184650] = {name = "[q4]Progresso della Campagna dell'Avventura", additional_info = "[q]\"Questa sfida porta ad avventure aggiuntive con ricompense migliori.\""}
MultiLanguageItemData['it'][184651] = {name = "Miasma Toccato dalla Fauce", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti circonda di un miasma malato, infliggendo ([Total Health] / 5) danni a qualsiasi Rattofauce entro 15 m ogni 1 s per 30 min. Utilizzabile solo a Torgast. (5 Min Recupero)\nRichiede che Ve'nari abbia di te un'opinione Incerta o superiore.\n[q]\"Una fiala fetida di gas, sostanza particolarmente potente contro i Rattifauce onnipresenti.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184652] = {name = "[q4]Instillatore Fantasmatico", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Consuma 100 Fantaplasma, usando l'energia creata dalla sostanza per potenziarti per 30 min. Utilizzabile solo a Torgast. (15 Min Recupero)\nRichiede che Ve'nari abbia di te un'opinione Ambivalente o superiore.\n[q]\"Si dice che questo dispositivo consumi il Fantaplasma per alimentare il tuo potere per un tempo limitato. Il dispositivo è riutilizzabile, ma il Fantaplasma consumato viene distrutto nel processo.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][184653] = {name = "[q3]Catena Levitante Animata", additional_info = "Potenziamento Permanente: La Fauce\nSi vincola alla raccolta\nUnico\n[q2]Usa: Vincola il segmento di catena alla tua volontà, permettendoti di indirizzarla verso alcuni luoghi vicini.\nRichiede che Ve'nari abbia di te un'opinione Incerta o superiore.\n[q]\"Questo frammento della catena magica è stato recuperato da un prigioniero indifeso del Carceriere, perduto nella Fauce. Contiene ancora parte del suo potere.\""}
