MultiLanguageItemData['it'][184662] = {name = "Cella d'Animum Requisita", additional_info = "Torgast, Torre dei Dannati\nSi vincola alla raccolta\n[q2]Usa: Rivela una Cella d'Animum Saccheggiata, permettendo a te e ai tuoi alleati di selezionare un potere aggiuntivo.\n[q]\"Questa Cella d'Animum viene offerta come parte di un accordo speciale.\""}
