MultiLanguageItemData['it'][186424] = {name = "[q4]Scheggia dell'Egida di Annhylde", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+42 [Agilità o Forza]\n[q2]Usa: L'Egida di Annhylde fornisce protezione, riducendo i danni subiti dai nemici frontali di 2015 per 8 s.\n\n Se l'Egida assorbe almeno 7052 danni subiti, si sovraccarica ed espelle il potere condensato, infliggendo 1123 danni da sacro a tutti i nemici frontali prima di terminare. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186425] = {name = "[q4]Parola del Richiamo Scarabocchiata", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+42 Intelletto\n[q2]Usa: Riduce il tempo di recupero restante di un incantesimo di cura appropriato di 4 s.\n\nValido solo per le specializzazioni da guaritore. (1 Min Recupero)\nPrezzo di vendita:"}
