MultiLanguageItemData['it'][186565] = {name = "[q5]Ricordo del Trasferimento Dilagante", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nTrasferimento Dilagante Abilità dell'Incisione Runica Istantaneo\nAumenta la forza ottenuta da Dovere della Morte del 3% e ne aumenta la durata di 2 s. Quando ci si trova all'interno del proprio Dovere della Morte, la generazione di potenza runica aumenta del 20%.\nIncisione Runica su: Torso, Fianchi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cavaliere della Morte"}
MultiLanguageItemData['it'][186566] = {name = "[q5]Ricordo della Sentenza Finale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSentenza Finale Abilità dell'Incisione Runica Istantaneo\nQuando Incatenamento Immeritevoli viene applicato a un nemico, fornisce istantaneamente una runa e aumenta i danni inflitti del 4%, fino a un massimo del 20% per 15 s.\nIncisione Runica su: Testa, Spalle, Schiena\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cavaliere della Morte"}
MultiLanguageItemData['it'][186567] = {name = "[q5]Ricordo della Fame Insaziabile", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFame Insaziabile Abilità dell'Incisione Runica Istantaneo\nQuando Nebbia Sciamante termina, infligge ([86.42% of Attack Power]) danni da ombra a 5 nemici vicini, curandoti del 25% dei danni inflitti. I danni aumentano del 2% ogni 1 potenza runica consumata mentre Nebbia Sciamante era attiva.\nIncisione Runica su: Gambe, Piedi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cavaliere della Morte"}
MultiLanguageItemData['it'][186568] = {name = "[q5]Ricordo della Frenesia dell'Abominio", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFrenesia dell'Abominio Abilità dell'Incisione Runica Istantaneo\nAumenta la durata di Arto di Abominio di 4 s e la frequenza di ottenimento di [ Sangue : Scudo d'Ossa / Gelo : Brina / Empietà : Corruzione Runica ] di 2 s. La prima volta che un nemico viene danneggiato da Arto di Abominio, subisce il 20% di danni aggiuntivi da te per 12 s. (20s di recupero)\nIncisione Runica su: Piedi, Polsi, Mani\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cavaliere della Morte"}
MultiLanguageItemData['it'][186569] = {name = "Nido di Pungitore Arrabbiato", additional_info = "Oggetto di missione\n[q2]Usa: Lancia il nido su un Alfiere, spezzandone la concentrazione e rendendolo vulnerabile agli attacchi. (15 S Recupero)"}
MultiLanguageItemData['it'][186570] = {name = "[q5]Ricordo della Gloria", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nGloria Abilità dell'Incisione Runica Istantaneo\nLo Stendardo del Conquistatore potenzia 1 alleato aggiuntivo e ogni [ Armi : 20 ] [ Furia : 25 /\n\nProtezione\n10 ] rabbia consumata mentre è attivo aumenta la durata dello stendardo di 0.5 s.\nIncisione Runica su: Torso, Fianchi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Guerriero"}
MultiLanguageItemData['it'][186572] = {name = "[q5]Ricordo dell'Impeto Peccaminoso", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nImpeto Peccaminoso Abilità dell'Incisione Runica Istantaneo\nCondanna estende la durata di [ Armi : Colpo del Colosso di 1.5 s ] [ Furia : Avventatezza di 2.0 s /\n\nProtezione\nAvatar di 2.5 s ] (500ms di recupero)\nIncisione Runica su: Testa, Collo, Spalle\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Guerriero"}
MultiLanguageItemData['it'][186573] = {name = "[q2]Mappa di Difesa", additional_info = "Si vincola alla raccolta\nDurata: 3 giorni (tempo reale)\nQuesto oggetto avvia una missione\n[q]\"Una mappa con indicate tutte le difese magiche del Forte della Perdizione.\""}
MultiLanguageItemData['it'][186576] = {name = "[q5]Ricordo della Furia della Natura", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFuria della Natura Abilità dell'Incisione Runica Istantaneo\nAumenta la durata di Scossa d'Assestamento Antica di 3 s. Inoltre, i nemici colpiti subiscono [([13.83% of Attack Power])o * 3] danni da natura in 6 s. Si accumula fino a 6 volte.\nIncisione Runica su: Polsi, Mani, Schiena\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Guerriero"}
MultiLanguageItemData['it'][186577] = {name = "[q5]Ricordo dello Sciame Sfrenato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSciame Sfrenato Abilità dell'Incisione Runica Istantaneo\nSciame Adattivo ha una probabilità del 60% di suddividersi in due Sciami Adattivi ogni volta che salta.\nIncisione Runica su: Torso, Polsi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega."}
