MultiLanguageItemData['it'][186637] = {name = "[q4]Meccaliante di Tazavesh", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli Alienatori di ogni tipo usano questi alianti per spostarsi a Tazavesh e dintorni, nonché per trasportare i loro beni.\"\nImpresa:\nPer finta con grinta\nCategoria:\nSpedizioni di Shadowlands"}
MultiLanguageItemData['it'][186638] = {name = "[q4]Meccaliante del Maestro del Cartello", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Solo i capi dei cartelli più ricchi possono permettersi i metalli necessari a creare il Meccaliante del Maestro del Cartello.\"\nBottino:\nSo'leah\nZona:\nTazavesh, il Bazar Celato"}
MultiLanguageItemData['it'][186639] = {name = "[q4]Meccaliante dell'Amministratore Xy", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il Cartello Xy opera con diverse valute, ma per la sua cerchia più stretta nessuna di esse è preziosa quanto la lealtà.\"\nFonte:\n[OMISSIS]"}
MultiLanguageItemData['it'][186640] = {name = "[q4]Meccaliante del Vandalo", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un raro aliante personalizzato usato perlopiù per raduni clandestini. La sua silenziosità lo rende quasi impossibile da rilevare, diventando lo strumento preferito di chi agisce tra le ombre.\"\nFazione:\nVandali della Manaforgia\nFama:\n8\nZona:\nPresidio Ombrale"}
MultiLanguageItemData['it'][186641] = {name = "[q4]Bardatura del Mazzuolatore Addomesticato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Quando si tratta di addomesticare i divoratori, tutto ciò che serve è un po' d'Animum e tanta pazienza. Oltre a una miriade di pozioni curative.\"\nBottino:\nRifornimenti del Codice degli Archivisti\nZona:\nKorthia"}
MultiLanguageItemData['it'][186642] = {name = "[q4]Redini della Vendetta", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il giorno in cui Arthas le tolse la vita, Sylvanas perse una parte di sé e l'oscurità crebbe in lei colmandone il vuoto.\"\nBottino:\nDama Sylvanas Ventolesto\nZona:\nSanctum del Dominio\nDifficoltà:\nMitica"}
MultiLanguageItemData['it'][186643] = {name = "[q4]Redini dell'Unicorno Girovago", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un animale curioso e inquisitorio che non vuole far preoccupare il suo padrone, ma si distrae facilmente, specialmente con tutte le nuove cose da vedere a Korthia.\"\nZona:\nKorthia"}
MultiLanguageItemData['it'][186644] = {name = "[q4]Pellescheggia di Berillo", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questi pellescheggia si nascondono facilmente nel sottobosco. È raro trovarne uno addomesticato.\"\nBottino:\nForniture della Marcia della Morte\nZona:\nKorthia"}
MultiLanguageItemData['it'][186645] = {name = "[q4]Pellescheggia Cremisi", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Quando Korthia venne trascinata nella Fauce, solo poche specie coriacee sopravvissero.\"\nBottino:\nMalpantano\nZona:\nKorthia"}
MultiLanguageItemData['it'][186646] = {name = "[q4]Zampaoscura", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Zampaoscura, un pellescheggia anziano, era relativamente amichevole e mansueto con gli abitanti di Korthia. Si credeva fosse andato perduto a causa della calamità.\"\nZona:\nKorthia"}
MultiLanguageItemData['it'][186647] = {name = "[q4]Pellescheggia d'Ambra", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeMarcia della Morte\n- Riverito\n\n\n[q]\"I colori accesi della fauna di Korthia indicano che hanno pochi predatori naturali oppure che sono abbastanza resistenti da sapersi difendere.\"\nMercante:\nDuchessa Mynx\nZona:\nKorthia\nFazione:\nMarcia della Morte - Riverito\nCosto:\n5.000"}
MultiLanguageItemData['it'][186648] = {name = "[q4]Alafina Planante", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeCodice degli Archivisti\n- Livello 6\n\n\n[q]\"La pelle dell'alafina è leggera, in moda da permettergli di volare, ma è anche piuttosto resistente, affinché possa sopravvivere all'entrata nella Fauce.\"\nMercante:\nArchivista Roh-Suir\nZona:\nKorthia\nFazione:\nCodice degli Archivisti - Livello 6\nCosto:\n5.000"}
MultiLanguageItemData['it'][186649] = {name = "[q4]Alafina Audace", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli alafina di solito stanno alla larga dalle altre specie di Korthia, ma col un po' di tempo e tanta pazienza, anch'essi possono essere addomesticati.\"\nBottino:\nForniture della Marcia della Morte\nZona:\nKorthia"}
MultiLanguageItemData['it'][186650] = {name = "[q3]Forniture della Marcia della Morte", additional_info = "[q7]Si vincola alla Brigata\nUnico\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186651] = {name = "[q4]Alafina di Albascura", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli alafina sono presenti in tutta Korthia e nidificano sulle colline più elevate e sugli alberi.\"\nZona:\nKorthia"}
MultiLanguageItemData['it'][186652] = {name = "[q4]Alafina Granato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Una tempo, Korthia era famosa per i suoi fiori dal colore rosso acceso. Diverse specie erano solito consumarli o rotolarcisi sopra, assumendo così una colorazione rossa brillante.\"\nBottino:\nReliwik l'Insolente\nZona:\nKorthia"}
MultiLanguageItemData['it'][186653] = {name = "[q4]Bracciale di Hrestimorak", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Hrestimorak è tristemente noto per aver tradito la sua gente, cercando sempre più potere. Affrontando la dannazione nella Fauce, ha cercato di sopraffare il Carceriere... Un atto folle che gli è costato un'eternità di tormenti.\"\nImpresa:\nGloria dell'incursore dominante\nZona:\nSanctum del Dominio"}
MultiLanguageItemData['it'][186654] = {name = "[q4]Braccialetto di Salaranga", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Salaranga era la più astuta dei suoi simili e si nascose negli Antri delle Bestie. Colpì l'Esiliato con un'orda di bestie, sue alleate, ma non fece alcuna differenza.\"\nImpresa:\nSpezzare le catene\nZona:\nKorthia e Fauce"}
MultiLanguageItemData['it'][186655] = {name = "[q4]Redini del Destriero dei Giurafauce", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il destino di tutti i destrieri cavalcabili.\"\nImpresa:\nMaestro Impeccabile\nZona:\nTorgast, Torre dei Dannati"}
MultiLanguageItemData['it'][186656] = {name = "[q4]Redini del Destriero Tenebroso del Sanctum", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Solo i luogotenenti più potenti del Carceriere ricevono in dono questi destrieri per perlustrare le sale della torre.\"\nBottino:\nLe Nove\nZona:\nSanctum del Dominio"}
MultiLanguageItemData['it'][186657] = {name = "[q4]Redini del Destriero Tenebroso Vincolato all'Anima", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Ve'nari conosce molti modi per infiltrarsi nella Fauce e ostacolare i piani del Carceriere, come vincolare i suoi stessi servitori.\"\nBottino:\nDono Misterioso di Ve'nari\nZona:\nFauce"}
MultiLanguageItemData['it'][186659] = {name = "[q4]Redini del Destriero Caduto", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Le urla del destriero riecheggiano in tutta la Fauce mentre continua a cavalcare senza sosta in ogni dove, alla perenne ricerca di una via di fuga dagli eterni tormenti che è stato costretto a subire.\"\nBottino:\nDestriero Caduto\nZona:\nFauce"}
