MultiLanguageItemData['it'][186671] = {name = "Tecnica: Runa Vantus - Sanctum del Dominio", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare una Runa Vantus - Sanctum del Dominio.\nRichiede Runografia di Shadowlands (100)\nPrezzo di vendita: \nRuna Vantus - Sanctum del Dominio\n[q2]Usa: Ti sintonizza con le energie del boss del Sanctum del Dominio che hai come bersaglio, aumentando il tuo indice di versatilità di 1875 quando combatti contro di lui.\n\n È possibile usare una sola Runa Vantus alla settimana, e l'effetto dura per l'intera settimana.\nPrezzo di vendita:\nRichiede Inchiostro Luminoso (10), Inchiostro Ombrale (10), Inchiostro Quieto , Cartapecora Oscura"}
MultiLanguageItemData['it'][186672] = {name = "Ali Effimere", additional_info = "Oggetto di missione\nUnico\n[q2]Usa: Balza in avanti con ali effimere, riducendo la velocità di caduta per 10 s. Quindi, salta su una posizione vicina. (6 S Recupero)"}
MultiLanguageItemData['it'][186673] = {name = "[q5]Ricordo dell'Affinità tra Simili", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAffinità tra Simili Livello 80 Abilità dell'Incisione Runica Istantaneo\nTu e il tuo Spirito Affine ottenete un aumento di un attributo secondario in base alla vostra Congrega d'appartenenza. Questo bonus è dimezzato per il tuo Spirito Affine, ma entrambi i bonus sono raddoppiati quando il legame è Potenziato.\n\nKyrian : indice di maestria aumentato di 571 .\nSilfi della Notte : celerità aumentata del 6%.\nVenthyr : probabilità di critico aumentata del 6%.\nNecrosignori : versatilità aumentata del 6%.\nIncisione Runica su: Collo, Spalle\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Druido"}
MultiLanguageItemData['it'][186676] = {name = "[q5]Ricordo del Massacro Tossico", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nMassacro Tossico Abilità dell'Incisione Runica Istantaneo\nQuando Sepsi termina sul tuo bersaglio, [ Assassinio : ottieni Scarica d'Adrenalina e Lame d'Ombra ] [ Fuorilegge : ottieni Lame d'Ombra e applica Ritorsione al bersaglio attuale ] [ Scaltrezza : ottieni Scarica d'Adrenalina e applica Ritorsione al bersaglio attuale ] per 10 s.\nIncisione Runica su: Torso, Gambe, Piedi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Ladro"}
MultiLanguageItemData['it'][186677] = {name = "[q0]Incavo Metallico", additional_info = "Prezzo di vendita:"}
MultiLanguageItemData['it'][186678] = {name = "[q3]Cassa di Armi Forgiate nella Fauce", additional_info = "Torgast, Torre dei Dannati\n[q2]Usa: Armi Forgiate nella Fauce ti aiutano in combattimento per 2 min. (5 Min Recupero)\n[q]\"Queste armi sembrano avere una vita propria.\""}
MultiLanguageItemData['it'][186679] = {name = "[q3]Pergamena del Dominio", additional_info = "Torgast, Torre dei Dannati\n[q2]Usa: Mette sotto il tuo controllo un bersaglio nemico non élite per 2 min. Quando la runa termina, il bersaglio controllato esplode, infliggendo danni a tutti nelle vicinanze. (5 Min Recupero)\n[q]\"Meglio non fissare le rune troppo a lungo.\""}
MultiLanguageItemData['it'][186680] = {name = "[q2]Stivale Pieno d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"Non dimenticare che è pieno d'oro, altrimenti potresti farti male alle dita.\"\n[q2]<Destra Aprire>"}
MultiLanguageItemData['it'][186684] = {name = "Ricordi di Tempi Migliori", additional_info = "[q2]Usa: Richiama dei tempi migliori a Oribos, prima che il potere della Fauce crescesse. Dura 168 ore.\n[q]\"Non modifica affatto l'oscurità imminente, ma la fa sembrare più piacevole.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186685] = {name = "[q2]Frammento di Reliquia", additional_info = "Reliquie di Korthia\nSi vincola alla raccolta\n[q2]Usa: Consegna i Frammenti di Reliquia all'Archivista Roh-Suir nel Reliquiario della Rimembranza, ottenendo 1 Ricerca Catalogata.\n[q]\"Antichi simboli sono ancora visibili sulla superficie di questi frammenti.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186686] = {name = "[q3]Ossa dell'Oracolo Pallide", additional_info = "Si vincola all'uso\nGiocattolo\n[q2]Usa: Consulta le ossa per scoprire il futuro. (15 Min Recupero)\n[q]\"Una serie di piccole ossa con dei simboli incisi che permettono all'utilizzatore di scoprire il proprio futuro.\""}
MultiLanguageItemData['it'][186687] = {name = "[q5]Ricordo degli Spiriti Celestiali", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSpiriti Celestiali Abilità dell'Incisione Runica Istantaneo\nRiduce il tempo di recupero di Convocazione degli Spiriti del 50% e la sua durata del 25%. Convocazione degli Spiriti ha una probabilità aggiuntiva di lanciare un incantesimo o un'abilità eccezionale.\nIncisione Runica su: Gambe, Piedi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Druido"}
MultiLanguageItemData['it'][186688] = {name = "[q3]Secchio Pieno d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"Il manico rende più facile spostarlo con tutto l'oro che contiene.\"\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186689] = {name = "[q5]Ricordo degli Elementi Scheggiati", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nElementi Scheggiati Abilità dell'Incisione Runica Istantaneo\nOgni ulteriore lancio di Dardo Fulminante generato da Ondata Primordiale aumenta la celerità del 10% per 12 s.\nIncisione Runica su: Collo, Fianchi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega."}
MultiLanguageItemData['it'][186690] = {name = "[q4]Barile Pieno d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"Squartacus si è arrabbiato molto quando ha dovuto usare il suo barile di birra per metterci l'oro.\"\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186691] = {name = "[q2]Borsa Piena d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"È stata fatta una cucitura aggiuntiva così che la borsa possa contenere tutte le monete.\"\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186692] = {name = "[q3]Elmetto Pieno d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"Le istruzioni dicono di tenerlo al contrario finché non è il momento di tirarne fuori le monete.\"\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186693] = {name = "[q4]Carriola Piena d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"Quando hai bisogno di una carriola per metterci tutto il tuo oro, vuol dire che ne hai abbastanza?\"\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186694] = {name = "Borsa di Minerali Ombrosa", additional_info = "Si vincola alla raccolta\n[q]\"Una borsa di minerali delle Terretetre.\"\n[q2]<Destra Aprire>"}
