MultiLanguageItemData['it'][186697] = {name = "[q2]Scarica di Bocciolo", additional_info = "[q2]Usa: Inzuppa gli amici con una scarica di verde! Divertimento per tutte le età! (3 Min Recupero)\n5 Carici"}
