MultiLanguageItemData['it'][186702] = {name = "[q3]Flauto d'Osso Pallido", additional_info = "Giocattolo\n[q2]Usa: Suoni una melodia inquietante, facendo ballare tutti nelle vicinanze. (10 Min Recupero)\n[q]\"Un flauto d'osso delle terre dei morti? Non sembra affatto di cattivo augurio.\""}
MultiLanguageItemData['it'][186703] = {name = "[q0]Calice Dorato", additional_info = "Si vincola alla raccolta\n[q]\"Anche solo la coppa sembra valere molto oro.\"\nPrezzo di vendita:"}
