MultiLanguageItemData['it'][186705] = {name = "[q2]Calice Pieno d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"Squartacus ha recuperato una pila di monete dalla sua enorme cassa per riempire la coppa.\"\n[q2]<Destra Aprire>"}
MultiLanguageItemData['it'][186706] = {name = "[q2]Cappello Pieno d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"I fili del cappello si stanno strappando sotto il peso di tutte quelle monete.\"\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186707] = {name = "[q3]Cassa Piena d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"La cassa è così piena di monete, che ormai straripano dal coperchio.\"\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186708] = {name = "[q2]Tazza per Pennelli Piena d'Oro", additional_info = "Si vincola alla raccolta\n[q]\"Nessuno solitamente mette in discussione gli strani interessi di un Dragatore, soprattutto non di uno che fornisce un servizio tanto fondamentale quanto le riparazioni.\"\n[q2]<Destra Aprire>\nPrezzo di vendita:"}
MultiLanguageItemData['it'][186710] = {name = "[q5]Ricordo dell'Obbediente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nObbedienza Abilità dell'Incisione Runica Istantaneo\nFlagellazione aumenta la versatilità del 0.5%. Ogni punto combo consumato durante Flagellazione ne riduce il tempo di recupero di 1 s. (100ms di recupero)\nIncisione Runica su: Testa, Schiena\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Ladro"}
MultiLanguageItemData['it'][186712] = {name = "[q5]Ricordo dell'Aculeo della Morte", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nAculeo della Morte Abilità dell'Incisione Runica Istantaneo\nAculeo Osseo Seghettato ha 2 cariche aggiuntive e lancia 1 aculeo osseo aggiuntivo ai nemici vicini.\nIncisione Runica su: Polsi, Mani\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Ladro"}
MultiLanguageItemData['it'][186713] = {name = "[q4]Anello di Controllo di Nilganihmaht", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Di tutti i giganti che osarono sfidare il Carceriere, Nilganihmaht fu il più arrogante. A causa della sua ribellione, la mano mozzata del gigante venne nascosta sotto un velo di tormenti e gli anelli che potevano richiamarla vennero sparsi per tutta la Fauce.\"\nZona:\nFauce"}
MultiLanguageItemData['it'][186714] = {name = "[q3]Rapporto di Ricerca: Cristallo Onnisciente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Permette di vedere in modo permanente e trovare le creature che stanno trasportando dei Frammenti di Reliquia.\nRichiede la ricerca di Livello 2 con il Codice degli Archivisti.\n[q]\"Roh-Suir è riuscito a ricreare la ricerca su un Cristallo Onnisciente, permettendoti di aggiungerne uno al Bastone Guida per poter individuare altre reliquie.\""}
MultiLanguageItemData['it'][186715] = {name = "[q3]Rapporto di Ricerca: Leghe Migliorate", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Permette di potenziare gli oggetti di Korthia e della Fauce al Grado 10.\n[q]\"Analizzare gli effetti della magia del dominio sugli oggetti di Korthia e della Fauce ha portato a leghe migliorate che ci permettono di rendere i nostri oggetti più resistenti e più potenti.\""}
MultiLanguageItemData['it'][186716] = {name = "[q3]Rapporto di Ricerca: Santuari Antichi", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Permette di interagire con le spade vicino ai santuari antichi, ottenendo l'abilità di raggiungere tesori di reliquie inaccessibili.\nRichiede la ricerca di Livello 5 con il Codice degli Archivisti.\n[q]\"Ulteriori ricerche sul misterioso Codice della Comprensione che hai recuperato dalla fenditura ci hanno permesso di comprendere l'interazione con le spade dei santuari antichi trovate a Korthia.\""}
MultiLanguageItemData['it'][186717] = {name = "[q3]Rapporto di Ricerca: Leghe Adattive", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Permette di potenziare gli oggetti di Korthia e della Fauce al Grado 5.\nRichiede la ricerca di Livello 6 con il Codice degli Archivisti e Fama 61 o superiore.\n[q]\"Ulteriori ricerche sul recupero delle reliquie ci hanno portato a scoprire nuove leghe adattive che ci permetteranno di aumentare la potenza degli oggetti toccati dalla magia del dominio di Korthia e della Fauce.\""}
MultiLanguageItemData['it'][186718] = {name = "[q2]Kit per Riparazioni del Teletrasporto", additional_info = "Si vincola alla raccolta\nRichiede la ricerca di Livello 3 con il Codice degli Archivisti.\n[q]\"C'è una regola universale: a destra si stringe e a sinistra si allenta. Permette di riparare i Teletrasporti Antichi di Korthia, fornendo l'accesso ad archivi nascosti.\""}
MultiLanguageItemData['it'][186721] = {name = "[q3]Trattato: Abbondanza di Reliquie nelle Terretetre", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Permette in modo permanente di trovare reliquie che forniscono reputazione aggiuntiva con le fazioni delle Terretetre quando si completa una missione mondiale o giornaliera, si depredano tesori o si uccide una creatura rara nei rispettivi regni.\nRichiede la ricerca di Livello 6 con il Codice degli Archivisti."}
MultiLanguageItemData['it'][186722] = {name = "[q3]Trattato: Lo Studio dell'Animum e della Conquista dei Bottini", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Permette in modo permanente di ottenere 25 Animum aggiuntivo quando si completa una missione mondiale o giornaliera, si depredano tesori o si uccide una creatura rara nelle Terretetre.\nRichiede la ricerca di Livello 5 con il Codice degli Archivisti."}
MultiLanguageItemData['it'][186724] = {name = "[q2]Tecnica: Contratto - Marcia della Morte", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Contratto - Marcia della Morte.\nRichiede Runografia di Shadowlands (60)\nRichiedeMarcia della Morte\n- Riverito\nPrezzo di vendita: \nContratto - Marcia della Morte\n[q2]Usa: Firma un contratto con la Marcia della Morte che permette di guadagnare reputazione con questa fazione ogni volta che si completano delle missioni mondiali nelle Terretetre.\nRichiedeMarcia della Morte\n- Amichevole\nRichiede Inchiostro Luminoso , Inchiostro Ombrale , Cartapecora Oscura"}
MultiLanguageItemData['it'][186725] = {name = "Pane d'Ossa", additional_info = "[q2]Usa: Rigenera ( 22500 / 5 * 20) salute in 20 s. Devi sederti per mangiare."}
MultiLanguageItemData['it'][186726] = {name = "Caramella Dura Porosa", additional_info = "[q2]Usa: Ti godi un dolcetto.\n[q]\"Non ha alcun valore nutritivo.\""}
MultiLanguageItemData['it'][186727] = {name = "[q3]Chiave Spezzasigillo", additional_info = "Si vincola alla raccolta\n[q]\"La chiave per spezzare un Sigillo del Dominio.\""}
MultiLanguageItemData['it'][186730] = {name = "Provviste per Mascotte", additional_info = "Oggetto di missione\n[q]\"Forniture recuperabili per mascotte.\""}
MultiLanguageItemData['it'][186731] = {name = "[q2]Chiave della Fenditura Riparata", additional_info = "Si vincola alla raccolta\n[q2]Equipaggia: Permette di entrare in un Portale della Fenditura a Korthia e di restarci per 15 min.\nRichiede la ricerca di Livello 4 con il Codice degli Archivisti.\n[q]\"Questa pietra si agita nella mano, vibrando con di uno strano potere e sussurrando dall'aldilà.\"\nPrezzo di vendita:"}
