MultiLanguageItemData['it'][186993] = {name = "Modello: Statua di Pietra Porosa", additional_info = "Unico\n[q2]Usa: Ti insegna a creare una Statua di Pietra Porosa.\nRichiede Oreficeria di Shadowlands (50)\nPrezzo di vendita: \nStatua di Pietra Porosa\n[q2]Usa: Posiziona sul terreno una statua di pietra porosa che cura per alcuni istanti prima che il suo potere svanisca. (5 Min Recupero)\nRichiede Oreficeria di Shadowlands (50)\nPrezzo di vendita:\nRichiede Pietra Porosa (5)"}
MultiLanguageItemData['it'][186994] = {name = "Modello: Statua di Pietra Oscurata", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare una Statua di Pietra Oscurata.\nRichiede Oreficeria di Shadowlands (100)\nPrezzo di vendita: \nStatua di Pietra Oscurata\n[q2]Usa: Posiziona sul terreno una statua di pietra oscurata che cura per alcuni istanti prima che il suo potere svanisca. (5 Min Recupero)\nRichiede Oreficeria di Shadowlands (100)\nPrezzo di vendita:\nRichiede Pietra Oscurata (5)"}
MultiLanguageItemData['it'][186995] = {name = "Modello: Asciugamano Ammantato", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Asciugamano Ammantato.\nRichiede Sartoria di Shadowlands (5)\n\n\nAsciugamano Ammantato\n[q2]Usa: Ripulisce sangue, melme, polvere... davvero tutto! (10 S Recupero)\n[q]\"La pulizia è a un passo dalla titanicità.\"\nPrezzo di vendita:\nRichiede Stoffa Ammantata (3)"}
