MultiLanguageItemData['it'][186998] = {name = "Modello: Ossa dell'Oracolo Pallide", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare delle Ossa dell'Oracolo Pallide.\nRichiede Conciatura di Shadowlands (50)\nPrezzo di vendita: \n[q3]Ossa dell'Oracolo Pallide\nSi vincola all'uso\nGiocattolo\n[q2]Usa: Consulta le ossa per scoprire il futuro. (15 Min Recupero)\n[q]\"Una serie di piccole ossa con dei simboli incisi che permettono all'utilizzatore di scoprire il proprio futuro.\"\nRichiede Osso Pallido (14)"}
MultiLanguageItemData['it'][186999] = {name = "Modello: Flauto d'Osso Pallido", additional_info = "Unico\n[q2]Usa: Ti insegna a creare un Flauto d'Osso Pallido.\nRichiede Conciatura di Shadowlands (75)\nPrezzo di vendita: \n[q3]Flauto d'Osso Pallido\nGiocattolo\n[q2]Usa: Suoni una melodia inquietante, facendo ballare tutti nelle vicinanze. (10 Min Recupero)\n[q]\"Un flauto d'osso delle terre dei morti? Non sembra affatto di cattivo augurio.\"\nRichiede Osso Pallido (20), Filo della Penombra (3)"}
MultiLanguageItemData['it'][187000] = {name = "Modello: Dolcetto per Mascotte Elusivo", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare uno Scheletro a Molla.\nRichiede Conciatura di Shadowlands (100)\nPrezzo di vendita: \n[q2]Dolcetto per Mascotte Elusivo\nGiocattolo\n[q2]Usa: Permette di rilasciare un golem d'ossa che la tua mascotte può inseguire per 30 s. (10 Min Recupero)\nPrezzo di vendita:\nRichiede Osso Pallido (18), Scheggia Immortale (3)"}
