MultiLanguageItemData['it'][187103] = {name = "[q3]Statuetta Perenne", additional_info = "Reliquie di Korthia\nSi vincola alla raccolta\nUnico\nQuesto oggetto avvia una missione\n[q]\"Gli eventi a cui questa statuetta ha assistito ti sconvolgerebbero la mente. Si potrebbe imparare molto, se solo non fosse così ambigua.\""}
MultiLanguageItemData['it'][187104] = {name = "[q3]Obelisco delle Notizie Oscure", additional_info = "Reliquie di Korthia\nSi vincola alla raccolta\nUnico\nQuesto oggetto avvia una missione\n[q]\"In prossimità dell'obelisco, una voce nella testa ti mormora dolci menzogne e folli verità.\""}
MultiLanguageItemData['it'][187105] = {name = "[q5]Ricordo dello Sguardo dell'Agonia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSguardo dell'Agonia Abilità dell'Incisione Runica Istantaneo\nAumenta i danni inflitti da Marchio Peccaminoso del 10% e i danni inflitti da [ Rovina : Raggio Oculare /\n\nVendetta\nVildevastazione ] aumentano la durata di Marchio Peccaminoso di 0.75 s.\nIncisione Runica su: Testa, Gambe\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cacciatore di Demoni"}
MultiLanguageItemData['it'][187106] = {name = "[q5]Ricordo della Risonanza Divina", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nRisonanza Divina Abilità dell'Incisione Runica Portata di 30 m\n Istantaneo\nDopo aver lanciato Rintocco Divino, si lancia istantaneamente [ Protezione : Scudo del Vendicatore ] [ Sacro : Folgore Sacra /\n\nCastigo\nGiudizio ] ogni 5 s. L'effetto dura 15 s. (3s di recupero)\nIncisione Runica su: Torso, Fianchi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Paladino"}
MultiLanguageItemData['it'][187107] = {name = "[q5]Ricordo del Martellaccio Obbligato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nMartellaccio Obbligato Abilità dell'Incisione Runica Istantaneo\nSacro\n Aumenta le cariche di Martello del Dominatore di 1. Un ulteriore lancio di Parola di Gloria attiva automaticamente Luce dell'Alba.\n\nProtezione\n Aumenta le cariche di Martello del Dominatore di 1. Un ulteriore lancio di Parola di Gloria attiva automaticamente Scudo del Virtuoso.\n\nCastigo\n Aumenta le cariche di Martello del Dominatore di 1. Un ulteriore lancio di Verdetto dei Templari attiva automaticamente Tempesta Divina.\nIncisione Runica su: Testa, Spalle, Dito\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Paladino"}
MultiLanguageItemData['it'][187109] = {name = "[q5]Ricordo del Massacro Fiammeggiante", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nMassacro Fiammeggiante Abilità dell'Incisione Runica Istantaneo\nA Caccia ti avvolge con Rogo Rovente al raggiungimento del bersaglio e aumenta l'Agilità del 4% per 12 s per ogni nemico colpito.\nIncisione Runica su: Spalle, Piedi, Schiena\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cacciatore di Demoni"}
MultiLanguageItemData['it'][187111] = {name = "[q5]Ricordo della Fede Cieca", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFede Cieca Abilità dell'Incisione Runica Istantaneo\nDecreto Elisio frantuma 2 Frammenti Inferiori dell'Anima aggiuntivi e fornisce Fede Cieca per 20 s. Per ogni Frammento Inferiore dell'Anima consumato mentre Fede Cieca è attiva, la furia aumenta di 10 e la versatilità del 1%, fino a un massimo del 20%.\nIncisione Runica su: Torso, Schiena\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cacciatore di Demoni"}
MultiLanguageItemData['it'][187113] = {name = "[q3]Palla con Catena Personale", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Crea la tua Palla con Catena Personale da trascinare in giro. (5 Min Recupero)\n[q]\"Ce ne sono tante uguali, ma questa è la mia.\"\nPrezzo di vendita:"}
