MultiLanguageItemData['it'][187116] = {name = "Manichino d'Allenamento", additional_info = "[q2]Usa: Applica in modo permanente un piccolo dispositivo a un equipaggiamento per fianchi, permettendoti di creare un bersaglio di cartone che i nemici attaccheranno. (5 min di tempo di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][187117] = {name = "Pagine Azzurre", additional_info = "Oggetto di missione\n[q]\"Pagine strappate, colme di energia.\""}
MultiLanguageItemData['it'][187118] = {name = "[q5]Ricordo del Giuramento Demoniaco", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nGiuramento Demoniaco Abilità dell'Incisione Runica Istantaneo\nQuando il demone di Carne alla Fiamma esplode, affligge 5 nemici vicini con Marchiatura Ardente per 5 s. Inoltre, aumenta la durata di Anima Infranta di 8 s.\nIncisione Runica su: Fianchi, Polsi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cacciatore di Demoni"}
MultiLanguageItemData['it'][187119] = {name = "[q3]Anello dell'Introspezione", additional_info = "Reliquie di Korthia\nSi vincola alla raccolta\nUnico\nQuesto oggetto avvia una missione\n[q]\"Se si guarda la gemma incastonata in questa vera da un'angolatura obliqua, è possibile vedere un duplicato scintillante dell'anello.\""}
MultiLanguageItemData['it'][187120] = {name = "[q4]Scheggia di Cura del Sangue 1 - Grado 5", additional_info = "Scheggia del Dominio\nSi vincola alla raccolta\nNella Fauce, il ritorno vitale aumenta di 1209 ."}
MultiLanguageItemData['it'][187123] = {name = "Ninnolo del Potenziamento", additional_info = "Si vincola alla raccolta\n[q]\"Utilizzabile per potenziare la Scheggia del Dominio bersaglio.\""}
MultiLanguageItemData['it'][187124] = {name = "Medaglione dell'Ira", additional_info = "Oggetto di missione\n[q]\"Concesso ai Venthyr dal Sire in persona. Consente a chi lo indossa di esercitare un parziale dominio su Revendreth.\""}
MultiLanguageItemData['it'][187126] = {name = "Diario Scartato", additional_info = "Oggetto di missione\n[q]\"Scritto dall'Alienatore Xevveth, sembra che fosse nel posto sbagliato.\""}
MultiLanguageItemData['it'][187127] = {name = "[q5]Ricordo delle Braci Radiose", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBraci Radiose Abilità dell'Incisione Runica Istantaneo\nAumenta la durata di Santificazione Cinerea del 50%. Annullare anticipatamente l'effetto di Santificazione Cinerea ne riduce il tempo di recupero di massimo il 50%, proporzionalmente alla durata restante.\nIncisione Runica su: Polsi, Mani, Schiena\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Paladino"}
MultiLanguageItemData['it'][187128] = {name = "Trova-la-Spia", additional_info = "Oggetto di missione\n[q2]Usa: Chiedi aiuto al gatto cattura-spie: Fiona. (6 S Recupero)"}
MultiLanguageItemData['it'][187131] = {name = "Interni di Automa", additional_info = "Oggetto di missione\n[q]\"...gelatinoso?\""}
MultiLanguageItemData['it'][187132] = {name = "[q5]Ricordo delle Stagioni Abbondanti", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nStagioni Abbondanti Abilità dell'Incisione Runica Istantaneo\nLanciare Benedizione dell'Estate fornisce Equinozio dopo 10 s.\n\nEquinozio: aumenta l'efficacia di Benedizione dell'Estate del 100% per 10 s.\nIncisione Runica su: Gambe, Piedi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Paladino"}
MultiLanguageItemData['it'][187133] = {name = "[q3]Cappellino Incantevole", additional_info = "Corte delle Braci\nSi vincola alla raccolta\nUnico\n[q]\"Un dono per il tuo Maggiordomo Dragatore, per dargli l'opzione di indossare un cappello da strega.\""}
MultiLanguageItemData['it'][187134] = {name = "[q4]Sfaccettatore Modellalega", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Aggiunge un incavo a un oggetto della Stagione 2 di Shadowlands che non ne ha già uno. Può essere usato su pezzi per testa, collo, polsi, fianchi e dita."}
MultiLanguageItemData['it'][187136] = {name = "[q7]Rapporto di Ricerca: Tecniche di Analisi delle Reliquie", additional_info = "[q7]Si vincola alla Brigata\nUnico\n[q2]Usa: Aumenta la reputazione ottenuta con il Codice degli Archivisti del 50% quando si consegnano delle reliquie all'Archivista.\nRichiede la ricerca di Livello 6 con il Codice degli Archivisti.\n[q]\"Man mano che le tecniche di ricerca migliorano, l'Archivista può raccogliere più informazioni da ogni frammento.\""}
MultiLanguageItemData['it'][187137] = {name = "[q3]Rapporto di Ricerca: Tecniche di Ritrovamento delle Reliquie", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Fornisce una probabilità del 20% di trovare Frammenti di Reliquia aggiuntivi quando si depredano nemici rari e tesori a Korthia.\n[q]\"Sapere come identificare le reliquie mancanti è fondamentale per i nostri sforzi, e questo rapporto spiega i consigli e i trucchi per trovare altri frammenti di reliquie da fonti comuni.\""}
MultiLanguageItemData['it'][187138] = {name = "[q3]Rapporto di Ricerca: Leghe Primarie", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Permette di potenziare gli oggetti di Korthia e della Fauce al Grado 6.\nRichiede la ricerca di Livello 6 con il Codice degli Archivisti e Fama 75 o superiore.\n[q]\"Con il completo accesso al Codice degli Archivisti, ora comprendiamo il potere vincolante della magia del dominio e come si allinei con alcune delle Leghe Primarie presenti nelle Terretetre, permettendoci di migliorare ulteriormente gli oggetti di Korthia e della Fauce.\""}
MultiLanguageItemData['it'][187139] = {name = "[q3]Cuore d'Ombra Imbottigliato", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Rompe il sigillo della bottiglia, permettendo all'ombra all'interno di impossessarsi di te per un breve periodo. (1 Ora Recupero)\n[q]\"Meglio lasciare indisturbato il contenuto all'interno.\""}
MultiLanguageItemData['it'][187140] = {name = "[q3]Anello della Doppiezza", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Usa un po' della magia rimasta sull'anello per evocare un'immagine speculare che copia le tue azioni. (1 Ora Recupero)"}
