MultiLanguageItemData['it'][187145] = {name = "[q3]Trattato: Riconoscere la Stigia e suoi utilizzi", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Permette in modo permanente di ottenere 10 Stigia aggiuntiva quando si completa una missione mondiale o giornaliera, si depredano tesori o si uccide una creatura rara che rilascia Stigia nella Fauce o a Korthia.\nRichiede la ricerca di Livello 2 con il Codice degli Archivisti."}
MultiLanguageItemData['it'][187148] = {name = "[q4]Scheggia Vincolata alla Morte", additional_info = "Si vincola alla raccolta\n[q2]Usa: Scopri un potenziamento di un Condotto casuale tra i tuoi Condotti di livello oggetto più basso per la tua specializzazione attuale, fino a un livello massimo di 252.\nRichiede la ricerca di Livello 6 con il Codice degli Archivisti.\n[q]\"Utilizzabile alla Forgia dei Vincoli per scoprire un condotto o un grado di condotto sconosciuto.\""}
MultiLanguageItemData['it'][187150] = {name = "[q3]Artiglio Feticcio di Gorak", additional_info = "Reliquie di Korthia\nSi vincola alla raccolta\nUnico\nQuesto oggetto avvia una missione\n[q]\"Terribile da guardare e ancora peggio da odorare.\""}
