MultiLanguageItemData['it'][187216] = {name = "[q4]Mezzaluna Avvolgianime", additional_info = "Si vincola alla raccolta\n[q2]Usa: Scopri un potenziamento di un Condotto casuale tra i tuoi Condotti di livello oggetto più basso per la tua specializzazione attuale, fino a un livello massimo di 226.\n[q]\"Utilizzabile alla Forgia dei Vincoli per scoprire un condotto o un grado di condotto sconosciuto.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][187217] = {name = "[q5]Ricordo della Birra Copiosa", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBirra Copiosa Abilità dell'Incisione Runica Istantaneo\n Circa 1.5 apparenze ogni minuto\nLe abilità hanno una bassa probabilità di lanciare Birra di Polvere d'Ossa sulla posizione del bersaglio. (500ms di recupero)\nIncisione Runica su: Collo, Spalle, Torso\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Monaco"}
MultiLanguageItemData['it'][187218] = {name = "[q5]Tomo delle Origini", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare delle Vestigia delle Origini, un potente Reagente d'Artigianato Facoltativo che aumenta il livello oggetto di un oggetto leggendario di base.\nRichiede la reputazione Onorato con la Marcia della Morte."}
