MultiLanguageItemData['it'][187222] = {name = "[q4]Singolarità Stigia", additional_info = "Si vincola alla raccolta\n[q]\"Contiene 500 Stigia.\"\n[q2]<Destra Aprire>"}
MultiLanguageItemData['it'][187223] = {name = "[q5]Ricordo dei Semi della Crescita Sfrenata", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSemi della Crescita Sfrenata Abilità dell'Incisione Runica Istantaneo\nOgni impulso dell'effetto dannoso di Trasfusione dei Silfi riduce il tempo di recupero dei Lupi Spirituali di 9.0 s e aumenta la probabilità di critico del 4% per 15 s.\nIncisione Runica su: Testa, Mani\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Ladro"}
MultiLanguageItemData['it'][187224] = {name = "[q5]Ricordo del Condotto Elementale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nCondotto Elementale Abilità dell'Incisione Runica Istantaneo\nLancia Marea Benefica su un massimo di 5 bersagli alleati curati da Raccolto a Catena. Lancia Folgore del Fuoco su un massimo di 5 bersagli nemici colpiti da Raccolto a Catena. I colpi critici di Folgore del Fuoco riducono il tempo di recupero di Raccolto a Catena di 1.0 s.\nIncisione Runica su: Torso, Polsi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega."}
MultiLanguageItemData['it'][187225] = {name = "[q5]Ricordo del Detrito d'Anima Stagnante", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nDetrito d'Anima Stagnante Abilità dell'Incisione Runica Istantaneo\nQuando Obolo fornisce frammenti d'anima, la velocità di movimento aumenta del 100% e la probabilità di critico aumenta del 45% per 8 s. Se Obolo termina, aumenta la velocità di movimento del 33% e aumenta la probabilità di critico del 15%.\nIncisione Runica su: Torso, Polsi, Schiena\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Stregone"}
MultiLanguageItemData['it'][187226] = {name = "[q5]Ricordo delle Scheggie dell'Annientamento", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nScheggia dell'Annientamento Abilità dell'Incisione Runica Istantaneo\nDardo della Decimazione aumenta la probabilità di critico del 100% e i danni critici inflitti da [ Distruzione : Incenerimento / Risucchio d'Anima ] [ Demonologia : Dardo Demoniaco /\n\nAfflizione\n Dardo d'Ombra ] del 50%.\nIncisione Runica su: Fianchi, Gambe\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Stregone"}
MultiLanguageItemData['it'][187227] = {name = "[q5]Ricordo della Borsa d'Anime Decadente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBorsa d'Anime Decadente Abilità dell'Incisione Runica Istantaneo\nOgni bersaglio affetto da Putrefazione d'Anima aumenta la celerità e la probabilità di critico del 5% per 8 s.\nIncisione Runica su: Piedi, Mani\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Stregone"}
MultiLanguageItemData['it'][187228] = {name = "[q5]Ricordo dell'Esplosione Perpetua Contenuta", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nEsplosione Perpetua Contenuta Abilità dell'Incisione Runica Istantaneo\nAumenta i danni periodici inflitti da Catastrofe Imminente del 125%, più il 15% per ogni bersaglio nemico colpito lungo la traiettoria verso il bersaglio finale, fino a un massimo del 275%.\nIncisione Runica su: Testa, Collo, Spalle\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Stregone"}
MultiLanguageItemData['it'][187229] = {name = "[q5]Ricordo del Patto degli Inseguitori d'Anime", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nPatto degli Inseguitori d'Anime Abilità dell'Incisione Runica Istantaneo\nQuando Freccia Risonante infligge danni a un bersaglio, la probabilità di critico del gruppo aumenta del 10% per 10 s. (1s di recupero)\nIncisione Runica su: Fianchi, Mani\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cacciatore"}
MultiLanguageItemData['it'][187230] = {name = "[q5]Ricordo della Borsa di Munizioni", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nBorsa di Munizioni Abilità dell'Incisione Runica Istantaneo\nFino a 2 bersagli colpiti dal un tuo Chakram della Morte vengono colpiti anche da Tiro Esplosivo.\nIncisione Runica su: Testa, Polsi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cacciatore"}
MultiLanguageItemData['it'][187231] = {name = "[q5]Ricordo dei Frammenti delle Corna Antiche", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nFrammenti delle Corna Antiche Abilità dell'Incisione Runica Istantaneo\nQuando gli Spiriti Selvatici colpiscono meno di 5 bersagli, c'è una probabilità del 100% che gli Spiriti Selvatici infliggano danni una seconda volta.\nIncisione Runica su: Collo, Torso\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cacciatore"}
MultiLanguageItemData['it'][187232] = {name = "[q5]Ricordo del Sacchetto di Frammenti Taglienti", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nSacchetto di Frammenti Taglienti Abilità dell'Incisione Runica\nI Tiri Mortali aggiuntivi di Tiro Scorticato fanno sì che 6 bersagli entro 12 m sanguinino, subendo danni pari al 60% dei danni inflitti da Tiro Mortale in 6 s.\nIncisione Runica su: Gambe, Piedi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Cacciatore"}
