MultiLanguageItemData['it'][187511] = {name = "[q5]Ricordo del Vigore Elisio", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ripristina il seguente ricordo dell'Incisore di Rune:\n\n\nVigore Elisio Abilità dell'Incisione Runica Istantaneo\nAumenta la durata di Lancia del Bastione di 4 s. Mentre sei all'interno dell'area di Lancia del Bastione, i danni critici inflitti aumentano del 25%.\nIncisione Runica su: Gambe, Piedi\nFonte: Si ottiene raggiungendo Fama 48 con la tua Congrega.\nRichiede: Guerriero"}
MultiLanguageItemData['it'][187512] = {name = "[q3]Tomo dei Peccatucci", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Aiuta un animale a espiare i peccati per passare all'aldilà che merita.\n\n Utilizzabile solo dai membri della Congrega dei Venthyr o da coloro che hanno raggiunto il livello di Fama 80 con i Venthyr. (1 Min Recupero)\n[q]\"Un tomo rituale che descrive i metodi dei Venthyr per assolvere le creature più piccole dai peccati.\""}
