MultiLanguageItemData['it'][187628] = {name = "Matrice di Rigenerazione", additional_info = "Oggetto di missione\nUnico\n[q]\"Uno strumento di grande potere per gli Automa. Tuttavia, questo dispositivo è ormai esaurito.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][187629] = {name = "[q4]Pietra Cuordiluce", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Vombatide Cuordiluce.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeIlluminati\n- Osannato\n\n\n[q]\"Gli Illuminati venerano tutte le creazioni dei Primi; tuttavia, per molti di loro, i vombatidi di Zereth Mortis hanno un posto speciale nel cuore. Queste creature sono sia fidate bestie da soma che adorate compagne di viaggio.\"\nMercante:\nVilo\nZona:\nZereth Mortis\nFazione:\nIlluminati - Osannato\nCosto:\n5.000"}
MultiLanguageItemData['it'][187630] = {name = "[q4]Annusacristalli Curioso", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Alla maggior parte dei vombatidi piace scavare nel terreno, ma i fiutatori sembrano avere una dote naturale nel trovare i cristalli nascosti sottoterra e si radunano intorno ai depositi più grandi.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187631] = {name = "[q4]Vombatide Oscuro", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Lo schema per sintetizzare questi vombatidi oscuri sembra essere apparso in reazione all'invasione dei Giurafauce. Il vombatide risultante sembra diverso, è scuro come gli invasori, ma si comporta normalmente.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187632] = {name = "[q4]Vombatide Adornato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I vombatidi rossi sono considerati fortunati dagli Illuminati. Al loro arrivo a Zereth Mortis, la prima creatura che incontrarono fu proprio un vombatide rosso.\"\nProfessione:\nSintesi di Protoforma"}
