MultiLanguageItemData['it'][187638] = {name = "[q4]Mortelesta", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questi cervidi selvaggi sono davvero in pace solo quando corrono attraverso le terre della morte.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187639] = {name = "[q4]Cervide Regale Tenue", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Osservando queste maestose creature, non è difficile notare come l'idea dei cervidi si sia evoluta nei cervi trovati su Azeroth e altri mondi mortali.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187640] = {name = "[q4]Redini del Proto-Cervo Consacrato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Proto-Cervo Consacrato.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeIlluminati\n- Riverito\n\n\n[q]\"Solo coloro tenuti in più alta considerazione dagli Illuminati possono tenere le redini di questo raro cervide.\"\nMercante:\nVilo\nZona:\nZereth Mortis\nFazione:\nIlluminati - Riverito\nCosto:\n5.000"}
MultiLanguageItemData['it'][187641] = {name = "[q4]Redini del Destriero di Zereth Spezzato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Qualunque fosse lo scopo di questi cervidi, è ormai dimenticato da tempo. Anche se non sono Dominati, sono stati corrotti dall'inaspettata presenza dei Giurafauce nel sacro regno di Zereth Mortis.\"\nProfessione:\nSintesi di Protoforma"}
