MultiLanguageItemData['it'][187660] = {name = "[q4]Vespide Svolazzatore", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli svolazzatori sono grossi vespidi operai, creati per trasportare altre creature. Invece di farsi guidare da una regina, queste creature seguono gli ordini solo del proprio cavaliere.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187662] = {name = "Gelatina Strana", additional_info = "Unico\n[q]\"Gli aurelidi di Zereth Mortis sembrano attratti da questa sostanza, ma è impossibile legarla a qualsiasi esca. Qualcuno con più familiarità con le creature marine potrebbe sapere cosa fare.\""}
MultiLanguageItemData['it'][187663] = {name = "[q4]Vespide Alabronzea", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Vespidi Alabronzea sono il risultato del tentativo di sintetizzare una regina vespide senza il resto dell'alveare. Anche se nessun mortale ha mai scoperto come sintetizzare un alveare, le alibronzee restano delle cavalcature affidabili così come sono.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187664] = {name = "[q4]Volarabbia Forgiato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Non c'è nulla che possa farti sentire vivo come cavalcare in giro per il regno della Morte in sella a un essere che ti odia.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187665] = {name = "[q4]Ronzio", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Bzz bzz bzz, bzz bzz! Bzz bzz bzz bzz bzz. bzz bzz bzz, bzz bzz bzz.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187666] = {name = "[q4]Cacciatore del Deserto", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Al servizio del grande Scopo, i Cacciatori del Deserto sono stati progettati per riempire i cieli dei regni lontani e dimenticati delle Terretetre.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187667] = {name = "[q4]Falconide Adattato alla Fauce", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Sin dall'incursione del Carceriere, Zereth Mortis ha sintetizzato dei nuovi falconidi fatti per resistere all'influenza corrompente della Fauce.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187668] = {name = "[q4]Falconide Predatore", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il Falconide Predatore è uno dei più aggressivi esemplari della propria specie, particolarmente adatto alla sua nicchia ecologica. Non avendo bisogno di alcuna ulteriore modifica, quelli sintetizzati oggi sono identici a quelli creati in passato.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187669] = {name = "[q4]Serenata", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questi meravigliosi elicidi emergono solo di notte. Quando sono contenti, i loro gusci risuonano di una melodia allegra.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187670] = {name = "[q4]Elicide Bronzeo", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Alcuni elicidi di Zereth Mortis hanno uno strano guscio metallico. Questi sono generalmente color bronzo, proprio come il metallo estratto anche dal più novizio dei minatori, con l'eccezione che la costruzione di questa creatura va ben oltre le abilità di un novizio.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187671] = {name = "[q4]Prototipo di Turbolumaca Fallito", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questa creatura non è stata progettata dai Primi, ma da un essere sconosciuto che ha tentato di creare una creatura molto veloce. Inutile dire che il tentativo è fallito, perché questa cavalcatura è molto lenta.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187672] = {name = "[q4]Elicide Scarlatto", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questa particolare colorazione rossastra è chiaramente intenzionale, ma l'unica altra differenza tra questi e altri elicidi è una caratteristica mancanza di melma.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187673] = {name = "[q4]Aurelide Criptico", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Codici dei Primi sono al di là di ogni comprensione mortale. Un effetto curioso della lingua è che, per ragioni ignote, alcuni aurelidi sono attratti dai mortali che aspirano a rivelarne i misteri.\"\nImpresa:\nDalla A alla Zereth\nCategoria:\nTerretetre"}
MultiLanguageItemData['it'][187674] = {name = "[q4]Inseguitore delle Profondità", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Inseguitore delle Profondità.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Catturate a Zereth Mortis, alcune di queste meduse andarono perdute quando la nave dei bracconieri affondò. Trovarono una nuova casa nelle profondità del Grande Mare.\"\nEmporio"}
MultiLanguageItemData['it'][187675] = {name = "[q4]Aurelide Scintillante", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Anche se è stato creato per difendere il Sepolcro dei Primi, ora che la sua funzione primaria si è esaurita, segue ciecamente i tuoi comandi.\"\nImpresa:\nGloria dell'incursore del Sepolcro\nCategoria:\nSpedizioni e incursioni"}
MultiLanguageItemData['it'][187676] = {name = "[q4]Polipo Stellafonda", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Aurelide Stellafonda.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"In veste di uno degli ultimi esemplari rimasti di una creatura elusiva, questo aurelide si sente a casa in acqua tanto quanto in aria.\"\nBottino:\nHirukon\nZona:\nZereth Mortis"}
MultiLanguageItemData['it'][187677] = {name = "[q4]Strisciatore della Genesi", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli Illuminati che hanno studiato i taracnidi credono che questa varietà sia una delle prime creature ad aver mai messo piede su Zereth Mortis.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187678] = {name = "[q4]Camminatore Taracnide", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questi taracnidi creano le loro tane negli angoli più oscuri di Zereth Mortis, uscendo fuori solo per cacciare (e, a volte, per trasportare qualcuno in giro).\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187679] = {name = "[q4]Saltatore Ineffabile", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questi taracnidi si muovono con uno scopo sconosciuto agli altri, e rispondono solo a un ordine dall'alto. Di qualsiasi cosa si tratti, sembra che l'assistenza ai mortali che hanno bisogno di un passaggio sia contemplata negli ordini. Per ora.\"\nProfessione:\nSintesi di Protoforma"}
MultiLanguageItemData['it'][187680] = {name = "[q4]Rospo da Guerra Malvagio", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\n[q2]Usa: Ti insegna a evocare un Rospo da Guerra Malvagio.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita: \n[q]\"Queste creature sono così entusiaste di scendere in battaglia che gracidano un qualcosa di molto simile a \"PER L'ORDA!\"\"\nPvP\n: Shadowlands: Stagione 3\nRicompensa stagionale di arene e campi di battaglia classificati."}
MultiLanguageItemData['it'][187681] = {name = "[q4]Rospo da Guerra Malvagio", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare un Rospo da Guerra Malvagio.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita: \n[q]\"Queste creature sono così entusiaste di scendere in battaglia che gracidano un qualcosa di molto simile a \"PER L'ALLEANZA!\"\"\nPvP\n: Shadowlands: Stagione 3\nRicompensa stagionale di arene e campi di battaglia classificati."}
MultiLanguageItemData['it'][187682] = {name = "[q4]Calcamorte Distorto", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Pura energia turbinante contenuta in una forma coesa, si piega solo alla volontà di coloro abbastanza forti da vincolarlo.\"\nImpresa:\nMaestro delle Chiavi di Shadowlands: Stagione 3\nCategoria:\nSpedizioni"}
MultiLanguageItemData['it'][187683] = {name = "[q4]Bufonide Placcato in Oro", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo bufonide corazzato è sempre pronto a saltare in battaglia... ammesso che la battaglia sia davvero, davvero vicina. In caso di bisogno, può saltare numerose volte di fila ed eventualmente arrivare alla battaglia.\"\nProfessione:\nSintesi di Protoforma"}
