MultiLanguageItemData['it'][189624] = {name = "[q4]10.0 Raid Template - Generic - Neck", additional_info = "Si vincola alla raccolta\nCollo\n+100 Tempra\n[q2]+ 85 Celerità\n[q2]+ 246 Maestria\n[q2]Usa: Ammalia la mente di una bestia che si trova all'esterno nelle Terretetre. Quando è affetto, il bersaglio ti aiuta per 5 min. (1 Ora Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189625] = {name = "[q4]10.0 Raid Template - Melee DPS - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 [Agilità o Forza]\n[q2]Usa: Diventa il Predatore Furtivo per 10 s, aumentando la velocità di movimento di 278 e saltando sul successivo nemico entro 8 m, infliggendo 19822 danni fisici. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189626] = {name = "[q4]10.0 Raid Template - Tank - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 [Agilità o Forza]\n[q2]Usa: Stabilisce un Vincolo del Predatore con un bersaglio alleato per 30 s. Il 25% dei danni subiti vengono reindirizzati sull'alleato vincolato, fino a un massimo di [ 58281 * (1 + Versatilità)] danni totali reindirizzati. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189627] = {name = "[q4]10.0 Raid Template - Int DPS - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 Intelletto\n[q2]Usa: Attiva Brucianima, sacrificando fino a 11037 salute in 15 s per potenziare Impeto Fiammeggiante.\n\n Rilanciare Brucianima attiva Impeto Fiammeggiante, infliggendo [ 7884 * (1 + Versatilità)] danni da fuoco suddivisi tra i nemici entro un cono di 40 m e fino al 40% di danni aggiuntivi in base alla durata di Brucianima.\n I danni aumentano per ogni nemico colpito, fino a un massimo di 5 nemici. (Tempo di recupero di 1 min)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189628] = {name = "[q4]10.0 Raid Template - Healer - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 Intelletto\n[q2]Usa: Infondi il tuo alleato con un ciuffo di piume di fenice, curandolo di [ 26603 * (1 + Versatilità)] dopo 6 s, quantità aumentata di massimo il 25% in base alla salute mancante al bersaglio. Se l'alleato subisce danni letali, l'effetto si attiva istantaneamente. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189629] = {name = "[q4]10.0 Raid Template - STR - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 Forza\n[q2]Equipaggia: Le abilità d'attacco hanno un'alta probabilità di infliggere 595 danni fisici, rigenerando salute pari al 300% dei danni inflitti. Se l'effetto fornisce delle sovracure, infligge [ 501 * 5 * (1 + Versatilità)] danni fisici suddivisi tra i nemici vicini in 15 s, ma sopprimendo l'effetto di cura.\n\n I danni aumentano per ogni nemico colpito, fino a un massimo di 5 nemici.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189630] = {name = "[q4]10.0 Raid Template - Omni  - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 [Agilità o Forza o Intelletto]\n[q2]Usa: Secondo uno schema causale, compaiono quattro compagni di ballo. Avvicinarsi a ognuno aumenta l'indice di celerità di 163 e la velocità di movimento di 91 per 20 s. Si accumula. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189631] = {name = "[q4]10.0 Raid Template - Physical DPS - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 [Agilità o Forza]\n[q2]Usa: Le successive 5 abilità d'attacco attivano Psiche Infranta, infliggendo 3330 danni da ombra e aumentando i danni inflitti da Psiche Infranta del 1% per 5 s. Si accumula fino a 25 volte. (1.5s di recupero) (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189632] = {name = "[q4]10.0 Raid Template - AGI - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 Agilità\n[q2]Equipaggia: Quando si ha una percentuale di salute maggiore di quella del bersaglio, le abilità hanno una probabilità molto alta di infliggere [ 925 * (1 + Versatilità)] danni fisici.\n\n Quando si ha una percentuale di salute minore di quella del bersaglio, le abilità hanno una probabilità molto alta di fornire [ 1263 * (1 + Versatilità)] salute.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][189633] = {name = "[q4]10.0 Raid Template - INT - Trinket", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+112 Intelletto\n[q2]Equipaggia: Permette di unirsi al Coro Cremisi. Ogni minuto, l'indice di critico aumenta di ( 158 * 3) in 30 s, poi torna normale. L'effetto aumenta del 5% per ogni membro del Coro Cremisi nel gruppo.\nPrezzo di vendita:"}
