MultiLanguageItemData['it'][190765] = {name = "[q4]Guinzaglio per Rattofauce di Iska", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Rattofauce Colossale.\n[q2]Evoca e congeda un Rattofauce Sputapiaga Colossale.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questi roditori sono diventati delle famigerate sentinelle di Iska, esplorando e portando la sua piaga in tutta la Fauce. La loro presenza è seguita solo dalla rovina.\"\nBottino:\nRhuv, Divoratore della Rovina"}
MultiLanguageItemData['it'][190766] = {name = "[q4]Coda del Rattofauce Spettrale", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Rattofauce Colossale.\n[q2]Evoca e congeda un Rattofauce Spettrale Colossale.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Infuse con le energie delle anime tormentate, queste creature hanno adottato delle abilità spettrali che le rendono molto sfuggenti.\"\nBottino:\nCassa di Rifornimenti dei Giurafauce"}
MultiLanguageItemData['it'][190767] = {name = "[q4]Pterrordattilo Dorato Corazzato", additional_info = "[q7]Si vincola alla Brigata\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\nEvoca e congeda questa cavalcatura, le cui capacità dipendono da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Dipinti e adornati d'oro, questi pterrordattili pattugliano i cieli sopra la tomba di Atal'dazar.\"\nEmporio"}
MultiLanguageItemData['it'][190768] = {name = "[q4]Codice Frattale del Sovrintendente di Zereth", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Enigmatico e distaccato, questo costrutto dei Primi vola su un aggraziato flusso di perfetta comprensione geometrica.\"\nBottino:\nIl Carceriere\nZona:\nSepolcro dei Primi\nDifficoltà:\nMitica"}
MultiLanguageItemData['it'][190769] = {name = "Arcano Instabile", additional_info = "Oggetto di missione\n[q]\"Arcano instabile condensato in una gemma. Sembra sul punto di esplodere da un momento all'altro. Quindi, meglio non scuoterlo troppo.\""}
MultiLanguageItemData['it'][190771] = {name = "[q4]Codice Frattale del Destriero di Zereth Carcinizzato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I pochi esemplari rimasti di queste creature misteriose sembrano essere incredibilmente antichi, quasi senza tempo. Forse sono stati creati dai Primi, poiché non è ancora stato scoperto nessuno schema per sintetizzarli.\"\nMissione:\nMotivazioni scatenanti"}
