MultiLanguageItemData['it'][192478] = {name = "Focus Elementale", additional_info = "Oggetto di missione\n[q]\"Questa gemma vibra di energia elementale concentrata. Sembra che ne voglia altra.\""}
MultiLanguageItemData['it'][192479] = {name = "Focus Elementale", additional_info = "Oggetto di missione\n[q2]Usa: Prosciuga l'energia dai Primalisti sconfitti entro 6 m. (3 S Recupero)\n[q]\"Questa gemma vibra di energia elementale concentrata. Sembra che ne voglia altra.\""}
MultiLanguageItemData['it'][192480] = {name = "Copia di Registro Frammentato", additional_info = "Oggetto di missione\nUnico\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Una copia carbone di una imponente tavoletta piena di rune draconiche.\""}
MultiLanguageItemData['it'][192482] = {name = "Bastone dei Viaggiatori nel Tempo", additional_info = "Oggetto di missione\n[q2]Usa: Strappa il flusso temporale dalla fonte per disattivare la Bolla di Stasi di Bronzo!\nRichiede dal livello 40 al 70 ( 70)"}
MultiLanguageItemData['it'][192485] = {name = "[q3]Dispositivo di Conservazione della Saggezza", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q]\"Contiene la saggezza e le regole della famigerata Ve'nari.\""}
MultiLanguageItemData['it'][192493] = {name = "Granulo di Energia Primordiale", additional_info = "Oggetto di missione\nUnico (10)\n[q]\"A ogni lento impulso di energia, il potere elementale cambia, ricoprendo la pietra con un flusso continuo di luce e temperature che variano rapidamente.\""}
MultiLanguageItemData['it'][192495] = {name = "[q3]NasconDinamo 54 Malfunzionante", additional_info = "Si vincola all'uso\nGiocattolo\n[q2]Usa: Occulta l'utilizzatore in un campo di furtività, permettendogli di muoversi furtivamente senza farsi scoprire. Almeno, è così che dovrebbe funzionare. (5 Min Recupero)\n[q]\"L'invisibilità è per gli scarsi!\""}
MultiLanguageItemData['it'][192496] = {name = "Lancia del Cacciatore Esumato", additional_info = "Oggetto di missione\n[q]\"Questa lancia, che un tempo apparteneva a un potente Cacciatore Shikaar, emana ancora energia necrotica.\""}
MultiLanguageItemData['it'][192523] = {name = "[q3]Proto-Draco Rinnovato: Scaglie Verdi", additional_info = "Manoscritto del Guardadraghi\nSi vincola alla raccolta\nUnico\n[q2]Usa: Sblocca questa opzione di personalizzazione per il Proto-Draco Rinnovato presso il Podio della Trasformazione.\n[q]\"Una pergamena che descrive un potente Proto-Draco dalle vibranti scaglie verdi.\""}
