MultiLanguageItemData['it'][192751] = {name = "[q4]Bruffalo Toccato dalla Tempesta", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\"Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\""}
