MultiLanguageItemData['it'][192753] = {name = "Scaglie d'Ira", additional_info = "Oggetto di missione\n[q]\"Una confutazione selvaggiamente commovente dell'ordine imposto dagli Aspetti e dai loro alleati Titani, raccontata dal punto di vista di un protodraco costretto a ribellarsi dopo essere stato spinto ai margini della società draconica.\""}
MultiLanguageItemData['it'][192754] = {name = "Drachisciotte", additional_info = "Oggetto di missione\n[q]\"La storia di un antico Drago Verde che non riusciva più a distinguere i sogni dalla realtà. Accompagnato da un Dragobestia da tempo sofferente, Drachisciotte si lancia in una missione bizzarra per ripristinare un'immaginaria epoca d'oro.\""}
MultiLanguageItemData['it'][192755] = {name = "Il Signore delle Ali", additional_info = "Oggetto di missione\n[q]\"Un gruppo di dragoidi temprati e draghetti impavidi si riuniscono per distruggere un manufatto dal terribile potere che può essere distrutto solo nelle forge del folle Aspetto che l'ha creato.\""}
MultiLanguageItemData['it'][192756] = {name = "Gli Stormi Rosso e Nero", additional_info = "Oggetto di missione\n[q]\"Un Draco Nero di umili origini non riesce a riconciliare il retaggio militaresco con il suo rispetto per l'intelligenza e l'ingegno, finendo in preda alla disperazione per un amore non corrisposto e il materialismo sconfinato dei dragoidi.\""}
MultiLanguageItemData['it'][192757] = {name = "Orgoglio e Protodrachi", additional_info = "Oggetto di missione\n[q]\"La storia d'amore per eccellenza. Prima dell'arrivo degli Aspetti, un giovane protodraco di belle speranze si imbatte in uno stolto anziano. La sua animosità si trasforma in apprezzamento e, alla fine, l'amore per il loro arrivo.\""}
MultiLanguageItemData['it'][192758] = {name = "Rotolo di Corda Pesante", additional_info = "Oggetto di missione\n[q]\"Una corda pesante per dei dragoidi. Probabilmente tu potresti trasportare dei macigni con un solo rotolo.\""}
MultiLanguageItemData['it'][192759] = {name = "Lancia dei Giuramagma", additional_info = "Oggetto di missione\n[q]\"Puntala verso il nemico e muoviti con dei rapidi affondi.\""}
MultiLanguageItemData['it'][192761] = {name = "[q4]Svolazzina Addomesticata", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 25 con la Spedizione delle Scaglie di Drago.\n\n\n[q]\"Nonno Baffetto non ha impiegato molto ad addomesticare le svolazzine attorno al Campo delle Scaglie di Drago e ordinare loro di aiutare a spostare il personale della spedizione con tanto di carico.\"\nFazione:\nSpedizione delle Scaglie di Drago\nFama:\n25\nMercante:\nNonno Baffetto\nPosizione:\nCampo delle Scaglie di Drago"}
MultiLanguageItemData['it'][192762] = {name = "[q4]Svolazzina Azzurra", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 25 con la Spedizione delle Scaglie di Drago.\n\n\n[q]\"Una volta che Nonno Baffetto ha insegnato loro come comportarsi coi propri fantini le Svolazzine Azzurre si sono dimostrate fedeli ai loro proprietari.\"\nFazione:\nSpedizione delle Scaglie di Drago\nFama:\n25\nMercante:\nNonno Baffetto\nPosizione:\nCampo delle Scaglie di Drago\nCosto:\n5\n20\n750"}
MultiLanguageItemData['it'][192764] = {name = "[q4]Svolazzina Verdeggiante", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Le Svolazzine Verdeggianti sono la cavalcatura perfetta per gli esploratori della Spedizione delle Scaglie di Drago, essendo rapide e in grado di mischiarsi tra la flora delle Isole dei Draghi.\"\nFazione:\nSpedizione delle Scaglie di Drago\nFama\n25\nTesoro:\nPacchetto da Esploratore della Spedizione"}
MultiLanguageItemData['it'][192765] = {name = "[q4]Sfiorasabbia Insigne", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un dono da parte di Nonno Baffetto, queste svolazzine capricciose aiutano i Viaggiatori nel Tempo a ripulire calamità temporali legate alla sabbia presenti e future.\"\nImpresa:\nÈ ora di chiudere\nCategoria:\nEsplorazione"}
MultiLanguageItemData['it'][192766] = {name = "[q4]Svolazzina d'Ambra", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un dono da parte di Nonno Baffetto per l'Emporio, le svolazzine d'ambra sono estremamente docili.\"\nEmporio"}
