MultiLanguageItemData['it'][192772] = {name = "[q4]Salamantera Antica", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"A causa della loro predilezione per le caverne oscure e le acque torbide, gli avvistamenti di questa rara razza di salamantera sono così rari che molti ricercatori le pensavano estinte.\"\nBottino:\nIsola Proibita"}
MultiLanguageItemData['it'][192774] = {name = "[q4]Salamantera Corallina", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Col placarsi delle tempeste di Raszageth, questa razza acquatica di salamantere è tra le molte meraviglie che si sono sistemate tra le coste.\"\nImpresa:\nNella tempesta\nCategoria:\nEsplorazione"}
MultiLanguageItemData['it'][192775] = {name = "[q4]Salamantera Scagliatuono", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"A volte, quando l'energia della tempesta infonde una creatura, questa diventa... semplicemente più grande e serena. Poche salamantere sono disposte a farsi cavalcare, ma questi cuccioli della tempesta sono una notevole eccezione.\"\nMercante:\nMythressa\nCosto:\n2.000"}
MultiLanguageItemData['it'][192776] = {name = "Tizzocono Dormiente", additional_info = "Oggetto di missione\n[q]\"Questo seme è caldo al tocco, e contenente abbastanza energia da crescere fino a raggiungere altezze vertiginose.\""}
MultiLanguageItemData['it'][192777] = {name = "[q4]Gusciomagma", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Chi è una lumachina nuova tutta fatta di lava elementale? Tu! Sì, tu!\"\nOggetto:\nGuscio di Magma Vuoto\nZona:\nSponde del Risveglio"}
MultiLanguageItemData['it'][192779] = {name = "[q4]Lumacone Ribollente", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Attirato fuori dal suo abisso dalla rabbia degli Zaqali.\"\nTesoro:\nCassa Ribollente\nZona:\nCaverna di Zaralek"}
