MultiLanguageItemData['it'][192784] = {name = "[q4]Gusciack", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Nutrita dalla vittoria e indurita dalla gloria, questa lumaca non è che un tributo alla maestria.\"\nImpresa:\nGloria all'Eroe di Dragonflight"}
MultiLanguageItemData['it'][192785] = {name = "[q4]Lumaca Elementale Appiccicosa", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Formatosi con gli avanzi delle energie elementali delle Tempeste Primordiali, questo mollusco magico è più veloce di quanto sembri.\"\nBottino:\nIsola Proibita"}
MultiLanguageItemData['it'][192786] = {name = "[q4]Conchiglia di Lumaca di Mondo Addormentata", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Per i Devastamondi, un semplice poggiapiedi. Per te, una cavalcatura potente.\"\nMercante:\nFornitore Vexil\nZona:\nSponde del Risveglio\nCosto:\n1.000"}
MultiLanguageItemData['it'][192788] = {name = "[q4]Mammut da Pesca Insigne", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un dono da parte dell'Esploratrice Tomul, così che i banchetti di Iskaara abbiano sempre abbastanza pesce da sfamare coloro che ne hanno bisogno.\"\nImpresa:\nNon si combatte a stomaco vuoto\nCategoria:\nEsplorazione"}
MultiLanguageItemData['it'][192790] = {name = "[q4]Mammut Muscoso", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Conservandolo per migliaia di anni nella pietra, la magia di bronzo ha invecchiato questo mammut fino a renderlo quasi un fossile.\"\nBottino:\nCripte di Zskera"}
MultiLanguageItemData['it'][192791] = {name = "[q4]Portatore Calcapianure", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I mammut delle Pianure di Ohn'ahra non sono abituati a trasportare persone, dato che i Centauri loro vicini non sono soliti adottare cavalcature. Tuttavia, possono imparare a trasportare gli altri e alcuni addirittura lo fanno con entusiasmo.\"\nEventi mondiali:\nCacce dei Centauri (prima caccia di ogni settimana)"}
MultiLanguageItemData['it'][192792] = {name = "[q4]Capobranco degli Spinatonante Insigne", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un dono da parte di Merithra, che ha benedetto questi spinatonante per assicurarsi che i clan dei Maruuk vaghino sempre sotto la protezione dello Stormo dei Draghi Verdi, a prescindere dalla loro meta.\"\nImpresa:\nAl centauro dell'attenzione\nCategoria:\nEsplorazione"}
