MultiLanguageItemData['it'][194299] = {name = "[q4]Decorazione di Fiamma", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+351 [Agilità o Forza]\n[q2]Usa: Colpisce il terreno, scatenando delle fiamme che si irradiano dalla posizione, infliggendo 30948 danni da fuoco suddivisi tra i nemici colpiti e fornendo uno scudo che assorbe 57788 danni subiti per 30 s. Dopo alcuni istanti, le fiamme tornano indietro, infliggendo gli stessi danni e rinnovando lo scudo.\n\n I danni e l'effetto di assorbimento sono aumentati per ogni nemico colpito, fino a un massimo di 5 nemici. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194300] = {name = "[q4]Globo di Gelo Evocato", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+351 Intelletto\n[q2]Usa: Se hai più del 65% del mana massimo, lancia il Globo di Gelo al bersaglio, infliggendo 55707 danni da gelo.\n\n Se hai meno del 65% del mana massimo, bevi dal Globo di Gelo per rigenerare 4523 mana istantaneamente. (1 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194301] = {name = "[q4]Icona dell'Incarnazione Sussurrante", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+371 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Soccombere ai sussurri dell'icona rende Infusi di Gelo , aumentando l'indice di critico di 478 .\n\n Combattere insieme ad altri alleati Infusi di Terra o Fuoco ha una probabilità di fornirti 131 della loro statistica di infusione per 12 s.\n\n Infusione in base alla specializzazione attuale. (1.5s di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194302] = {name = "[q4]Dono della Mangiatempeste", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+371 [Agilità o Forza]\n[q2]Usa: Accettare la tempesta trasforma in un Elementale dell'Aria Primordiale, immobilizzando sul posto per 10 s.\n\n In questa forma, i venti tutt'intorno infliggono 6309 danni da natura ogni secondo a tutti i nemici entro 10 m, danni che si intensificano del 10% ogni secondo finché la trasformazione non si placa. (3 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194303] = {name = "[q4]Rubino Tremante", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+351 Forza\n[q2]Equipaggia: Gli attacchi generano Forza Concussiva, fornendo 21 potenza d'attacco per accumulo.\n\n Al raggiungimento di 10 accumuli, le successive 3 abilità in mischia emettono un'onda d'urto frontale, infliggendo 16542 danni da natura aggiuntivi a tutti i nemici lungo una linea. Le onde d'urto infliggono danni aggiuntivi ai nemici con salute alta. (500ms di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194304] = {name = "[q4]Trappola Mortale di Brinarossa", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+351 Intelletto\n[q2]Usa: Infligge 40232 danni da gelo al bersaglio, intrappolando lui e tutti i nemici in una Ragnatela Cristallina per 15 s.I nemici all'interno hanno una velocità di movimento ridotta del 15% e subiscono 3185 danni da gelo quando un nemico all'interno viene colpito.\n\n Danni aumentati per ogni nemico intrappolato, fino a un massimo di 5. Danni per bersaglio ridotti oltre i 5 nemici. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194305] = {name = "[q4]Tecnica della Corrente Controllata", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+371 Agilità\n[q2]Equipaggia: I colpi critici hanno una probabilità di creare Elettricità Statica, aumentando la velocità d'attacco del 2% per accumulo. L'effetto può verificarsi solo una volta ogni 1 s. Al raggiungimento di 10 accumuli, l'elettricità si impenna, aumentando la velocità di movimento del 30% per 12 s. Durante il picco, gli attacchi automatici folgorano il bersaglio e 1 nemico vicino, infliggendo 6470 danni da natura.\n\n Al termine dell'effetto, si viene ancorati al terreno per 1 min e non è possibile generare Elettricità Statica. (1.5s di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194306] = {name = "[q4]Totem Totale del Maestro", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+371 [Agilità o Forza]\n[q2]Equipaggia: Assume una Postura Elementale. Schivare o parare un attacco scatena un potente Contrattacco Elementale contro i nemici frontali, permettendo poi di assumere la postura successiva.\n\n Può attivarsi solo una volta ogni 30 s. (30s di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194307] = {name = "[q4]Promessa della Custode della Progenie", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+382 Intelletto\n[q2]Usa: Indica un altro personaggio a cui legarti, diventandone il Guardiano per 1 ora.\n\n Finché siete legati, il vostro indice di versatilità aumenta di [ 94 * (0.8)] e rigenerate [ 964 * (0.6)] salute ogni secondo. Se vi trovate a meno di 15 m di distanza, i bonus aumentano.\n\nValido solo per le specializzazioni da guaritore. (5 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194308] = {name = "[q4]Fiocaluce Frenetica", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+382 [Agilità o Forza]\n[q2]Usa: Canalizza per 2 s, scatenando una furiosa raffica di fiamme attorno al bersaglio, infliggendo [ 20285 * (8) * (1 + Versatilità)] danni da fuoco al bersaglio con la probabilità di infliggere danni aggiuntivi ai nemici vicini.\n\n Se un personaggio alleato muore, il tempo di recupero si riduce di 90 s. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194309] = {name = "[q4]Tempesta Adirata", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+382 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Gli incantesimi e le abilità permettono di accumulare Perfidia. Al raggiungimento di 5 accumuli, un Dardo della Tempesta Adirato si sposta sul bersaglio attuale, infliggendo [ 1828 * (6) * (1 + Versatilità)] danni da natura in 3 s.\n\n Al termine, il dardo torna indietro, aumentando gli accumuli di Perfidia necessari per il lancio di 1 e aumentando in modo permanente i danni inflitti da Dardo della Tempesta Adirato, finché uno muore. (1s di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][194310] = {name = "[q4]Codice dell'Invocatore Disperato", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+382 Intelletto\n[q2]Equipaggia: Lanciare incantesimi fornisce accumuli di Odio, riducendo permanentemente il tempo di recupero di questo monile di 1 s fino al termine del combattimento. L'effetto si accumula fino a 180 volte. (1s di recupero)\n[q2]Usa: Scatena una pericolosa corrente di fulmini, infliggendo 125328 danni da natura al bersaglio e 665 danni da natura a se stessi. I danni inflitti a se stessi aumentano in base agli accumuli di Odio. (4 Min Recupero)\nPrezzo di vendita:"}
