MultiLanguageItemData['it'][194512] = {name = "Dispositivo Arcano Rotto", additional_info = "Oggetto di missione\n[q]\"C'è ancora un po' di magia arcana che sprizza fuori da questo pezzo del dispositivo.\""}
MultiLanguageItemData['it'][194513] = {name = "Collezione di Tomi", additional_info = "Oggetto di missione\n[q]\"Questi tomi raccontano la storia di ciò che era l'Accampamento Antonidas 10.000 anni fa.\""}
MultiLanguageItemData['it'][194514] = {name = "Lista degli Ospiti Antiquata", additional_info = "Oggetto di missione\n[q]\"Questo vecchio tomo contiene i nomi dei draghi che frequentavano quest'area. Due nomi sono presenti quasi su ogni pagina: Malygos e Sindragosa.\""}
MultiLanguageItemData['it'][194515] = {name = "Pianificatore di Eventi Sgretolato", additional_info = "Oggetto di missione\n[q]\"Questo libro descrive diversi eventi avvenuti in questa zona. Tutti sembravano coinvolgere manifestazioni arcane per mostrare altri stormi e aspetti dei draghi.\""}
MultiLanguageItemData['it'][194516] = {name = "Diario Invecchiato", additional_info = "Oggetto di missione\n[q]\"Queste pagine includono dei dettagli sul corteggiamento tra due Draghi Blu, Malygos e Sindragosa. Una nota dice che è \"parte una di una serie\".\""}
MultiLanguageItemData['it'][194517] = {name = "Testi Rotti", additional_info = "Oggetto di missione\n[q]\"Questo libro descrive i draconidi e le dragobestie che si sono occupati di quest'area dopo la partenza dei Draghi Blu. In molte pagine si lamenta la mancanza della \"gioia\", provocata dall'assenza di Sindragosa e Malygos.\""}
MultiLanguageItemData['it'][194519] = {name = "Aiuto di Osoria", additional_info = "Oggetto di missione\n[q2]Usa: Richiama Osoria perché ti sollevi in volo e attacchi i nemici. Funziona solo nella Cittadella d'Ossidiana. (5 S Recupero)\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][194520] = {name = "Pergamena della Conoscenza dei Viaggiatori nel Tempo", additional_info = "Oggetto di missione\n[q]\"La pergamena contiene una vasta conoscenza della magia del tempo. Percepisci la tua mente incurvarsi, se fissi la cartapecora troppo a lungo.\""}
MultiLanguageItemData['it'][194521] = {name = "[q4]Dracobrado della Rupe", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Dracobrado della Rupe cavalcabile.\n\n Questa cavalcatura può usare Viaggio in Compagnia.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Questi esemplari, che spesso si annidano lungo le pareti impervie di Thaldraszus, sono velocissimi, soprattutto in caso di pericolo.\"\nImpresa:\nIsole dei Draghi: Dracobrado della Rupe"}
