MultiLanguageItemData['it'][198070] = {name = "Fibra Marina Lacera", additional_info = "Materiale per Equipaggiamento da Pesca di Iskaara\nSi vincola alla raccolta\nUnico\n\"Il Pescatore Tinnak era eccezionalmente bravo a tessere le corde degli arpioni. Purtroppo, è scomparso tempo fa. È stato visto l'ultima volta nelle Terre Gelide Superiori, non lontano dall'Accampamento Antonidas. Da portare a Tavio a Iskaara.\""}
MultiLanguageItemData['it'][198071] = {name = "[q3]Osso Intagliato delle Fiamme", additional_info = "Si vincola alla raccolta\nQuesto oggetto avvia una missione\n[q]\"Rune dei Djaradin ricoprono quest'osso.\""}
MultiLanguageItemData['it'][198072] = {name = "[q3]Dente di Drago con Bande Dorate", additional_info = "Si vincola alla raccolta\nQuesto oggetto avvia una missione\n[q]\"Ciò che resta di un drago caduto.\""}
MultiLanguageItemData['it'][198073] = {name = "Karha, il Vento Sereno", additional_info = "Oggetto di missione\nUnico\n[q]\"Karha era il bastone di Ganmat il Saggio, un Saggio del Vento di Ohn'ahra che secoli fa ha curato innumerevoli alleati e sconfitto ancora più nemici.\""}
MultiLanguageItemData['it'][198074] = {name = "Josanak, la Vittoria Certa", additional_info = "Oggetto di missione\nUnico\n[q]\"Josanak apparteneva al guerriero mai sconfitto Zaphiil. Zaphiil si affidava sempre alla sua alabarda, così come il suo clan si affidava sempre a lui.\""}
MultiLanguageItemData['it'][198075] = {name = "Tsegzaya, l'Arco di Rovi", additional_info = "Oggetto di missione\nUnico\n[q]\"Innumerevoli frecce scagliate da Tsegzaya hanno raggiunto l'obiettivo, che si trattasse di selvaggina o dei nemici del Clan Teerai, quando era Dihar a tendere l'arco.\""}
MultiLanguageItemData['it'][198076] = {name = "[q2]Nebulizzatore Disinfestante", additional_info = "Si vincola alla raccolta\n[q2]Usa: Lancia un Nebulizzatore Disinfestante che genera un'esplosione velenosa, infliggendo 15 danni da natura a tutti i nemici entro 6 m, respingendoli indietro e riducendone la velocità di movimento del 30% per 8 s.\n\n L'effetto di respinta è più efficace contro i personaggi nemici."}
MultiLanguageItemData['it'][198078] = {name = "Elenco di Reclutamento", additional_info = "Oggetto di missione\nRichiede dal livello 20 al 70 ( 70)\n[q]\"Pagine piene di strategie di reclutamento e istruzioni per trovare un manufatto presso le Rovine di Nelthazan.\""}
MultiLanguageItemData['it'][198079] = {name = "Ordini di Sarkareth", additional_info = "Oggetto di missione\nRichiede dal livello 20 al 70 ( 70)\n[q]\"Gli Aspetti sono complici dei crimini del Distruttore. Trovate le prove dei loro tentativi di controllarci. Parlate! Resistete! - Comandante delle Scaglie Sarkareth\""}
MultiLanguageItemData['it'][198080] = {name = "[q3]Sigillo delle Tempeste", additional_info = "Si vincola alla raccolta\nQuesto oggetto avvia una missione\n[q]\"I segni illeggibili e la temperatura fluttuante del sigillo lo rendono un ritrovamento molto interessante.\""}
MultiLanguageItemData['it'][198081] = {name = "[q2]Talismano dell'Assistente", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+382 Intelletto\n[q2]Usa: Concentra l'occhio vigile sul bersaglio, fornendo un'alta probabilità di curarlo di 1847 quando riceve cure nei successivi 30 s. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198082] = {name = "Mucchio di Rocce Presenzienti", additional_info = "[q]\"Resta solo un accenno inconsistente di coscienza elementale.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198083] = {name = "[q3]Kit di Forniture per la Spedizione", additional_info = "[q7]Si vincola alla Brigata\nUnico\n[q2]Usa: Permette di accedere al Kit di Forniture per la Spedizione. Usa i Rifornimenti delle Isole dei Draghi per potenziare le tue abilità d'esplorazione, di arrampicata e di catalogazione.\nRichiede il livello di Fama 6 con la Spedizione delle Scaglie di Drago.[q]\"Questo kit è una ricompensa per aver ottenuto Fama con la Spedizione delle Scaglie di Drago.\""}
MultiLanguageItemData['it'][198085] = {name = "[q3]Chiave della Cassa d'Ossidiana Perduta", additional_info = "Si vincola alla raccolta\n[q]\"La chiave della Cassa d'Ossidiana Perduta.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198086] = {name = "[q4]Mazzo dell'Inferno di Lunacupa", additional_info = "Si vincola all'equipaggiamento\nUnico equipaggiabile: Mazzo di Lunacupa (1)\nMonile\n+300 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Equipaggia: mischia di tanto in tanto il mazzo, mentre si è in combattimento.\n[q2]Usa: Usa: lancia un Inferno Infuocato contro il bersaglio, infliggendo ( 78083 * .3)- 78083 danni da fuoco. I danni inflitti sono determinati dalla carta in cima al mazzo. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198087] = {name = "[q4]Mazzo della Brina di Lunacupa", additional_info = "Si vincola all'equipaggiamento\nUnico equipaggiabile: Mazzo di Lunacupa (1)\nMonile\n+300 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Equipaggia: mischia di tanto in tanto il mazzo, mentre si è in combattimento.\n[q2]Usa: Usa: infligge 15897 danni da gelo e applica Brina del Risveglio al bersaglio per 4-12 s. Se il bersaglio muore mentre Brina del Risveglio è attiva, esplode, infliggendo 39743 danni da gelo suddivisi tra i nemici in un raggio di 10 m. La durata è determinata dalla carta in cima al mazzo. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198088] = {name = "[q4]Mazzo della Danza di Lunacupa", additional_info = "Si vincola all'equipaggiamento\nUnico equipaggiabile: Mazzo di Lunacupa (1)\nMonile\n+300 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Equipaggia: mischia di tanto in tanto il mazzo, mentre si è in combattimento.\n[q2]Usa: Usa: richiama una Danza Rinfrescante che rimbalza 6-13 volte tra gli alleati e i nemici entro 25 m, infliggendo 9545 danni da natura o fornendo 5200 cure. Il numero di salti è determinato dalla carta in cima al mazzo. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198089] = {name = "[q4]Mazzo del Guardiano di Lunacupa", additional_info = "Si vincola all'equipaggiamento\nUnico equipaggiabile: Mazzo di Lunacupa (1)\nMonile\n+300 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Equipaggia: mischia di tanto in tanto il mazzo, mentre si è in combattimento.\n[q2]Usa: Usa: fornisce la Benedizione del Guardiano per 5-12 s e uno scudo che assorbe 62801 danni subiti.\n Se lo scudo si esaurisce mentre Benedizione del Guardiano è attiva, aumenta l'indice di versatilità di 1469 per la durata corrispondente. La durata è determinata dalla carta in cima al mazzo. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
