MultiLanguageItemData['it'][198477] = {name = "[q4]Scatola del Mazzo della Brina di Lunacupa", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Mazzo di Lunacupa (1)\nMonile\n+244 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Equipaggia: mischia di tanto in tanto il mazzo, mentre si è in combattimento.\n[q2]Usa: Usa: infligge 10372 danni da gelo e applica Brina del Risveglio al bersaglio per 4-12 s. Se il bersaglio muore mentre Brina del Risveglio è attiva, esplode, infliggendo 25929 danni da gelo suddivisi tra i nemici in un raggio di 10 m. La durata è determinata dalla carta in cima al mazzo. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198478] = {name = "[q4]Scatola del Mazzo della Danza di Lunacupa", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Mazzo di Lunacupa (1)\nMonile\n+244 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Equipaggia: mischia di tanto in tanto il mazzo, mentre si è in combattimento.\n[q2]Usa: Usa: richiama una Danza Rinfrescante che rimbalza 6-13 volte tra gli alleati e i nemici entro 25 m, infliggendo 6228 danni da natura o fornendo 4133 cure. Il numero di salti è determinato dalla carta in cima al mazzo. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198479] = {name = "Aliante della Burrasca", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Usi l'aliante per ridurre la velocità di caduta per 2 min. Funziona solo a Kul Tiras. (3 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198480] = {name = "Pozze Splendenti", additional_info = "Oggetto di missione\n[q]\"Questo dipinto a metà che rappresenta le Pozze della Vita comprende una delicata tavolozza di rosa, rubino e verde.\""}
MultiLanguageItemData['it'][198481] = {name = "[q4]Scatola del Mazzo del Guardiano di Lunacupa", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Mazzo di Lunacupa (1)\nMonile\n+244 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Equipaggia: mischia di tanto in tanto il mazzo, mentre si è in combattimento.\n[q2]Usa: Usa: fornisce la Benedizione del Guardiano per 5-12 s e uno scudo che assorbe 51162 danni subiti.\n Se lo scudo si esaurisce mentre Benedizione del Guardiano è attiva, aumenta l'indice di versatilità di 1230 per la durata corrispondente. La durata è determinata dalla carta in cima al mazzo. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][198482] = {name = "Spirale dei Kargan", additional_info = "Oggetto di missione\n[q]\"In questo dipinto delle Pianure di Ohn'ahra, bianche spirali avvolgono verdi colline mentre i venti soffiano tra gli alberi.\""}
