MultiLanguageItemData['it'][198871] = {name = "[q4]Lontruk del Commerciante Iskaara", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Non ci sono certezze quando acquisti una lontruk da Tattukiaka. Almeno sono carine.\"\nMercante:\nTattukiaka\nZona:\nVastità Azzurra\nCosto:\n1\n1"}
MultiLanguageItemData['it'][198872] = {name = "[q4]Lontruk da Ricognizione Marrone", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 25 con i Tuskarr di Iskaara.\n\n\n[q]\"Le lontruk, notoriamente giocose nel loro habitat naturale, possiedono uno sguardo acuto in grado di scandagliare in lontananza in cerca di predatori.\"\nFazione:\nTuskarr di Iskaara\nFama:\n25\nMercante:\nTatto\nPosizione:\nIskaara\nCosto:\n2\n2\n750"}
